ROUTE_DECISION_FORM_PATHS = tuple(path for path, _label, _options in ROUTE_DECISION_FORM_FIELDS)
ROUTE_DECISION_REQUIRED_FORM_PATHS = frozenset(
    path for path in (*COMMON_REQUIRED_FIELDS, *READY_REQUIRED_FIELDS) if path in ROUTE_DECISION_FORM_PATHS
)


def nested_get(data: dict, path: str, default: Any = "") -> Any:
    current: Any = data
    for part in path.split("."):
        if isinstance(current, dict) and part in current:
            current = current[part]
        else:
            return default
    return current


def nested_set(data: dict, path: str, value: Any) -> None:
    current: Any = data
    parts = path.split(".")
    for part in parts[:-1]:
        if not isinstance(current.get(part), dict):
            current[part] = {}
        current = current[part]
    current[parts[-1]] = value


def route_decision_form_values(data: dict) -> dict[str, str]:
    values = {}
    for path, _label, _options in ROUTE_DECISION_FORM_FIELDS:
        value = nested_get(data, path, "")
        if path == "decision.open_blockers":
            if isinstance(value, list):
                values[path] = "; ".join(str(item).strip() for item in value if str(item).strip())
            else:
                values[path] = str(value or "")
        elif path == "bench.device_ids" and isinstance(value, list):
            values[path] = ", ".join(str(item).strip() for item in value if str(item).strip())
        elif isinstance(value, bool):
            values[path] = "true" if value else "false"
        elif value is None:
            values[path] = ""
        else:
            values[path] = str(value)
    return values


def apply_route_decision_form_values(data: dict, values: dict[str, str]) -> dict:
    for path, raw_value in values.items():
        text = str(raw_value).strip()
        if path == "decision.allowed_to_run_p1":
            nested_set(data, path, text.lower() in {"true", "yes", "y", "1", "pass", "allow", "allowed"})
        elif path == "decision.open_blockers":
            normalized = text.replace("\r", "\n").replace(";", "\n")
            blockers = [item.strip() for item in normalized.split("\n") if item.strip()]
            nested_set(data, path, blockers)
        elif path == "bench.device_ids":
            devices = [item.strip() for item in text.split(",") if item.strip()]
            nested_set(data, path, devices)
            if devices and not str(nested_get(data, "bench.device_id", "")).strip():
                nested_set(data, "bench.device_id", devices[0])
        else:
            nested_set(data, path, text)
    return data


def route_decision_form_issues(data: dict) -> dict[str, str]:
    values = route_decision_form_values(data)
    issues: dict[str, str] = {}
    for path, text in values.items():
        stripped = text.strip()
        if path in ROUTE_DECISION_REQUIRED_FORM_PATHS and not stripped:
            issues[path] = "missing"
            continue
        if stripped and _route_form_has_placeholder(stripped):
            issues[path] = "placeholder"

    allowed = values.get("decision.allowed_to_run_p1", "").strip().lower()
    if allowed not in {"true", "yes", "y", "1", "pass", "allow", "allowed"}:
        issues["decision.allowed_to_run_p1"] = "not allowed"

    blockers = values.get("decision.open_blockers", "").strip()
    if blockers:
        if _route_form_has_placeholder(blockers):
            issues["decision.open_blockers"] = "placeholder"
        else:
            issues["decision.open_blockers"] = "open blocker"
    return issues


def route_decision_issue_rows(data: dict) -> list[dict[str, str]]:
    values = route_decision_form_values(data)
    issues = route_decision_form_issues(data)
    rows = []
    for path, label, _options in ROUTE_DECISION_FORM_FIELDS:
        issue = issues.get(path, "")
        if not issue:
            continue
        rows.append({
            "path": path,
            "label": label,
            "issue": issue,
            "value": values.get(path, ""),
            "action": _route_issue_action(issue),
        })
    return rows


def route_decision_issue_brief(data: dict) -> str:
    rows = route_decision_issue_rows(data)
    counts: dict[str, int] = {}
    for row in rows:
        counts[row["issue"]] = counts.get(row["issue"], 0) + 1
    count_text = ", ".join(f"{key}={value}" for key, value in sorted(counts.items())) or "none"
    return f"Route checklist: issues={len(rows)}; {count_text}"


def write_route_decision_issue_markdown(data: dict, path: str | Path) -> Path:
    rows = route_decision_issue_rows(data)
    out_path = Path(path)
    lines = [
        "# Route Decision Fill Checklist",
        "",
        f"- Run ID: `{data.get('run_id', '')}`",
        f"- Target: `{str(data.get('target_stage', 'p1') or 'p1').upper()}`",
        f"- Issue count: `{len(rows)}`",
        "- Real iOS control verified: `False`",
        "",
        "This checklist is for filling the route decision record only. It does not write evidence and does not prove AirPlay, HID, screenshots, or real iPhone response.",
        "",
        "## Items",
        "",
        "| Field | Issue | Current value | Action |",
        "|---|---|---|---|",
    ]
    if rows:
        for row in rows:
            value = row["value"].replace("|", "\\|")
            lines.append(f"| `{row['path']}` | {row['issue']} | `{value}` | {row['action']} |")
    else:
        lines.append("| None | none |  | Route form has no GUI-detected issue. Run Validate before real testing. |")
    lines.extend([
        "",
        "## Next Step",
        "",
        "After every item is cleared, use GUI `Validate` or `python -m imouse.route_decision validate --require-ready`.",
        "If validation fails and is recorded into evidence, treat that run_id as blocked and start a fresh run_id after fixing blockers.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


def route_decision_metadata_prefill_values(
    *,
    device_ids: list[str],
    receiver_provider: str,
    capture_method: str,
    hid_provider: str,
    hid_id: str,
    serial_port: str,
    iphone_id: str,
    ios_version: str,
    receiver_name: str = "",
    receiver_version: str = "",
) -> dict[str, str]:
    cleaned_devices = [str(item).strip() for item in device_ids if str(item).strip()]
    values = {
        "receiver.route": _normalize_receiver_route(receiver_provider),
        "receiver.name": receiver_name.strip(),
        "receiver.version": receiver_version.strip(),
        "receiver.capture_method": capture_method.strip(),
        "hid.route": _normalize_hid_route(hid_provider),
        "hid.provider": hid_provider.strip(),
        "hid.id": hid_id.strip(),
        "hid.serial_port": serial_port.strip(),
        "iphone.id": iphone_id.strip(),
        "iphone.ios_version": ios_version.strip(),
    }
    if cleaned_devices:
        values["bench.device_id"] = cleaned_devices[0]
        values["bench.device_ids"] = ", ".join(cleaned_devices)
    return {key: value for key, value in values.items() if value}


def _route_form_has_placeholder(text: str) -> bool:
    lowered = text.lower()
    return any(token and str(token).lower() in lowered for token in DEFAULT_PLACEHOLDERS)


def _route_issue_action(issue: str) -> str:
    if issue == "missing":
        return "Fill the real bench value before route validation."
    if issue == "placeholder":
        return "Replace placeholder text with a real receiver/HID/iPhone/bench value."
    if issue == "not allowed":
        return "Set Allow P1 real run to true only after receiver, HID, iPhone, and bench are ready."
    if issue == "open blocker":
        return "Resolve the blocker or keep the run stopped."
    return "Review this field before validation."


def _normalize_receiver_route(value: str) -> str:
    text = value.strip()
    lowered = text.lower()
    if lowered in {"uxplay", "windows_receiver", "wired", "capture_card"}:
        return lowered
    if "windows" in lowered:
        return "windows_receiver"
    if "capture_card" in lowered or "capture card" in lowered:
        return "capture_card"
    if "wired" in lowered:
        return "wired"
    return text


def _normalize_hid_route(value: str) -> str:
    text = value.strip()
    lowered = text.lower()
    if lowered in {"ch9329", "xp_hardware", "self_built", "bluetooth"}:
        return lowered
    if "xp" in lowered:
        return "xp_hardware"
    if "self" in lowered:
        return "self_built"
    return text


def fit_image_to_canvas(image_width: int, image_height: int,
                        canvas_width: int, canvas_height: int) -> tuple[float, int, int, int, int]:
    """Return scale, display width/height, and x/y offsets for centered preview."""
    if image_width <= 0 or image_height <= 0 or canvas_width <= 0 or canvas_height <= 0:
        return 1.0, 0, 0, 0, 0
    scale = min(canvas_width / image_width, canvas_height / image_height)
    display_width = max(1, int(image_width * scale))
    display_height = max(1, int(image_height * scale))
    offset_x = max(0, int((canvas_width - display_width) / 2))
    offset_y = max(0, int((canvas_height - display_height) / 2))
    return scale, display_width, display_height, offset_x, offset_y


def canvas_to_image_point(canvas_x: int, canvas_y: int,
                          image_width: int, image_height: int,
                          canvas_width: int, canvas_height: int) -> Optional[tuple[int, int]]:
    """Map a canvas click to original image coordinates."""
    scale, display_width, display_height, offset_x, offset_y = fit_image_to_canvas(
        image_width,
        image_height,
        canvas_width,
        canvas_height,
    )
    if display_width <= 0 or display_height <= 0:
        return None
    if not (offset_x <= canvas_x < offset_x + display_width):
        return None
    if not (offset_y <= canvas_y < offset_y + display_height):
        return None
    image_x = int((canvas_x - offset_x) / scale)
    image_y = int((canvas_y - offset_y) / scale)
    image_x = max(0, min(image_width - 1, image_x))
    image_y = max(0, min(image_height - 1, image_y))
    return image_x, image_y


def canvas_rect_to_image_rect(x1: int, y1: int, x2: int, y2: int,
                              image_width: int, image_height: int,
                              canvas_width: int, canvas_height: int) -> Optional[tuple[int, int, int, int]]:
    """Map a canvas drag rectangle to an image-space (x, y, w, h)."""
    p1 = canvas_to_image_point(x1, y1, image_width, image_height, canvas_width, canvas_height)
    p2 = canvas_to_image_point(x2, y2, image_width, image_height, canvas_width, canvas_height)
    if p1 is None or p2 is None:
        return None
    left = min(p1[0], p2[0])
    top = min(p1[1], p2[1])
    right = max(p1[0], p2[0])
    bottom = max(p1[1], p2[1])
    width = right - left + 1
    height = bottom - top + 1
    if width < 2 or height < 2:
        return None
    return left, top, width, height


def doctor_brief(report: dict) -> str:
    """Return one-line status text for a doctor report."""
    counts = report.get("counts", {})
    return (
        f"Doctor {report.get('overall', 'unknown')}: "
        f"ok={counts.get('ok', 0)}, warn={counts.get('warn', 0)}, fail={counts.get('fail', 0)}"
    )


def _doctor_allows_real_run(report: dict) -> bool:
    """Return whether Doctor has no hard fail for a guarded real run."""
    overall = str(report.get("overall", "") or "").lower()
    counts = report.get("counts", {}) if isinstance(report.get("counts"), dict) else {}
    try:
        fail_count = int(counts.get("fail", 0) or 0)
    except (TypeError, ValueError):
        fail_count = 0
    return fail_count == 0 and overall in {"ok", "warn"}


def scenario_brief(summary: dict) -> str:
    """Return one-line status text for a script scenario summary."""
    status = "ok" if summary.get("ok") else "fail"
    return (
        f"Scenario {status}: "
        f"total={summary.get('total', 0)}, "
        f"pass={summary.get('success_count', 0)}, "
        f"fail={summary.get('failure_count', 0)}"
    )


def evidence_review_brief(summary: dict) -> str:
    """Return one-line status text for a field evidence review."""
    by_status = summary.get("by_status", {})
    categories = summary.get("by_failure_category", {})
    metrics = summary.get("metrics", {})
    category_text = ", ".join(
        f"{category}={count}" for category, count in sorted(categories.items()) if count
    )
    if not category_text:
        category_text = "none"
    elif len(category_text) > 90:
        category_text = category_text[:87] + "..."
    return (
        f"Evidence review: total={summary.get('total', 0)}, "
        f"fail={by_status.get('fail', 0)}, "
        f"categories={category_text}, "
        f"metrics={metrics.get('count', 0)}"
    )


def evidence_timeline_rows(events: list[dict], *, detail_limit: int = 180) -> list[dict[str, str]]:
    """Return compact display rows for GUI evidence events."""
    rows = []
    for index, event in enumerate(events, start=1):
        status = str(event.get("status", "") or "")
        devices = event.get("device_ids", [])
        if not isinstance(devices, list):
            devices = []
        artifacts = event.get("artifacts", [])
        if not isinstance(artifacts, list):
            artifacts = []
        category = failure_category(event) if status == "fail" else "-"
        rows.append({
            "index": str(index),
            "ts": str(event.get("ts", "") or ""),
            "status": status,
            "step": str(event.get("step", "") or ""),
            "devices": ", ".join(str(item) for item in devices if item) or "-",
            "category": category,
            "artifacts": ", ".join(str(item) for item in artifacts if item) or "-",
            "detail": _timeline_detail_brief(event.get("details", {}), limit=detail_limit),
        })
    return rows


def evidence_timeline_brief(rows: list[dict[str, str]]) -> str:
    counts: dict[str, int] = {}
    categories: dict[str, int] = {}
    for row in rows:
        status = str(row.get("status", "info") or "info")
        counts[status] = counts.get(status, 0) + 1
        category = str(row.get("category", "-") or "-")
        if status == "fail" and category != "-":
            categories[category] = categories.get(category, 0) + 1
    category_text = ", ".join(f"{name}={count}" for name, count in sorted(categories.items())) or "none"
    if len(category_text) > 90:
        category_text = category_text[:87] + "..."
    return (
        f"Evidence timeline: events={len(rows)}, "
        f"pass={counts.get('pass', 0)}, fail={counts.get('fail', 0)}, "
        f"info={counts.get('info', 0)}, skip={counts.get('skip', 0)}, "
        f"categories={category_text}"
    )


