    """Return compact display rows for XP callback ledger events."""
    rows = []
    for event in events:
        ts = event.get("ts", "")
        if isinstance(ts, (int, float)):
            ts_text = datetime.fromtimestamp(float(ts)).strftime("%Y-%m-%d %H:%M:%S")
        else:
            ts_text = str(ts or "")
        device_id = str(event.get("device_id", event.get("id", "")) or "")
        rows.append({
            "seq": str(event.get("seq", "") or ""),
            "ts": ts_text,
            "event": str(event.get("event", event.get("type", "")) or ""),
            "device_id": device_id or "-",
            "source": str(event.get("source", "") or "-"),
            "severity": str(event.get("severity", "") or "info"),
            "detail": _timeline_detail_brief(event.get("data", {}), limit=detail_limit),
        })
