def rerun_playbook_rows(
    issue_rows_data: list[dict[str, str]] | None = None,
    *,
    stage: str = "p1",
    route_report: dict | None = None,
    doctor_report: dict | None = None,
    acceptance_report: dict | None = None,
    readiness_report: dict | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
) -> list[dict[str, str]]:
    """Convert current failures and gates into a field rerun decision playbook."""
    normalized_stage = stage.lower().strip() or "p1"
    summary = evidence_summary or {}
    status_counts = summary.get("by_status", {}) if isinstance(summary.get("by_status"), dict) else {}
    total_events = int(summary.get("total", 0) or 0)
    fail_events = int(status_counts.get("fail", 0) or 0)
    route_ready = bool(route_report and route_report.get("ok") and route_report.get("ready"))
    doctor_overall = str((doctor_report or {}).get("overall", "") or "").lower()
    doctor_clean = doctor_overall == "ok"
    acceptance_ok = bool(acceptance_report and acceptance_report.get("ok"))
    readiness_ok = bool(readiness_report and readiness_report.get("ok"))
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))

    rows: list[dict[str, str]] = []
    seen: set[str] = set()

    def add_row(
        category: str,
        *,
        count: int = 0,
        status: str,
        current: str,
        devices: str = "-",
        steps: str = "-",
        source: str = "computed",
    ) -> None:
        policy = _rerun_playbook_policy(category)
        method = policy["method"]
        rows.append({
            "category": category,
            "status": status,
            "count": str(count),
            "devices": devices or "-",
            "steps": steps or "-",
            "current": current,
            "rerun_rule": policy["rerun_rule"],
            "fresh_run_id": policy["fresh_run_id"],
            "evidence": policy["evidence"],
            "stop_rule": policy["stop_rule"],
            "gui_action": _rerun_playbook_gui_action(method),
            "method": method,
            "source": source,
        })
        seen.add(category)

    for issue in issue_rows_data or []:
        category = str(issue.get("category", "") or "uncategorized")
        try:
            count = int(issue.get("count", 0) or 0)
        except (TypeError, ValueError):
            count = 0
        if count <= 0:
            continue
        add_row(
            category,
            count=count,
            status="fail",
            current=(
                f"issue_count={count}; route_ready={route_ready}; doctor={doctor_overall or '-'}; "
                f"acceptance_ok={acceptance_ok}; readiness_ok={readiness_ok}; real_ios_verified={real_ios_verified}"
            ),
            devices=str(issue.get("devices", "-") or "-"),
            steps=str(issue.get("steps", "-") or "-"),
            source="Issue Triage",
        )

    if route_report is None and "route_decision" not in seen:
        add_row(
            "route_decision",
            status="pending",
            current=f"stage={normalized_stage.upper()}; route decision not loaded; events={total_events}, fail={fail_events}",
            source="Route gate",
        )
    elif route_report is not None and not route_ready and "route_decision" not in seen:
        add_row(
            "route_decision",
            status="fail",
            current=route_decision_brief(route_report),
            source="Route gate",
        )

    if doctor_report is None and "doctor" not in seen:
        add_row(
            "doctor",
            status="pending",
            current=f"stage={normalized_stage.upper()}; doctor not run",
            source="Doctor gate",
        )
    elif doctor_report is not None and not doctor_clean and "doctor" not in seen:
        add_row(
            "doctor",
            status="fail" if doctor_overall == "fail" else "warn",
            current=doctor_brief(doctor_report),
            source="Doctor gate",
        )

    if acceptance_report is None and "acceptance" not in seen:
        add_row(
            "acceptance",
            status="pending",
            current="acceptance not evaluated",
            source="Acceptance gate",
        )
    elif acceptance_report is not None and not acceptance_ok and "acceptance" not in seen:
        add_row(
            "acceptance",
            status="fail",
            current=acceptance_brief(acceptance_report),
            source="Acceptance gate",
        )

    if readiness_report is None and "readiness" not in seen:
        add_row(
            "readiness",
            status="pending",
            current="readiness not evaluated",
            source="Readiness gate",
        )
    elif readiness_report is not None and (not readiness_ok or not real_ios_verified) and "readiness" not in seen:
        add_row(
            "readiness",
            status="fail" if not readiness_ok else "warn",
            current=f"{readiness_brief(readiness_report)}; real_ios_verified={real_ios_verified}",
            source="Readiness gate",
        )

    if not rows:
        status = "ready" if evidence_exists and total_events > 0 and fail_events == 0 else "pending"
        add_row(
            "no_open_rerun",
            status=status,
            current=f"events={total_events}, fail={fail_events}; route_ready={route_ready}; doctor_clean={doctor_clean}",
            source="Summary",
        )
    return rows


def rerun_playbook_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts = _row_status_counts(rows)
    first_action = _first_attention_value(rows, "category", statuses={"fail", "pending", "warn"})
    return (
        f"Rerun playbook {stage.upper()}: "
        f"pass={counts.get('pass', 0)}, ready={counts.get('ready', 0)}, "
        f"warn={counts.get('warn', 0)}, fail={counts.get('fail', 0)}, "
        f"pending={counts.get('pending', 0)}; first_action={first_action}"
    )


def write_rerun_playbook_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    stage: str = "p1",
    evidence_path: str | Path = "",
    readiness_report: dict | None = None,
) -> Path:
    out_path = Path(path)
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))
    lines = [
        f"# GUI Rerun Playbook {stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        f"- Real iOS control verified: `{real_ios_verified}`",
        "- This playbook turns failures and gates into rerun decisions. It does not write evidence and does not prove real iPhone response.",
        "",
        "## Rerun Decisions",
        "",
        "| Category | Status | Count | Devices | Steps | Current | Rerun rule | Fresh run_id | Evidence to keep | Stop rule | GUI action | Source |",
        "|---|---|---|---|---|---|---|---|---|---|---|---|",
    ]
    for row in rows:
        lines.append(
            f"| {_md_cell(row.get('category', ''))} | `{_md_cell(row.get('status', ''))}` | "
            f"{_md_cell(row.get('count', ''))} | {_md_cell(row.get('devices', ''))} | "
            f"{_md_cell(row.get('steps', ''))} | {_md_cell(row.get('current', ''))} | "
            f"{_md_cell(row.get('rerun_rule', ''))} | {_md_cell(row.get('fresh_run_id', ''))} | "
            f"{_md_cell(row.get('evidence', ''))} | {_md_cell(row.get('stop_rule', ''))} | "
            f"{_md_cell(row.get('gui_action', ''))} | {_md_cell(row.get('source', ''))} |"
        )
    if not rows:
        lines.append("| none | `pending` | 0 | - | - | no rows built | Refresh Rerun | - | - | Do not promote | - | - |")
    lines.extend([
        "",
        "## Rerun Rule",
        "",
        "Use Rerun after Timeline, Matrix, Triage, and Review. Rerun the smallest failing path first. Start a fresh run_id when route, wiring, receiver identity, selected devices, or iPhone settings changed. Promotion still depends on JSONL evidence, Acceptance, Readiness, and manual real-iPhone observation.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


def _issue_category_counts(issue_rows_data: list[dict[str, str]] | None) -> dict[str, int]:
    counts: dict[str, int] = {}
    for row in issue_rows_data or []:
        category = str(row.get("category", "") or "").strip()
        if not category:
            continue
        try:
            count = int(row.get("count", 0) or 0)
        except (TypeError, ValueError):
            count = 0
        counts[category] = counts.get(category, 0) + count
    return counts


