def _p1_trial_failure_category(lane: str) -> str:
    text = str(lane or "").lower()
    if "receiver" in text or "capture" in text:
        return "capture"
    if "hid" in text or "keyboard" in text or "calibration" in text:
        return "hid"
    if "log" in text:
        return "uncategorized"
    if "route" in text:
        return "uncategorized"
    return "uncategorized"


def stage_dashboard_rows(
    *,
    target_stage: str = "p1",
    device_ids: list[str] | None = None,
    readiness_report: dict | None = None,
    acceptance_reports: dict[str, dict] | None = None,
    route_report: dict | None = None,
    doctor_report: dict | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
) -> list[dict[str, str]]:
    """Build the P0-P4 GUI stage dashboard without writing evidence."""
    normalized_target = target_stage.lower().strip() or "p1"
    if normalized_target not in STAGE_DASHBOARD_ORDER:
        normalized_target = "p1"
    selected_devices = [item for item in (device_ids or []) if str(item).strip()]
    acceptance_by_stage = acceptance_reports or {}
    stage_status = readiness_report.get("stage_status", {}) if isinstance(readiness_report, dict) else {}
    evidence_total = int((evidence_summary or {}).get("total", 0) or 0)
    fail_total = int((evidence_summary or {}).get("by_status", {}).get("fail", 0) or 0)
    metric_total = int((evidence_summary or {}).get("metrics", {}).get("count", 0) or 0)
    evidence_text = (
        f"events={evidence_total}, fail={fail_total}, metrics={metric_total}"
        if evidence_exists
        else "missing"
    )

    rows = []
    for stage in STAGE_DASHBOARD_ORDER:
        readiness_item = stage_status.get(stage, {}) if isinstance(stage_status, dict) else {}
        if isinstance(readiness_item, dict) and readiness_item:
            status = "pass" if readiness_item.get("ok") else "fail"
        elif stage == "p0":
            status = "pending"
        else:
            report = acceptance_by_stage.get(stage)
            status = "pass" if isinstance(report, dict) and report.get("ok") else "pending"

        blockers = _stage_dashboard_blockers(
            stage=stage,
            selected_devices=selected_devices,
            readiness_report=readiness_report,
            acceptance_report=acceptance_by_stage.get(stage),
            route_report=route_report,
            doctor_report=doctor_report,
            evidence_exists=evidence_exists,
        )
        if blockers and status == "pass":
            status = "fail"
        rows.append({
            "stage": stage,
            "label": STAGE_DASHBOARD_LABELS[stage],
            "status": status,
            "selected_devices": str(len(selected_devices)),
            "required_devices": str(STAGE_DEVICE_REQUIREMENTS.get(stage, 1)),
            "evidence": evidence_text,
            "gate": STAGE_DASHBOARD_GATES[stage],
            "script": STAGE_PRIMARY_SCENARIOS.get(stage, ""),
            "blockers": ", ".join(blockers[:4]) if blockers else "none",
            "next_action": _stage_dashboard_next_action(stage, blockers),
            "current": "yes" if stage == normalized_target else "",
        })
    return rows


def stage_dashboard_brief(rows: list[dict[str, str]], *, target_stage: str = "p1") -> str:
    counts: dict[str, int] = {}
    for row in rows:
        status = str(row.get("status", "pending") or "pending")
        counts[status] = counts.get(status, 0) + 1
    normalized_target = target_stage.lower().strip() or "p1"
    current = next((row for row in rows if row.get("stage") == normalized_target), None)
    if current:
        current_text = f"{normalized_target.upper()} {current.get('status', 'pending')}"
        blockers = str(current.get("blockers", "none") or "none")
    else:
        current_text = f"{normalized_target.upper()} pending"
        blockers = "none"
    return (
        f"Stage dashboard {normalized_target.upper()}: "
        f"pass={counts.get('pass', 0)}, fail={counts.get('fail', 0)}, "
        f"pending={counts.get('pending', 0)}; current={current_text}; blockers={blockers}"
    )


def write_stage_dashboard_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    target_stage: str = "p1",
    run_id: str = "",
    evidence_path: str | Path = "",
    readiness_report: dict | None = None,
) -> Path:
    out_path = Path(path)
    claims = (readiness_report or {}).get("claims", {}) if isinstance(readiness_report, dict) else {}
    real_ios_verified = bool(claims.get("real_ios_control_verified"))
    group_verified = bool(claims.get("ios_group_control_verified"))
    lines = [
        f"# GUI Stage Dashboard {target_stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        f"- Real iOS control verified: `{real_ios_verified}`",
        f"- iOS group control verified: `{group_verified}`",
        "- This dashboard is a GUI snapshot; it does not write evidence or prove real iPhone response.",
        "",
        "## Stage Matrix",
        "",
        "| Stage | Current | Status | Devices | Evidence | Gate | Script | Blockers | Next action |",
        "|---|---|---|---|---|---|---|---|---|",
    ]
    for row in rows:
        devices = f"{row.get('selected_devices', '0')}/{row.get('required_devices', '0')}"
        values = [
            row.get("stage", "").upper(),
            row.get("current", ""),
            row.get("status", ""),
            devices,
            row.get("evidence", ""),
            row.get("gate", ""),
            row.get("script", ""),
            row.get("blockers", ""),
            row.get("next_action", ""),
        ]
        escaped = [str(value).replace("|", "\\|") for value in values]
        lines.append(
            f"| {escaped[0]} | {escaped[1]} | `{escaped[2]}` | {escaped[3]} | "
            f"{escaped[4]} | {escaped[5]} | `{escaped[6]}` | {escaped[7]} | {escaped[8]} |"
        )
    lines.extend([
        "",
        "## Promotion Rule",
        "",
        "Do not promote beyond the current stage unless the current row is PASS, Route Decision is PASS, Doctor has no fail, Acceptance is PASS, Readiness is PASS, and Manual evidence records real iPhone behavior.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


def _acceptance_check_line(report: dict | None, check_name: str) -> tuple[str, str]:
    if not isinstance(report, dict) or not report:
        return "pending", f"{check_name} has not been evaluated."
    for check in report.get("checks", []) or []:
        if not isinstance(check, dict) or check.get("name") != check_name:
            continue
        status = str(check.get("status", "pending") or "pending").lower()
        if status == "ok":
            status = "pass"
        if status not in {"pass", "fail", "warn", "pending"}:
            status = "pending"
        message = str(check.get("message", "") or f"{check_name} evaluated")
        return status, message
    if report.get("ok"):
        return "pass", f"{check_name} is not required by this gate."
    return "pending", f"{check_name} check not found in acceptance report."


def field_runbook_rows(
    *,
    stage: str = "p1",
    device_ids: list[str] | None = None,
    route_report: dict | None = None,
    doctor_report: dict | None = None,
    scenario_summary: dict | None = None,
    acceptance_report: dict | None = None,
    readiness_report: dict | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
    command_queue_items: list[dict] | None = None,
    template_asset_rows_data: list[dict[str, str]] | None = None,
) -> list[dict[str, str]]:
    """Build the operator-facing field runbook for the current GUI stage."""
    normalized_stage = stage.lower().strip() or "p1"
    selected_devices = [str(item).strip() for item in (device_ids or []) if str(item).strip()]
    required_devices = STAGE_DEVICE_REQUIREMENTS.get(normalized_stage, 1)
    summary = evidence_summary or {}
    status_counts = summary.get("by_status", {}) if isinstance(summary.get("by_status"), dict) else {}
    total_events = int(summary.get("total", 0) or 0)
    fail_events = int(status_counts.get("fail", 0) or 0)
    metrics_count = int(summary.get("metrics", {}).get("count", 0) or 0) if isinstance(summary.get("metrics"), dict) else 0
    template_rows = template_asset_rows_data or []
    queue_count = len(command_queue_rows(command_queue_items or []))
    guard = real_run_guard_report(
        stage=normalized_stage,
        device_ids=selected_devices,
        route_report=route_report,
        doctor_report=doctor_report,
    )

    rows: list[dict[str, str]] = []

    def add(
        phase: str,
        status: str,
        objective: str,
        gui_action: str,
        evidence: str,
        stop_rule: str,
    ) -> None:
        rows.append({
            "phase": phase,
            "status": status,
            "objective": objective,
            "gui_action": gui_action,
            "evidence": evidence,
            "stop_rule": stop_rule,
        })

    add(
        "Bench scope",
        "pass" if len(selected_devices) >= required_devices else "fail",
        f"Select the target bench devices for {normalized_stage.upper()} ({len(selected_devices)}/{required_devices}).",
        "Register/select devices, then Record Metadata.",
        "Device ids plus receiver/HID/iPhone component metadata in JSONL.",
        "Stop if target device count is below the stage requirement.",
    )

    if route_report is None:
        route_status = "pending"
        route_text = "Route Decision has not been loaded or validated."
    else:
        route_status = "pass" if bool(route_report.get("ok")) and bool(route_report.get("ready")) else "fail"
        route_text = route_decision_brief(route_report)
    add(
        "Route ledger",
        route_status,
        "Lock receiver, capture, HID, iPhone, hub, cable, and operator ledger before field actions.",
        "Route Init/Edit, Use Metadata, Checklist, Validate.",
        route_text,
        "Stop real runs until Route Decision is ok and ready with no placeholders or open blockers.",
    )

    if doctor_report is None:
        doctor_status = "pending"
        doctor_text = "Doctor has not been run for this run_id."
    else:
        overall = str(doctor_report.get("overall", "") or "").lower()
        doctor_status = "pass" if overall == "ok" else "warn" if overall == "warn" else "fail"
        doctor_text = doctor_brief(doctor_report)
    add(
        "Preflight doctor",
        doctor_status,
        "Check Python modules, receiver provider, ports, writable evidence, and local API health.",
        "Doctor.",
        doctor_text,
        "Stop if doctor has fail before touching real devices.",
    )

    screenshot_status, screenshot_text = _acceptance_check_line(acceptance_report, "screenshot_quality")
    add(
        "Receiver/capture",
        screenshot_status,
        "Bring up AirPlay/receiver/capture and prove the screenshot is usable.",
        "Start AirPlay, Start Capture, Screenshot, Timeline.",
        screenshot_text,
        "Stop if screenshot is missing, black/white/invalid, or not traceable to the device.",
    )

    manual_status, manual_text = _acceptance_check_line(acceptance_report, "manual_observation")
    add(
        "HID/manual control",
        manual_status,
        "Run click/swipe/type and record what the real iPhone did.",
        "Click, Swipe, Type, Manual Record.",
        manual_text,
        "Stop promotion if there is no manual pass observation from a real iPhone.",
    )

    if not template_rows:
        template_status = "pending"
        template_text = "No template asset index has been refreshed."
    else:
        template_fail = len([row for row in template_rows if row.get("status") == "fail"])
        template_ok = len([row for row in template_rows if row.get("status") == "ok"])
        template_status = "fail" if template_fail else "pass" if template_ok else "pending"
        template_text = f"templates ok={template_ok}, fail={template_fail}, total={len(template_rows)}"
    add(
        "Vision assets",
        template_status,
        "Prepare reusable templates/colors/OCR probes before repeated GUI automation.",
        "Assets, Save Crop, Find, Find Color, OCR, Find Text.",
        template_text,
        "Stop template-driven runs if assets are too small or low texture.",
    )

    if scenario_summary is None:
        scenario_status = "ready" if queue_count else "pending"
        scenario_text = f"Command queue items={queue_count}; scenario summary not run."
    else:
        scenario_status = "pass" if scenario_summary.get("ok") else "fail"
        scenario_text = scenario_brief(scenario_summary)
    add(
        "Probe scenario",
        scenario_status,
        "Dry-run the stage script or GUI-built queue, then keep the exact JSON for repeatability.",
        "Scenario Library, Dry Run, Command Queue Save JSON, Run.",
        scenario_text,
        "Stop before real run if dry-run or queue validation fails.",
    )

    add(
        "Real-run guard",
        "pass" if guard.get("ok") else "fail",
        "Verify the GUI is allowed to disable dry-run for the current stage.",
        "Run Scenario or Command Queue with Dry Run disabled.",
        real_run_guard_brief(guard),
        "Stop if guard blocks route, doctor, or device scope.",
    )

    metrics_status, metrics_text = _acceptance_check_line(acceptance_report, "metrics")
    if metrics_status == "pending" and normalized_stage == "p1":
        metrics_text = f"metrics samples={metrics_count}; optional for P1 but required for later stability stages."
    add(
        "Stability metrics",
        metrics_status,
        "Record host/device stability signals before P2/P3/P4 promotion.",
        "Run P2/P3/P4 watchdog scenario or a metrics step.",
        metrics_text,
        "Stop P2/P3/P4 promotion if metrics are absent or show resource pressure.",
    )

    if not evidence_exists or total_events == 0:
        triage_status = "pending"
        triage_text = "No evidence JSONL events loaded."
    else:
        triage_status = "fail" if fail_events else "pass"
        triage_text = f"events={total_events}, fail={fail_events}"
    add(
        "Review and triage",
        triage_status,
        "Inspect event order, affected devices, artifacts, and failure categories.",
        "Timeline, Matrix, Triage, Review.",
        triage_text,
        "Stop promotion until root failed events are explained or re-run cleanly.",
    )

    acceptance_ok = isinstance(acceptance_report, dict) and bool(acceptance_report.get("ok"))
    readiness_ok = isinstance(readiness_report, dict) and bool(readiness_report.get("ok"))
    if acceptance_ok and readiness_ok:
        promotion_status = "pass"
    elif acceptance_report is None and readiness_report is None:
        promotion_status = "pending"
    else:
        promotion_status = "fail"
    add(
        "Promotion gate",
        promotion_status,
        "Decide whether the stage can advance without overstating real iOS control.",
        "Acceptance, Gap, Readiness, Dashboard, Pack, XP Gap.",
        f"{acceptance_brief(acceptance_report or {})}; {readiness_brief(readiness_report or {})}",
        "Only promote when Acceptance and Readiness pass and manual evidence proves real iPhone behavior.",
    )
    return rows


def field_runbook_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts: dict[str, int] = {}
    for row in rows:
        status = str(row.get("status", "pending") or "pending")
        counts[status] = counts.get(status, 0) + 1
    first_stop = next(
        (row.get("phase", "") for row in rows if row.get("status") in {"fail", "pending"}),
        "none",
    )
    return (
        f"Field runbook {stage.upper()}: "
        f"pass={counts.get('pass', 0)}, fail={counts.get('fail', 0)}, "
        f"pending={counts.get('pending', 0)}, ready={counts.get('ready', 0)}, "
        f"warn={counts.get('warn', 0)}; first_stop={first_stop}"
    )


def write_field_runbook_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    stage: str = "p1",
    evidence_path: str | Path = "",
    readiness_report: dict | None = None,
) -> Path:
    out_path = Path(path)
    real_ios_verified = bool(
        (readiness_report or {}).get("claims", {}).get("real_ios_control_verified")
    )
    lines = [
        f"# GUI Field Runbook {stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        f"- Real iOS control verified: `{real_ios_verified}`",
        "- This runbook is an operator guide. It does not write evidence or prove real iPhone response.",
        "",
        "## Steps",
        "",
        "| Phase | Status | Objective | GUI action | Evidence | Stop rule |",
        "|---|---|---|---|---|---|",
    ]
    for row in rows:
        lines.append(
            f"| {_md_cell(row.get('phase', ''))} | `{_md_cell(row.get('status', ''))}` | "
            f"{_md_cell(row.get('objective', ''))} | {_md_cell(row.get('gui_action', ''))} | "
            f"{_md_cell(row.get('evidence', ''))} | {_md_cell(row.get('stop_rule', ''))} |"
        )
    if not rows:
        lines.append("| - | `pending` | Build GUI runbook first | Refresh Runbook | - | Do not promote |")
    lines.extend([
        "",
        "## Promotion Rule",
        "",
        "Promotion requires clean JSONL evidence, Acceptance PASS, Readiness PASS, usable screenshot quality, component metadata, and manual real-iPhone observation. For P3/P4, every target device must be traceable in Matrix.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


def stage_sop_rows(
    *,
    stage: str = "p1",
    device_ids: list[str] | None = None,
    route_report: dict | None = None,
    doctor_report: dict | None = None,
    scenario_summary: dict | None = None,
    acceptance_report: dict | None = None,
    readiness_report: dict | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
    command_queue_items: list[dict] | None = None,
    template_asset_rows_data: list[dict[str, str]] | None = None,
) -> list[dict[str, str]]:
    """Build the stage SOP board rows without writing evidence."""
    normalized_stage = stage.lower().strip() or "p1"
    selected_devices = [str(item).strip() for item in (device_ids or []) if str(item).strip()]
    required_devices = STAGE_DEVICE_REQUIREMENTS.get(normalized_stage, 1)
    summary = evidence_summary or {}
    status_counts = summary.get("by_status", {}) if isinstance(summary.get("by_status"), dict) else {}
    total_events = int(summary.get("total", 0) or 0)
    fail_events = int(status_counts.get("fail", 0) or 0)
    queue_rows = command_queue_rows(command_queue_items or [])
    template_rows = template_asset_rows_data or []

    rows: list[dict[str, str]] = []

    def add(
        step: str,
        workstream: str,
        status: str,
        current: str,
        next_action: str,
        evidence: str,
    ) -> None:
        rows.append({
            "step": step,
            "workstream": workstream,
            "status": status,
            "current": current,
            "next_action": next_action,
            "evidence": evidence,
        })

    device_status = "pass" if len(selected_devices) >= required_devices else "fail"
    add(
        "1",
        "Device scope",
        device_status,
        f"selected={len(selected_devices)}, required={required_devices}",
        "Register/select devices and record component metadata.",
        "Record Metadata evidence with receiver/HID/iPhone fields.",
    )

    if route_report is None:
        route_status = "pending"
        route_current = "route decision not loaded"
    else:
        route_status = "pass" if route_report.get("ready") and route_report.get("ok") is not False else "fail"
        route_current = route_decision_brief(route_report)
    add(
        "2",
        "Route decision",
        route_status,
        route_current,
        "Use Route Init/Edit, fill real receiver/HID/iPhone values, then Validate.",
        "Route Decision JSON/report and route decision evidence event.",
    )

    if doctor_report is None:
        doctor_status = "pending"
        doctor_current = "doctor not run"
    else:
        overall = str(doctor_report.get("overall", "unknown") or "unknown").lower()
        doctor_status = "pass" if overall == "ok" else "warn" if overall == "warn" else "fail"
        doctor_current = doctor_brief(doctor_report)
    add(
        "3",
        "Preflight doctor",
        doctor_status,
        doctor_current,
        "Run Doctor and fix server, route, binary, serial, and dependency failures.",
        "Doctor report artifact.",
    )

    if not evidence_exists:
        evidence_status = "pending"
        evidence_current = "no JSONL evidence file"
    elif total_events <= 0:
        evidence_status = "fail"
        evidence_current = "JSONL exists but has zero events"
    elif fail_events:
        evidence_status = "fail"
        evidence_current = f"events={total_events}, fail={fail_events}"
    else:
        evidence_status = "pass"
        evidence_current = f"events={total_events}, fail=0"
    add(
        "4",
        "Capture/control evidence",
        evidence_status,
        evidence_current,
        "Record Screenshot, command result, and Manual real-iPhone observation evidence.",
        "JSONL events with screenshot quality and manual observation.",
    )

    if scenario_summary:
        scenario_status = "pass" if scenario_summary.get("ok") else "fail"
        scenario_current = scenario_brief(scenario_summary)
        scenario_action = "Use Gap after failures; rerun only after route and doctor blockers are fixed."
    elif queue_rows:
        scenario_status = "ready"
        scenario_current = command_queue_brief(command_queue_items or [])
        scenario_action = "Save JSON, dry-run the queue, then run real only after P1 route is allowed."
    else:
        scenario_status = "pending"
        scenario_current = "no scenario/queue result"
        scenario_action = "Load Probe Script or build Command Queue for the current stage."
    add(
        "5",
        "Probe script",
        scenario_status,
        scenario_current,
        scenario_action,
        "Scenario summary event and GUI queue JSON when using queued actions.",
    )

    template_fail = sum(1 for row in template_rows if row.get("status") == "fail")
    template_ok = sum(1 for row in template_rows if row.get("status") == "ok")
    if not template_rows:
        template_status = "pending"
        template_current = "no template asset index"
    elif template_fail:
        template_status = "fail"
        template_current = f"ok={template_ok}, fail={template_fail}"
    else:
        template_status = "pass"
        template_current = f"ok={template_ok}, fail=0"
    add(
        "6",
        "Vision assets",
        template_status,
        template_current,
        "Open Assets, replace low-texture/small templates, then Write Index.",
        "Template asset index and failure screenshots for misses.",
    )

    if acceptance_report is None:
        acceptance_status = "pending"
        acceptance_current = "acceptance not evaluated"
    else:
        acceptance_status = "pass" if acceptance_report.get("ok") else "fail"
        acceptance_current = acceptance_brief(acceptance_report)
    add(
        "7",
        "Acceptance gate",
        acceptance_status,
        acceptance_current,
        "Run Acceptance; if FAIL, run Gap and add the listed evidence.",
        "Acceptance report and optional acceptance gap report.",
    )

    if readiness_report is None:
        readiness_status = "pending"
        readiness_current = "readiness not evaluated"
    else:
        readiness_status = "pass" if readiness_report.get("ok") else "fail"
        readiness_current = readiness_brief(readiness_report)
    add(
        "8",
        "Promotion review",
        readiness_status,
        readiness_current,
        "Run Readiness, export Dashboard/Pack/Session, then promote only with real iPhone evidence.",
        "Readiness report, stage dashboard, evidence pack, and session snapshot.",
    )
    return rows


def stage_sop_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts: dict[str, int] = {}
    for row in rows:
        status = str(row.get("status", "pending") or "pending")
        counts[status] = counts.get(status, 0) + 1
    blockers = [
        row.get("workstream", "")
        for row in rows
        if row.get("status") in {"fail", "pending"}
    ]
    blocker_text = ", ".join(blockers[:3]) if blockers else "none"
    return (
        f"SOP board {stage.upper()}: "
        f"pass={counts.get('pass', 0)}, ready={counts.get('ready', 0)}, "
        f"warn={counts.get('warn', 0)}, fail={counts.get('fail', 0)}, "
        f"pending={counts.get('pending', 0)}; blockers={blocker_text}"
    )


def stage_sop_next_command(row: dict, *, queue_has_items: bool = False) -> dict[str, str]:
    """Return the primary GUI command for a SOP row."""
    workstream = str(row.get("workstream", "") or "").strip()
    status = str(row.get("status", "") or "").strip().lower()
    if workstream == "Device scope":
        return {
            "label": "Record Metadata",
            "method": "record_component_metadata",
            "reason": "write component metadata into the current evidence run",
        }
    if workstream == "Route decision":
        return {
            "label": "Edit Route",
            "method": "edit_route_decision_from_gui",
            "reason": "fill and validate real receiver/HID/iPhone route values",
        }
    if workstream == "Preflight doctor":
        return {
            "label": "Run Doctor",
            "method": "run_preflight_doctor",
            "reason": "check service, receiver, serial, route, and local dependencies",
        }
    if workstream == "Capture/control evidence":
        return {
            "label": "Screenshot",
            "method": "screenshot",
            "reason": "capture a frame and record screenshot quality before control claims",
        }
    if workstream == "Probe script":
        if queue_has_items or status == "ready":
            return {
                "label": "Run Queue",
                "method": "run_command_queue_from_gui",
                "reason": "execute the GUI-built command queue through ScriptRunner",
            }
        return {
            "label": "Load Probe Script",
            "method": "load_probe_script_from_gui",
            "reason": "load the stage default dry-run scenario",
        }
    if workstream == "Vision assets":
        return {
            "label": "Open Assets",
            "method": "show_template_asset_manager",
            "reason": "review template size and texture quality",
        }
    if workstream == "Acceptance gate":
        return {
            "label": "Run Acceptance",
            "method": "run_acceptance_from_gui",
            "reason": "evaluate the current JSONL evidence against the selected gate",
        }
    if workstream == "Promotion review":
        if status == "pass":
            return {
                "label": "Export Session",
                "method": "write_gui_session_snapshot_from_gui",
                "reason": "export a handoff snapshot after readiness has passed",
            }
        return {
            "label": "Run Readiness",
            "method": "run_readiness_audit",
            "reason": "evaluate whether the stage can be promoted",
        }
    return {
        "label": "Refresh SOP",
        "method": "refresh_live_probe_status",
        "reason": "refresh the live state before choosing an action",
    }


def write_stage_sop_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    stage: str = "p1",
    evidence_path: str | Path = "",
) -> Path:
    out_path = Path(path)
    lines = [
        f"# GUI SOP Board {stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        "- Real iOS control verified: `False`",
        "- This SOP board is an execution guide and review index. It does not write evidence or prove real iPhone response.",
        "",
        "## Stage Steps",
        "",
        "| # | Workstream | Status | Current | Primary GUI command | Next action | Evidence to keep |",
        "|---|---|---|---|---|---|---|",
    ]
    for row in rows:
        command = stage_sop_next_command(row)
        lines.append(
            f"| {_md_cell(row.get('step', ''))} | {_md_cell(row.get('workstream', ''))} | "
            f"`{_md_cell(row.get('status', ''))}` | {_md_cell(row.get('current', ''))} | "
            f"{_md_cell(command.get('label', ''))} | "
            f"{_md_cell(row.get('next_action', ''))} | {_md_cell(row.get('evidence', ''))} |"
        )
    lines.extend([
        "",
        "## Promotion Rule",
        "",
        "A stage is reviewable only when Route Decision, Doctor, Acceptance, and Readiness are PASS and manual evidence records real iPhone behavior. For P3/P4, every selected device must have per-device evidence and failure isolation notes.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


