def _receiver_capture_binding_gate(route_decision: dict | None) -> tuple[str, str]:
    if not route_decision:
        return "pending", "route decision not loaded"
    values = route_decision_form_values(route_decision)
    route = str(values.get("receiver.route", nested_get(route_decision, "receiver.route", "")) or "").strip()
    capture_method = str(
        values.get("receiver.capture_method", nested_get(route_decision, "receiver.capture_method", "")) or ""
    ).strip()
    if not capture_method:
        return "fail", "receiver.capture_method is missing"
    if _route_form_has_placeholder(capture_method):
        return "fail", f"receiver.capture_method is placeholder: {capture_method}"

    if capture_method == "window":
        title = str(
            values.get(
                "receiver.window_binding.title",
                nested_get(route_decision, "receiver.window_binding.title", ""),
            )
            or ""
        ).strip()
        process = str(
            values.get(
                "receiver.window_binding.process",
                nested_get(route_decision, "receiver.window_binding.process", ""),
            )
            or ""
        ).strip()
        handle = str(
            values.get(
                "receiver.window_binding.handle",
                nested_get(route_decision, "receiver.window_binding.handle", ""),
            )
            or ""
        ).strip()
        if not title:
            return "fail", "window capture selected but receiver.window_binding.title is missing"
        placeholders = [
            name
            for name, value in (
                ("title", title),
                ("process", process),
                ("handle", handle),
            )
            if value and _route_form_has_placeholder(value)
        ]
        if placeholders:
            return "fail", f"window binding has placeholder={', '.join(placeholders)}"
        if not process and not handle:
            return "warn", f"window title={title}; add process or handle for stable binding"
        return "pass", f"window title={title}; process={process or '-'}; handle={handle or '-'}"

    if capture_method in {"display", "sdk", "capture_card", "wired"}:
        return "pass", f"route={route or '-'}; capture_method={capture_method}"
    if capture_method == "other":
        return "warn", "capture_method=other requires a written operator binding note"
    return "fail", f"unsupported capture_method={capture_method}"


def receiver_route_gate_rows(
    *,
    stage: str = "p1",
    docs_root: str | Path = ".",
    route_decision: dict | None = None,
    route_report: dict | None = None,
    doctor_report: dict | None = None,
    acceptance_report: dict | None = None,
    readiness_report: dict | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
    receiver_report: dict | None = None,
    route_decision_path: str | Path = "",
) -> list[dict[str, str]]:
    """Build the GUI receiver-route readiness gate without writing evidence."""
    normalized_stage = stage.lower().strip() or "p1"
    summary = evidence_summary or {}
    status_counts = summary.get("by_status", {}) if isinstance(summary.get("by_status"), dict) else {}
    fail_events = int(status_counts.get("fail", 0) or 0)
    total_events = int(summary.get("total", 0) or 0)

    if receiver_report is None:
        try:
            if route_decision:
                receiver_report = evaluate_receiver_provider(
                    receiver_config_from_decision(route_decision),
                    root=docs_root,
                )
            else:
                receiver_report = evaluate_receiver_provider(None, root=docs_root)
        except Exception as exc:
            receiver_report = {
                "status": "fail",
                "route": "",
                "message": f"Receiver provider evaluation failed: {exc}",
                "details": {},
            }

    receiver_status = _receiver_gate_status_from_provider(receiver_report)
    receiver_route = str(receiver_report.get("route", "") or "").strip()
    provider_ok = str(receiver_report.get("status", "") or "").lower() == "ok"
    screenshot_status, screenshot_text = _acceptance_check_line(acceptance_report, "screenshot_quality")
    manual_status, manual_text = _acceptance_check_line(acceptance_report, "manual_observation")
    real_ios_verified = bool(
        (readiness_report or {}).get("claims", {}).get("real_ios_control_verified")
    )

    rows: list[dict[str, str]] = []

    def add(
        lane: str,
        status: str,
        current: str,
        required: str,
        evidence: str,
        next_action: str,
        stop_rule: str,
        method: str,
    ) -> None:
        rows.append({
            "lane": lane,
            "status": status,
            "current": current,
            "required": required,
            "evidence": evidence,
            "next_action": next_action,
            "stop_rule": stop_rule,
            "gui_action": _receiver_route_gate_gui_action(method),
            "method": method,
        })

    route_path_text = str(route_decision_path or "").strip() or "evidence/<run_id>_route_decision.json"
    add(
        "Route decision source",
        "pass" if route_decision else "fail",
        (
            f"loaded=True; path={route_path_text}; run_id={route_decision.get('run_id', '-')}"
            if route_decision
            else f"loaded=False; path={route_path_text}"
        ),
        "A route decision JSON filled with real receiver, capture, HID, iPhone, bench, and decision fields.",
        "Route Decision JSON and route validation markdown.",
        "Open or initialize the route decision, then fill real bench values before hardware actions.",
        "Stop if the operator cannot point to the exact receiver route file for this run_id.",
        "edit_route_decision_from_gui",
    )

    if route_report is None:
        route_status = "pending"
        route_current = "route decision has not been validated"
    else:
        route_status = "pass" if route_report.get("ok") and route_report.get("ready") else "fail"
        route_current = route_decision_brief(route_report)
    add(
        "Route validation and open blockers",
        route_status,
        route_current,
        "Route validation requires ok=true, ready=true, allowed_to_run_p1=true, and no open blockers.",
        "Route Decision Report generated by Validate or python -m imouse.route_decision validate --require-ready.",
        "Clear missing fields, placeholders, not-allowed state, and open blockers.",
        "Stop if route validation fails; a recorded route failure requires a fresh run_id after fixes.",
        "edit_route_decision_from_gui" if route_status != "pass" else "run_preflight_doctor",
    )

    add(
        "Receiver provider config",
        receiver_status,
        receiver_provider_brief(receiver_report),
        "Provider config must resolve route/name/version/path/start command/capture method and required AirPlay/window fields.",
        "Provider preflight from Route Decision or receiver config; this does not start the receiver.",
        "Fix provider fields or select a supported route before rerunning Doctor.",
        "Stop if provider path, capture method, or AirPlay/window binding is missing or placeholder-shaped.",
        "run_preflight_doctor" if receiver_status == "pass" else "edit_route_decision_from_gui",
    )

    uxplay_status, uxplay_message, _uxplay_details = _probe_check_line(doctor_report, "binary:uxplay")
    receiver_check_status, receiver_check_message, _receiver_check_details = _probe_check_line(
        doctor_report,
        "receiver_provider",
    )
    alt_route = receiver_route in {"windows_receiver", "wired", "capture_card"}
    if doctor_report is None:
        dependency_status = "pending"
        dependency_current = "Doctor has not been run for this run_id."
    elif alt_route and provider_ok:
        if uxplay_status == "fail":
            dependency_status = "fail"
            dependency_current = (
                f"route={receiver_route}; binary:uxplay still fail; rerun Doctor with the route decision path."
            )
        else:
            dependency_status = "pass"
            dependency_current = (
                f"route={receiver_route}; provider={receiver_check_status}; "
                f"binary:uxplay={uxplay_status}; {uxplay_message}"
            )
    elif receiver_route == "uxplay":
        dependency_status = "pass" if uxplay_status == "pass" else "fail" if uxplay_status == "fail" else "pending"
        dependency_current = f"route=uxplay; binary:uxplay={uxplay_status}; {uxplay_message}"
    else:
        dependency_status = "fail" if receiver_status == "fail" else "pending"
        dependency_current = f"route={receiver_route or '-'}; provider={receiver_status}; {receiver_check_message}"
    add(
        "UxPlay dependency and alternate route",
        dependency_status,
        dependency_current,
        "Default UxPlay route needs uxplay available; valid Windows/wired/capture-card routes may downgrade uxplay absence to warn.",
        "Doctor report for the same run_id and Route Decision path.",
        "Run Doctor with --route-decision, or fix UxPlay/provider installation before screenshot tests.",
        "Stop if Doctor still has binary:uxplay fail without a valid alternate receiver provider.",
        "run_preflight_doctor" if dependency_status != "pass" else "run_capture_quality_bench_from_gui",
    )

    binding_status, binding_detail = _receiver_capture_binding_gate(route_decision)
    add(
        "Capture binding fields",
        binding_status,
        binding_detail,
        "The selected capture path must bind to a deterministic window/display/SDK/capture-card source.",
        "Route Decision receiver.capture_method plus window title/process/handle where capture_method=window.",
        "Bind the receiver window before taking quality samples; add process/handle when possible.",
        "Stop if capture can point at the wrong window, stale display, or unknown provider.",
        "edit_route_decision_from_gui" if binding_status != "pass" else "run_capture_quality_bench_from_gui",
    )

    screenshot_gate_status = "pass" if screenshot_status == "pass" else "fail" if screenshot_status == "fail" else "pending"
    add(
        "Screenshot proof boundary",
        screenshot_gate_status,
        f"{screenshot_text}; evidence_exists={evidence_exists}; events={total_events}",
        "One visible, non-black, correctly bound screenshot before any click/swipe/text claim.",
        "Screenshot quality evidence, Shot Bench samples, and Acceptance screenshot_quality PASS.",
        "Run Shot Bench or P1 Trial and keep frame artifacts for review.",
        "Stop if the screenshot is black, stale, wrong window, cropped, rotated, or not tied to the selected iPhone.",
        "run_capture_quality_bench_from_gui",
    )

    if real_ios_verified:
        claim_status = "pass"
    elif manual_status == "pass" or screenshot_status == "pass":
        claim_status = "warn"
    else:
        claim_status = "pending"
    add(
        "Claim boundary",
        claim_status,
        (
            f"real_ios_control_verified={real_ios_verified}; manual={manual_status}; "
            f"screenshot={screenshot_status}; fail_events={fail_events}"
        ),
        "Real iOS control still needs JSONL evidence, screenshot quality, manual real-iPhone observations, Acceptance, and Readiness.",
        "Manual/P1 Trial evidence plus Acceptance PASS and Readiness real_ios_control_verified=true.",
        "Record real click/swipe/text observations, rerun Acceptance, then Readiness.",
        "Stop perfect-control or XP-parity wording while this row is not PASS.",
        "run_readiness_audit" if manual_status == "pass" and screenshot_status == "pass" else "show_p1_trial_from_gui",
    )
    return rows


def receiver_route_gate_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts: dict[str, int] = {}
    first_gap = "none"
    for row in rows:
        status = str(row.get("status", "pending") or "pending").lower()
        counts[status] = counts.get(status, 0) + 1
        if first_gap == "none" and status != "pass":
            first_gap = str(row.get("lane", "") or "unknown")
    return (
        f"Receiver route gate {stage.upper()}: rows={len(rows)}, "
        f"pass={counts.get('pass', 0)}, warn={counts.get('warn', 0)}, "
        f"pending={counts.get('pending', 0)}, fail={counts.get('fail', 0)}; first_gap={first_gap}"
    )


def write_receiver_route_gate_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    stage: str = "p1",
    evidence_path: str | Path = "",
    route_decision_path: str | Path = "",
    readiness_report: dict | None = None,
) -> Path:
    out_path = Path(path)
    real_ios_verified = bool(
        (readiness_report or {}).get("claims", {}).get("real_ios_control_verified")
    )
    lines = [
        f"# Receiver Route Gate {stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        f"- Route Decision: `{route_decision_path}`",
        f"- Real iOS control verified: `{real_ios_verified}`",
        "- This gate checks receiver route readiness only. It does not write evidence, does not start a receiver, and does not prove real iOS control or real iPhone response.",
        "",
        "## Gate Rows",
        "",
        "| Lane | Status | Current | Required | Evidence | Next action | GUI action | Stop rule |",
        "|---|---|---|---|---|---|---|---|",
    ]
    for row in rows:
        lines.append(
            f"| {_md_cell(row.get('lane', ''))} | `{_md_cell(row.get('status', ''))}` | "
            f"{_md_cell(row.get('current', ''))} | {_md_cell(row.get('required', ''))} | "
            f"{_md_cell(row.get('evidence', ''))} | {_md_cell(row.get('next_action', ''))} | "
            f"{_md_cell(row.get('gui_action', ''))} | {_md_cell(row.get('stop_rule', ''))} |"
        )
    if not rows:
        lines.append("| None | `pending` | no rows built | Refresh Receiver Gate | - | - | - | - |")
    lines.extend([
        "",
        "## Review Rule",
        "",
        "Treat this as a provider/route preflight. P1 still requires a visible screenshot, real iPhone manual observations, no unexplained failures, Acceptance PASS, and Readiness PASS before claiming iOS control.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


