def _receiver_setup_value(values: dict[str, str], route_decision: dict | None, key: str) -> str:
    if values.get(key):
        return str(values.get(key, "") or "").strip()
    return str(nested_get(route_decision or {}, key, "") or "").strip()


def _receiver_setup_missing_or_placeholder(value: str) -> bool:
    return not value.strip() or _route_form_has_placeholder(value)


def _receiver_setup_route_command(route: str, values: dict[str, str], route_path_text: str, run_id: str) -> str:
    airplay_name = values.get("receiver.airplay_name", "").strip() or "imouse-dev-01"
    start_command = values.get("receiver.start_command", "").strip()
    receiver_path = values.get("receiver.path", "").strip()
    if route == "uxplay":
        command = start_command if start_command and not _route_form_has_placeholder(start_command) else f"uxplay -n {airplay_name}"
        return f"where.exe uxplay; {command}"
    if route == "windows_receiver":
        if start_command and not _route_form_has_placeholder(start_command):
            return f"{start_command}; Get-Process | Where-Object {{ $_.MainWindowTitle -like '*{airplay_name}*' }}"
        if receiver_path and not _route_form_has_placeholder(receiver_path):
            return f"Start-Process -FilePath '{receiver_path}'; Get-Process | Where-Object {{ $_.MainWindowTitle -like '*{airplay_name}*' }}"
        return "# Start the chosen Windows receiver, then record path/version/window title in Route Decision."
    if route == "wired":
        return "# Start the wired projection driver or SDK, then record driver version, cable id, and capture method."
    if route == "capture_card":
        return "# Open the capture-card preview/source, then record card id, input, resolution, and capture method."
    return f".\\.venv\\Scripts\\python -m imouse.route_decision init --run-id {run_id} --output {route_path_text}"


def receiver_setup_wizard_rows(
    *,
    stage: str = "p1",
    docs_root: str | Path = ".",
    route_decision: dict | None = None,
    route_report: dict | None = None,
    doctor_report: dict | None = None,
    acceptance_report: dict | None = None,
    readiness_report: dict | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
    receiver_report: dict | None = None,
    route_decision_path: str | Path = "",
) -> list[dict[str, str]]:
    """Build a route-aware receiver install/binding guide without writing evidence."""
    normalized_stage = stage.lower().strip() or "p1"
    route_path_text = str(route_decision_path or "").strip() or "evidence/<run_id>_route_decision.json"
    run_id = str((route_decision or {}).get("run_id", "<run_id>") or "<run_id>")
    values = route_decision_form_values(route_decision or {}) if route_decision else {}
    receiver_route = _receiver_setup_value(values, route_decision, "receiver.route")
    receiver_name = _receiver_setup_value(values, route_decision, "receiver.name")
    receiver_version = _receiver_setup_value(values, route_decision, "receiver.version")
    receiver_path = _receiver_setup_value(values, route_decision, "receiver.path")
    receiver_start = _receiver_setup_value(values, route_decision, "receiver.start_command")
    airplay_name = _receiver_setup_value(values, route_decision, "receiver.airplay_name")
    capture_method = _receiver_setup_value(values, route_decision, "receiver.capture_method")
    window_title = _receiver_setup_value(values, route_decision, "receiver.window_binding.title")
    window_process = _receiver_setup_value(values, route_decision, "receiver.window_binding.process")
    license_status = _receiver_setup_value(values, route_decision, "receiver.license_status")
    valid_route = receiver_route in {"uxplay", "windows_receiver", "wired", "capture_card"}

    summary = evidence_summary or {}
    status_counts = summary.get("by_status", {}) if isinstance(summary.get("by_status"), dict) else {}
    fail_events = int(status_counts.get("fail", 0) or 0)
    total_events = int(summary.get("total", 0) or 0)

    if receiver_report is None:
        try:
            if route_decision:
                receiver_report = evaluate_receiver_provider(
                    receiver_config_from_decision(route_decision),
                    root=docs_root,
                )
            else:
                receiver_report = evaluate_receiver_provider(None, root=docs_root)
        except Exception as exc:
            receiver_report = {
                "status": "fail",
                "route": receiver_route,
                "message": f"Receiver provider evaluation failed: {exc}",
                "details": {},
            }
    provider_status = _receiver_gate_status_from_provider(receiver_report)
    provider_ok = str(receiver_report.get("status", "") or "").lower() == "ok"
    uxplay_status, uxplay_message, _uxplay_details = _probe_check_line(doctor_report, "binary:uxplay")
    receiver_check_status, receiver_check_message, _receiver_check_details = _probe_check_line(
        doctor_report,
        "receiver_provider",
    )
    screenshot_status, screenshot_text = _acceptance_check_line(acceptance_report, "screenshot_quality")
    manual_status, manual_text = _acceptance_check_line(acceptance_report, "manual_observation")
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))
    binding_status, binding_detail = _receiver_capture_binding_gate(route_decision)

    rows: list[dict[str, str]] = []

    def add(
        step: str,
        status: str,
        route: str,
        current: str,
        operator_action: str,
        command: str,
        pass_criteria: str,
        failure_handling: str,
        evidence: str,
        stop_rule: str,
        method: str,
    ) -> None:
        rows.append({
            "step": step,
            "status": status,
            "route": route,
            "current": current,
            "operator_action": operator_action,
            "command": command,
            "pass_criteria": pass_criteria,
            "failure_handling": failure_handling,
            "evidence": evidence,
            "stop_rule": stop_rule,
            "gui_action": _receiver_setup_wizard_gui_action(method),
            "method": method,
        })

    add(
        "1. Run identity and route file",
        "pass" if route_decision else "fail",
        receiver_route or "-",
        (
            f"loaded=True; run_id={run_id}; path={route_path_text}"
            if route_decision
            else f"loaded=False; expected={route_path_text}"
        ),
        "Create or open the exact Route Decision JSON for this field run before installing or changing receiver components.",
        f".\\.venv\\Scripts\\python -m imouse.route_decision init --run-id {run_id} --output {route_path_text}",
        "One route file exists for the run_id and is the only source of receiver/HID/iPhone scope.",
        "If a failed route decision was already recorded, fix fields under a fresh run_id before real hardware actions.",
        "Route Decision JSON path and optional validation markdown.",
        "Stop if the operator cannot identify the route file for this run.",
        "edit_route_decision_from_gui",
    )

    if route_report is None:
        route_status = "pending"
        route_current = "route validation not run"
    else:
        route_status = "pass" if route_report.get("ok") and route_report.get("ready") else "fail"
        route_current = route_decision_brief(route_report)
    add(
        "2. Validate route before setup",
        route_status,
        receiver_route or "-",
        route_current,
        "Validate that receiver, capture, HID, iPhone, bench, evidence plan, allowed_to_run_p1, and blockers are real.",
        (
            f".\\.venv\\Scripts\\python -m imouse.route_decision validate {route_path_text} "
            f"--require-ready --markdown evidence\\{run_id}_route_decision.md"
        ),
        "Validation returns PASS and Ready to run P1 is true.",
        "Do not install random components while the route still has placeholders or open blockers.",
        "Route Decision Report for the same run_id.",
        "Stop if validation fails; route failures are run-level blockers.",
        "validate_route_decision_from_gui",
    )

    setup_command = _receiver_setup_route_command(receiver_route, values, route_path_text, run_id)
    add(
        "3. Lock one receiver lane",
        "pass" if valid_route else "fail",
        receiver_route or "-",
        (
            f"route={receiver_route or '-'}; name={receiver_name or '-'}; version={receiver_version or '-'}; "
            f"capture={capture_method or '-'}"
        ),
        "Use exactly one receiver lane for this run: uxplay, windows_receiver, wired, or capture_card.",
        setup_command,
        "Route, receiver name, version, path, start command, capture method, and AirPlay/window identity are recorded.",
        "If the selected lane changes after a failure is written, start a new run_id to avoid mixed evidence.",
        "Route JSON fields plus component metadata evidence when Record is enabled.",
        "Stop if the operator mixes UxPlay, manual screenshots, and third-party receiver output in one run.",
        "show_mainstream_route_matrix_from_gui" if not valid_route else "show_receiver_route_gate_from_gui",
    )

    if receiver_route == "uxplay":
        if doctor_report is None:
            uxplay_lane_status = "pending"
        elif uxplay_status == "pass":
            uxplay_lane_status = "pass"
        elif uxplay_status == "warn":
            uxplay_lane_status = "warn"
        else:
            uxplay_lane_status = "fail"
        uxplay_current = f"selected=True; binary:uxplay={uxplay_status}; {uxplay_message}"
    elif valid_route:
        uxplay_lane_status = "pass" if provider_ok and receiver_route in {"windows_receiver", "wired", "capture_card"} else "warn"
        uxplay_current = f"selected=False; active_route={receiver_route}; uxplay not required when Doctor records route-specific warn."
    else:
        uxplay_lane_status = "pending"
        uxplay_current = "receiver route not selected"
    add(
        "4. UxPlay install lane",
        uxplay_lane_status,
        "uxplay",
        uxplay_current,
        "For uxplay route, install/start UxPlay and make the AirPlay name unique; for alternate routes, keep Doctor's uxplay warning documented.",
        f"where.exe uxplay; {setup_command if receiver_route == 'uxplay' else '.\\.venv\\Scripts\\python -m imouse.doctor --route-decision ' + route_path_text}",
        "UxPlay route has binary:uxplay PASS, or alternate route has provider PASS and binary:uxplay WARN rather than FAIL.",
        "If uxplay is missing on the uxplay lane, either install it or switch to a documented alternate route under a fresh run_id.",
        "Doctor report, receiver start log, route JSON.",
        "Stop HID or screenshot claims while binary:uxplay is FAIL on the selected uxplay lane.",
        "run_preflight_doctor",
    )

    if receiver_route == "windows_receiver":
        windows_status = provider_status
        windows_current = (
            f"selected=True; provider={receiver_check_status}; path={receiver_path or '-'}; "
            f"window={window_title or '-'}; process={window_process or '-'}; license={license_status or '-'}; "
            f"{receiver_check_message}"
        )
    elif valid_route:
        windows_status = "pass"
        windows_current = f"selected=False; active_route={receiver_route}"
    else:
        windows_status = "pending"
        windows_current = "receiver route not selected"
    add(
        "5. Windows receiver lane",
        windows_status,
        "windows_receiver",
        windows_current,
        "If selected, start the receiver, freeze version/license, and bind a deterministic window title/process/handle.",
        _receiver_setup_route_command("windows_receiver", values, route_path_text, run_id),
        "Provider preflight is PASS, window identity is stable, and iPhone can select the exact AirPlay target.",
        "If the window title or process drifts, fix binding before collecting screenshot samples.",
        "Route JSON, license/version note, receiver log, window binding note.",
        "Stop if a commercial receiver can display video but cannot expose a stable capture target.",
        "edit_route_decision_from_gui" if windows_status != "pass" else "run_capture_quality_bench_from_gui",
    )

    if receiver_route in {"wired", "capture_card"}:
        hardware_status = provider_status
        hardware_current = (
            f"selected=True; route={receiver_route}; path={receiver_path or '-'}; "
            f"capture={capture_method or '-'}; provider={receiver_check_status}; {receiver_check_message}"
        )
    elif valid_route:
        hardware_status = "pass"
        hardware_current = f"selected=False; active_route={receiver_route}"
    else:
        hardware_status = "pending"
        hardware_current = "receiver route not selected"
    add(
        "6. Wired or capture-card lane",
        hardware_status,
        "wired/capture_card",
        hardware_current,
        "If selected, label cable/card/driver/input and prove frames can be captured automatically, not only previewed by a human.",
        _receiver_setup_route_command(receiver_route if receiver_route in {"wired", "capture_card"} else "capture_card", values, route_path_text, run_id),
        "Provider preflight is PASS and capture method/device identity are recorded for the selected iPhone.",
        "If frames exist only in a vendor preview window, bind that capture path before P1 control.",
        "Cable/card id, driver/version note, capture artifact, route JSON.",
        "Stop if physical link identity cannot be tied to device_id and screenshot artifacts.",
        "show_hardware_bench_from_gui" if hardware_status != "pass" else "run_capture_quality_bench_from_gui",
    )

    add(
        "7. Capture binding",
        binding_status,
        receiver_route or "-",
        (
            f"{binding_detail}; capture_method={capture_method or '-'}; "
            f"title={window_title or '-'}; process={window_process or '-'}"
        ),
        "Bind the selected receiver output to one deterministic capture source before quality sampling.",
        "GUI: Receiver -> Edit Route -> Shot Bench",
        "Capture binding is PASS, or a written operator note explains a non-window capture provider.",
        "Fix placeholders, title/process/handle, display index, SDK source, or capture-card input before screenshots.",
        "Route JSON binding fields plus screenshot artifact path.",
        "Stop if capture can point to the wrong device, stale frame, hidden window, or manual-only screenshot.",
        "edit_route_decision_from_gui" if binding_status != "pass" else "run_capture_quality_bench_from_gui",
    )

    airplay_required = receiver_route in {"uxplay", "windows_receiver"}
    airplay_missing = airplay_required and _receiver_setup_missing_or_placeholder(airplay_name)
    if airplay_missing:
        discovery_status = "fail"
    elif screenshot_status == "pass":
        discovery_status = "pass"
    elif valid_route:
        discovery_status = "pending"
    else:
        discovery_status = "fail"
    add(
        "8. iPhone to receiver binding",
        discovery_status,
        receiver_route or "-",
        (
            f"airplay_name={airplay_name or '-'}; screenshot={screenshot_status}; "
            f"manual={manual_status}; evidence_exists={evidence_exists}"
        ),
        "On the iPhone, connect to the exact receiver identity and keep one baseline screenshot before HID tests.",
        "GUI: Screenshot, then Shot Bench; iPhone: Control Center -> Screen Mirroring -> selected receiver.",
        "The iPhone is bound to the selected receiver and screenshot_quality is PASS for this device_id.",
        "If the iPhone cannot discover/connect, check same network, firewall, mDNS/Bonjour, duplicate names, and receiver logs.",
        "Baseline screenshot, Shot Bench samples, receiver logs.",
        "Stop if the screenshot is black, stale, cropped, wrong-window, or from another iPhone.",
        "run_capture_quality_bench_from_gui",
    )

    screenshot_gate_status = "pass" if screenshot_status == "pass" else "fail" if screenshot_status == "fail" else "pending"
    add(
        "9. Screenshot bench before HID",
        screenshot_gate_status,
        receiver_route or "-",
        f"{screenshot_text}; total_events={total_events}; fail_events={fail_events}",
        "Run repeated screenshot samples and inspect frame artifacts before click/swipe/text.",
        "GUI: Shot Bench",
        "At least one visible, non-black, correctly bound screenshot exists; P1 should then run the larger sample plan.",
        "Attach bad frames/logs and classify airplay_stream or capture failures before touching HID.",
        "Shot Bench artifacts, screenshot_quality acceptance row, callback/log attachments when failed.",
        "Stop if screenshot quality is not PASS; API success or receiver preview does not prove control.",
        "run_capture_quality_bench_from_gui",
    )

    if real_ios_verified:
        logs_status = "pass"
    elif total_events > 0 and fail_events == 0:
        logs_status = "warn"
    else:
        logs_status = "pending"
    add(
        "10. Reconnect and log attachment",
        logs_status,
        receiver_route or "-",
        f"events={total_events}; fail_events={fail_events}; real_ios_control_verified={real_ios_verified}",
        "Record reconnect attempts and attach receiver/HID logs around any failed screenshot or control path.",
        "GUI: Attach Log -> Problems -> Rerun",
        "Failures have receiver/capture/HID category, log attachment, rerun decision, and smallest affected scope.",
        "Do not rerun blindly; classify whether the failure is discovery, stream, capture, binding, HID, or business state.",
        "Attached log events, problem ledger row, rerun/recovery note.",
        "Stop promotion if logs exist but cannot be tied to device_id, route, and artifact.",
        "show_sop_problem_ledger_from_gui",
    )

    if real_ios_verified:
        claim_status = "pass"
    elif manual_status == "pass" or screenshot_status == "pass":
        claim_status = "warn"
    else:
        claim_status = "pending"
    add(
        "11. Handoff and claim boundary",
        claim_status,
        normalized_stage,
        (
            f"real_ios_control_verified={real_ios_verified}; manual={manual_status}; "
            f"screenshot={screenshot_status}; {manual_text}"
        ),
        "After receiver setup, continue through P1 Trial, Acceptance, and Readiness before making any iOS control claim.",
        f".\\.venv\\Scripts\\python -m imouse.readiness --target {normalized_stage} --evidence evidence\\{run_id}.jsonl",
        "Readiness claims real_ios_control_verified=true for the same run_id and evidence file.",
        "Keep setup success wording separate from real iPhone response and XP parity wording.",
        "P1 Trial JSONL, Acceptance report, Readiness report.",
        "Stop perfect-control or XP-parity wording until this row is PASS.",
        "run_readiness_audit" if manual_status == "pass" and screenshot_status == "pass" else "show_p1_trial_from_gui",
    )
    return rows


def receiver_setup_wizard_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts: dict[str, int] = {}
    first_gap = "none"
    selected_route = "-"
    for row in rows:
        status = str(row.get("status", "pending") or "pending").lower()
        counts[status] = counts.get(status, 0) + 1
        if first_gap == "none" and status != "pass":
            first_gap = str(row.get("step", "") or "unknown")
        route = str(row.get("route", "") or "").strip()
        if str(row.get("step", "")).startswith("3.") and route in {"uxplay", "windows_receiver", "wired", "capture_card"}:
            selected_route = route
    return (
        f"Receiver setup wizard {stage.upper()}: rows={len(rows)}, route={selected_route}, "
        f"pass={counts.get('pass', 0)}, warn={counts.get('warn', 0)}, "
        f"pending={counts.get('pending', 0)}, fail={counts.get('fail', 0)}; first_gap={first_gap}"
    )


def write_receiver_setup_wizard_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    stage: str = "p1",
    evidence_path: str | Path = "",
    route_decision_path: str | Path = "",
    readiness_report: dict | None = None,
) -> Path:
    out_path = Path(path)
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))
    lines = [
        f"# Receiver Setup Wizard {stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        f"- Route Decision: `{route_decision_path}`",
        f"- Real iOS control verified: `{real_ios_verified}`",
        "- This wizard guides receiver install/binding only. It does not install software, write JSONL evidence, or start a receiver, and it does not prove real iPhone response.",
        "",
        "## Setup Rows",
        "",
        "| Step | Status | Route | Current | Operator action | Command | Pass criteria | Failure handling | Evidence | Stop rule | GUI action |",
        "|---|---|---|---|---|---|---|---|---|---|---|",
    ]
    commands: list[str] = []
    seen_commands: set[str] = set()
    for row in rows:
        command = str(row.get("command", "") or "").strip()
        if command and not command.startswith("GUI:") and command not in seen_commands:
            seen_commands.add(command)
            commands.append(command)
        lines.append(
            f"| {_md_cell(row.get('step', ''))} | `{_md_cell(row.get('status', ''))}` | "
            f"{_md_cell(row.get('route', ''))} | {_md_cell(row.get('current', ''))} | "
            f"{_md_cell(row.get('operator_action', ''))} | `{_md_cell(command)}` | "
            f"{_md_cell(row.get('pass_criteria', ''))} | {_md_cell(row.get('failure_handling', ''))} | "
            f"{_md_cell(row.get('evidence', ''))} | {_md_cell(row.get('stop_rule', ''))} | "
            f"{_md_cell(row.get('gui_action', ''))} |"
        )
    if not rows:
        lines.append("| None | `pending` | - | no rows built | Refresh wizard | - | - | - | - | - | - |")
    lines.extend(["", "## Copy-Ready Commands", ""])
    if commands:
        lines.append("```powershell")
        lines.extend(commands)
        lines.append("```")
    else:
        lines.append("- No terminal command is available yet; complete the route decision first.")
    lines.extend([
        "",
        "## Review Rule",
        "",
        "Treat this as a setup and routing guide. P1 still requires JSONL evidence, visible screenshots, manual real-iPhone observations, Acceptance PASS, and Readiness PASS before claiming iOS control or XP parity.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


def _receiver_evidence_gui_action(method: str) -> str:
    return {
        "edit_route_decision_from_gui": "Edit Route",
        "validate_route_decision_from_gui": "Validate Route",
        "run_preflight_doctor": "Run Doctor",
        "show_receiver_route_gate_from_gui": "Open Receiver",
        "show_receiver_setup_wizard_from_gui": "Open Rx Setup",
        "run_capture_quality_bench_from_gui": "Run Shot Bench",
        "show_p1_trial_from_gui": "Open P1 Trial",
        "attach_callback_log_from_gui": "Attach Log",
        "show_control_evidence_ledger_from_gui": "Open Ctrl Ledger",
        "run_acceptance_from_gui": "Run Acceptance",
        "run_readiness_audit": "Run Readiness",
    }.get(method, method)


def _receiver_evidence_command(
    name: str,
    *,
    run_id: str,
    stage: str,
    route_decision_path: str,
    evidence_path: str,
) -> str:
    if name == "route_validate":
        return (
            f".\\.venv\\Scripts\\python -m imouse.route_decision validate {route_decision_path} "
            f"--require-ready --markdown evidence\\{run_id}_route_decision.md"
        )
    if name == "doctor":
        return (
            f".\\.venv\\Scripts\\python -m imouse.doctor --route-decision {route_decision_path} "
            f"--markdown evidence\\{run_id}_doctor.md"
        )
    if name == "capture_dry_run":
        return (
            f".\\.venv\\Scripts\\python -m imouse.script_runner "
            f"scripts\\p1_receiver_capture_probe.json --run-id {run_id} --dry-run"
        )
    if name == "capture_real_run":
        return (
            f".\\.venv\\Scripts\\python -m imouse.script_runner "
            f"scripts\\p1_receiver_capture_probe.json --run-id {run_id}"
        )
    if name == "acceptance":
        return (
            f".\\.venv\\Scripts\\python -m imouse.acceptance {evidence_path} --gate {stage} "
            f"--markdown evidence\\{run_id}_{stage}_acceptance.md "
            f"--gap-markdown evidence\\{run_id}_{stage}_acceptance_gap.md"
        )
    if name == "readiness":
        return (
            f".\\.venv\\Scripts\\python -m imouse.readiness --target {stage} --evidence {evidence_path} "
            f"--markdown evidence\\{run_id}_{stage}_readiness.md"
        )
    return ""


def receiver_evidence_checklist_rows(
    *,
    stage: str = "p1",
    docs_root: str | Path = ".",
    route_decision: dict | None = None,
    route_report: dict | None = None,
    doctor_report: dict | None = None,
    acceptance_report: dict | None = None,
    readiness_report: dict | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
    receiver_report: dict | None = None,
    route_decision_path: str | Path = "",
    evidence_path: str | Path = "",
) -> list[dict[str, str]]:
    """Build the receiver/capture evidence checklist without writing evidence."""
    normalized_stage = stage.lower().strip() or "p1"
    route_path_text = str(route_decision_path or "").strip() or "evidence/<run_id>_route_decision.json"
    run_id = str((route_decision or {}).get("run_id", "<run_id>") or "<run_id>")
    evidence_path_text = str(evidence_path or f"evidence/{run_id}.jsonl")
    values = route_decision_form_values(route_decision or {}) if route_decision else {}
    receiver_route = _receiver_setup_value(values, route_decision, "receiver.route")
    receiver_name = _receiver_setup_value(values, route_decision, "receiver.name")
    receiver_version = _receiver_setup_value(values, route_decision, "receiver.version")
    receiver_path = _receiver_setup_value(values, route_decision, "receiver.path")
    receiver_start = _receiver_setup_value(values, route_decision, "receiver.start_command")
    airplay_name = _receiver_setup_value(values, route_decision, "receiver.airplay_name")
    capture_method = _receiver_setup_value(values, route_decision, "receiver.capture_method")
    window_title = _receiver_setup_value(values, route_decision, "receiver.window_binding.title")
    window_process = _receiver_setup_value(values, route_decision, "receiver.window_binding.process")
    hid_route = _receiver_setup_value(values, route_decision, "hid.route")
    hid_id = _receiver_setup_value(values, route_decision, "hid.id")
    iphone_model = _receiver_setup_value(values, route_decision, "iphone.model")
    ios_version = _receiver_setup_value(values, route_decision, "iphone.ios_version")
    valid_route = receiver_route in {"uxplay", "windows_receiver", "wired", "capture_card"}
    route_ready = bool(route_report and route_report.get("ok") and route_report.get("ready"))

    if receiver_report is None:
        try:
            if route_decision:
                receiver_report = evaluate_receiver_provider(
                    receiver_config_from_decision(route_decision),
                    root=docs_root,
                )
            else:
                receiver_report = evaluate_receiver_provider(None, root=docs_root)
        except Exception as exc:
            receiver_report = {
                "status": "fail",
                "route": receiver_route,
                "message": f"Receiver provider evaluation failed: {exc}",
                "details": {},
            }
    provider_status = _receiver_gate_status_from_provider(receiver_report)
    provider_ok = str(receiver_report.get("status", "") or "").lower() == "ok"
    provider_route = str(receiver_report.get("route", "") or receiver_route or "").strip()
    uxplay_status, uxplay_message, _uxplay_details = _probe_check_line(doctor_report, "binary:uxplay")
    receiver_check_status, receiver_check_message, _receiver_details = _probe_check_line(
        doctor_report,
        "receiver_provider",
    )
    doctor_overall = str((doctor_report or {}).get("overall", "") or "").lower()
    doctor_ok = bool(doctor_report and _doctor_allows_real_run(doctor_report))
    summary = evidence_summary or {}
    status_counts = summary.get("by_status", {}) if isinstance(summary.get("by_status"), dict) else {}
    total_events = int(summary.get("total", 0) or 0)
    fail_events = int(status_counts.get("fail", 0) or 0)
    metric_count = int(summary.get("metrics", {}).get("count", 0) or 0) if isinstance(summary.get("metrics"), dict) else 0
    screenshot_status, screenshot_text = _acceptance_check_line(acceptance_report, "screenshot_quality")
    manual_status, manual_text = _acceptance_check_line(acceptance_report, "manual_observation")
    component_status, component_text = _acceptance_check_line(acceptance_report, "component_traceability")
    readiness_ok = bool(readiness_report and readiness_report.get("ok"))
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))
    binding_status, binding_detail = _receiver_capture_binding_gate(route_decision)

    def command(name: str) -> str:
        return _receiver_evidence_command(
            name,
            run_id=run_id,
            stage=normalized_stage,
            route_decision_path=route_path_text,
            evidence_path=evidence_path_text,
        )

    rows: list[dict[str, str]] = []

    def add(
        checkpoint: str,
        status: str,
        current: str,
        operator_step: str,
        command_text: str,
        artifact: str,
        pass_criteria: str,
        stop_rule: str,
        method: str,
    ) -> None:
        rows.append({
            "checkpoint": checkpoint,
            "status": status,
            "route": receiver_route or "-",
            "current": current,
            "operator_step": operator_step,
            "command": command_text,
            "artifact": artifact,
            "pass_criteria": pass_criteria,
            "stop_rule": stop_rule,
            "gui_action": _receiver_evidence_gui_action(method),
            "method": method,
        })

    if not route_decision:
        route_status = "fail"
        route_current = f"loaded=False; path={route_path_text}"
    elif route_report is None:
        route_status = "pending"
        route_current = (
            f"loaded=True; route={receiver_route or '-'}; receiver={receiver_name or '-'}; "
            "validation has not been run"
        )
    else:
        route_status = "pass" if route_ready else "fail"
        route_current = route_decision_brief(route_report)
    add(
        "1. Lock one receiver route",
        route_status,
        route_current,
        "Use exactly one receiver route for this run_id and record real receiver, HID, iPhone, Hub, cable, and operator fields.",
        command("route_validate"),
        "Route Decision JSON and route decision Markdown.",
        "Route validation is PASS, ready=true, allowed_to_run_p1=true, and open blockers are empty.",
        "Stop if placeholders remain, the route is mixed, or a failed route decision was already recorded under this run_id.",
        "edit_route_decision_from_gui" if route_status != "pass" else "run_preflight_doctor",
    )

    add(
        "2. Receiver provider preflight",
        provider_status,
        (
            f"{receiver_provider_brief(receiver_report)}; route={provider_route or '-'}; "
            f"name={receiver_name or '-'}; version={receiver_version or '-'}; path={receiver_path or '-'}"
        ),
        "Confirm the selected provider can be preflighted from route data before starting screenshot or HID work.",
        "",
        "Receiver provider report, route JSON, receiver version/path/start command.",
        "Provider status is PASS for the selected receiver route.",
        "Stop if provider path, capture method, AirPlay name, or window binding is missing or placeholder-shaped.",
        "show_receiver_setup_wizard_from_gui" if provider_status != "pass" else "run_preflight_doctor",
    )

    if doctor_report is None:
        doctor_status = "pending"
        doctor_current = "Doctor has not been run with this Route Decision."
    elif doctor_ok:
        doctor_status = "pass"
        doctor_current = (
            f"{doctor_brief(doctor_report)}; receiver_provider={receiver_check_status}; "
            f"binary:uxplay={uxplay_status}; {uxplay_message}"
        )
    else:
        doctor_status = "fail"
        doctor_current = (
            f"{doctor_brief(doctor_report)}; receiver_provider={receiver_check_status}; "
            f"binary:uxplay={uxplay_status}; {receiver_check_message}"
        )
    add(
        "3. Route-aware Doctor",
        doctor_status,
        doctor_current,
        "Run Doctor with the Route Decision path so alternate receiver routes do not inherit the default UxPlay hard fail.",
        command("doctor"),
        "Doctor Markdown plus receiver/HID install notes if any warning remains.",
        "Doctor has no fail checks. Route-specific warnings are documented by the operator.",
        "Stop if Doctor still fails; do not disable Dry Run or call lower-level APIs around this failure.",
        "run_preflight_doctor" if doctor_status != "pass" else "show_receiver_route_gate_from_gui",
    )

    if not valid_route:
        identity_status = "fail"
    else:
        identity_status = binding_status
        if receiver_route in {"uxplay", "windows_receiver"} and _receiver_setup_missing_or_placeholder(airplay_name):
            identity_status = _worst_status(identity_status, "fail")
        if receiver_route == "windows_receiver" and _receiver_setup_missing_or_placeholder(window_title):
            identity_status = _worst_status(identity_status, "fail")
    add(
        "4. Bind receiver identity to device",
        identity_status,
        (
            f"route={receiver_route or '-'}; airplay={airplay_name or '-'}; capture={capture_method or '-'}; "
            f"title={window_title or '-'}; process={window_process or '-'}; {binding_detail}"
        ),
        "On the iPhone, connect to the exact receiver identity and verify the capture source maps to the selected device_id.",
        "",
        "Route binding fields, operator photo/recording, receiver log, first screenshot artifact path.",
        "The receiver identity, capture binding, iPhone model/iOS, HID id, and device_id are traceable together.",
        "Stop if a human-visible window cannot be tied to a code-captured frame for the selected iPhone.",
        "edit_route_decision_from_gui" if identity_status != "pass" else "run_capture_quality_bench_from_gui",
    )

    if screenshot_status == "pass":
        baseline_status = "pass"
    elif screenshot_status == "fail":
        baseline_status = "fail"
    elif doctor_status == "pass" and identity_status == "pass":
        baseline_status = "pending"
    else:
        baseline_status = "fail"
    add(
        "5. Baseline screenshot proof",
        baseline_status,
        f"{screenshot_text}; evidence_exists={evidence_exists}; total_events={total_events}",
        "Capture one current, non-black, correctly oriented screenshot before any HID click/swipe/text trial.",
        command("capture_dry_run"),
        "Shot Bench artifact or screenshot_quality evidence row for the same run_id.",
        "A visible screenshot is reviewed and Acceptance screenshot_quality is PASS.",
        "Stop if the frame is black, stale, cropped, wrong-window, wrong-device, rotated unexpectedly, or only manually captured.",
        "run_capture_quality_bench_from_gui",
    )

    if fail_events:
        probe_status = "fail"
    elif screenshot_status == "pass" and total_events > 0 and metric_count > 0:
        probe_status = "ready"
    elif screenshot_status == "pass" and total_events > 0:
        probe_status = "warn"
    elif baseline_status == "pass":
        probe_status = "pending"
    else:
        probe_status = "fail" if baseline_status == "fail" else "pending"
    add(
        "6. Receiver capture probe set",
        probe_status,
        f"events={total_events}; fail_events={fail_events}; metrics={metric_count}; screenshot={screenshot_status}",
        "Run the receiver capture probe after editing placeholder metadata in the script or recording equivalent GUI evidence.",
        command("capture_real_run"),
        "JSONL events, saved screenshot artifacts, metrics samples, receiver/capture logs.",
        "The probe has no fail events, screenshot samples are reviewable, and metrics/log context is attached.",
        "Stop before HID if the probe hides receiver/capture failures or records placeholder metadata as pass.",
        "run_capture_quality_bench_from_gui" if probe_status != "ready" else "show_p1_trial_from_gui",
    )

    if fail_events:
        log_status = "warn"
    elif total_events > 0 and metric_count > 0:
        log_status = "ready"
    elif total_events > 0:
        log_status = "pending"
    else:
        log_status = "pending"
    add(
        "7. Reconnect and log triage",
        log_status,
        f"route={receiver_route or '-'}; events={total_events}; fail_events={fail_events}; metrics={metric_count}",
        "Attach receiver/HID logs around discovery, pairing, stream, capture, binding, reconnect, and performance failures.",
        "",
        "Attach Log output, Problems ledger, Rerun/Recovery notes, bad-frame artifacts.",
        "Every failure has category, artifact, device_id, receiver/HID context, and a smallest-rerun decision.",
        "Stop scaling if a receiver/capture failure cannot be isolated to device, route, window, cable, or log line.",
        "attach_callback_log_from_gui" if log_status != "ready" else "show_p1_trial_from_gui",
    )

    if manual_status == "pass":
        handoff_status = "pass"
    elif screenshot_status == "pass" and doctor_status == "pass":
        handoff_status = "pending"
    elif manual_status == "fail":
        handoff_status = "fail"
    else:
        handoff_status = "fail" if doctor_status == "fail" or baseline_status == "fail" else "pending"
    add(
        "8. HID handoff stop line",
        handoff_status,
        (
            f"manual={manual_status}; screenshot={screenshot_status}; "
            f"hid={hid_route or '-'}:{hid_id or '-'}; {manual_text}"
        ),
        "Only after receiver evidence is clean, move to P1 Trial for click, swipe, and text observations.",
        "",
        "P1 Trial JSONL, lane-separated Manual observations, Control Ledger rows.",
        "Manual click, swipe, and text input observations are recorded against the real iPhone.",
        "Stop if screenshot proof is missing, Doctor failed, or Manual observation is generic rather than lane-specific.",
        "show_p1_trial_from_gui" if handoff_status != "pass" else "show_control_evidence_ledger_from_gui",
    )

    if readiness_ok and real_ios_verified:
        promotion_status = "pass"
    elif acceptance_report is not None or readiness_report is not None:
        promotion_status = "fail"
    else:
        promotion_status = "pending"
    add(
        "9. Acceptance and claim closure",
        promotion_status,
        (
            f"component={component_status}; screenshot={screenshot_status}; manual={manual_status}; "
            f"readiness_ok={readiness_ok}; real_ios_verified={real_ios_verified}; "
            f"iphone={iphone_model or '-'}:{ios_version or '-'}; {component_text}"
        ),
        "Run Acceptance and Readiness after the same-run receiver, screenshot, HID, and manual evidence exists.",
        f"{command('acceptance')}\n{command('readiness')}",
        "Acceptance Markdown, Acceptance Gap Markdown, Readiness Markdown, Evidence Pack.",
        "Acceptance and Readiness PASS for the same run_id and exact device/iOS/receiver/HID scope.",
        "Stop all perfect-control, group-control, broad-compatibility, or XP-parity wording while this row is not PASS.",
        "run_acceptance_from_gui" if promotion_status != "pass" else "run_readiness_audit",
    )
    return rows


def receiver_evidence_checklist_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts = _row_status_counts(rows)
    first_stop = _first_attention_value(rows, "checkpoint", statuses={"fail", "pending", "warn"})
    return (
        f"Receiver evidence checklist {stage.upper()}: "
        f"pass={counts.get('pass', 0)}, ready={counts.get('ready', 0)}, "
        f"warn={counts.get('warn', 0)}, fail={counts.get('fail', 0)}, "
        f"pending={counts.get('pending', 0)}; first_stop={first_stop}"
    )


def write_receiver_evidence_checklist_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    stage: str = "p1",
    evidence_path: str | Path = "",
    route_decision_path: str | Path = "",
    readiness_report: dict | None = None,
) -> Path:
    out_path = Path(path)
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))
    lines = [
        f"# Receiver Evidence Checklist {stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        f"- Route Decision: `{route_decision_path}`",
        f"- Real iOS control verified: `{real_ios_verified}`",
        "- This export is a receiver/capture evidence SOP. The export itself does not write JSONL evidence, does not prove real iPhone response, and does not prove XP parity.",
        "",
        "## Checklist Rows",
        "",
        "| Checkpoint | Status | Route | Current | Operator step | Command | Artifact | Pass criteria | Stop rule | GUI action |",
        "|---|---|---|---|---|---|---|---|---|---|",
    ]
    commands: list[str] = []
    seen_commands: set[str] = set()
    for row in rows:
        command = str(row.get("command", "") or "").strip()
        if command and command not in seen_commands:
            seen_commands.add(command)
            commands.append(command)
        lines.append(
            f"| {_md_cell(row.get('checkpoint', ''))} | `{_md_cell(row.get('status', ''))}` | "
            f"{_md_cell(row.get('route', ''))} | {_md_cell(row.get('current', ''))} | "
            f"{_md_cell(row.get('operator_step', ''))} | `{_md_cell(command)}` | "
            f"{_md_cell(row.get('artifact', ''))} | {_md_cell(row.get('pass_criteria', ''))} | "
            f"{_md_cell(row.get('stop_rule', ''))} | {_md_cell(row.get('gui_action', ''))} |"
        )
    if not rows:
        lines.append("| None | `pending` | - | no rows built | Refresh checklist | - | - | - | Do not claim | - |")
    lines.extend(["", "## Copy-Ready Commands", ""])
    if commands:
        lines.append("```powershell")
        lines.extend(commands)
        lines.append("```")
    else:
        lines.append("- No terminal command is available yet; complete the route decision first.")
    lines.extend([
        "",
        "## Review Rule",
        "",
        "Use this checklist after Rx Setup and before P1 Trial. It can organize receiver evidence, but only same-run JSONL events, saved artifacts, lane-separated Manual observations, Acceptance PASS, Readiness PASS, and exact device/iOS/receiver/HID scope can support an iOS control claim.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


