def _receiver_score_add(
    score_parts: list[str],
    strengths: list[str],
    gaps: list[str],
    label: str,
    points: int,
    max_points: int,
    text: str,
    *,
    good: bool = True,
) -> int:
    score_parts.append(f"{label}={points}/{max_points}")
    if good and points > 0:
        strengths.append(text)
    else:
        gaps.append(text)
    return points


def receiver_candidate_scorecard_rows(
    *,
    stage: str = "p1",
    docs_root: str | Path = ".",
    route_decision: dict | None = None,
    route_report: dict | None = None,
    doctor_report: dict | None = None,
    acceptance_report: dict | None = None,
    readiness_report: dict | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
    receiver_report: dict | None = None,
    route_decision_path: str | Path = "",
) -> list[dict[str, str]]:
    """Rank receiver candidates for the next field run without proving iOS control."""
    root = Path(docs_root)
    normalized_stage = stage.lower().strip() or "p1"
    route_path_text = str(route_decision_path or "").strip() or "evidence/<run_id>_route_decision.json"
    values = route_decision_form_values(route_decision or {}) if route_decision else {}
    receiver_route = _receiver_setup_value(values, route_decision, "receiver.route")
    receiver_name = _receiver_setup_value(values, route_decision, "receiver.name")
    receiver_version = _receiver_setup_value(values, route_decision, "receiver.version")
    receiver_path = _receiver_setup_value(values, route_decision, "receiver.path")
    receiver_start = _receiver_setup_value(values, route_decision, "receiver.start_command")
    capture_method = _receiver_setup_value(values, route_decision, "receiver.capture_method")
    airplay_name = _receiver_setup_value(values, route_decision, "receiver.airplay_name")
    window_title = _receiver_setup_value(values, route_decision, "receiver.window_binding.title")
    window_process = _receiver_setup_value(values, route_decision, "receiver.window_binding.process")
    license_status = _receiver_setup_value(values, route_decision, "receiver.license_status")
    selected_route_valid = receiver_route in {"uxplay", "windows_receiver", "wired", "capture_card"}
    selected_route_unknown = not receiver_route or _route_form_has_placeholder(receiver_route)

    if receiver_report is None:
        try:
            if route_decision:
                receiver_report = evaluate_receiver_provider(
                    receiver_config_from_decision(route_decision),
                    root=root,
                )
            else:
                receiver_report = evaluate_receiver_provider(None, root=root)
        except Exception as exc:
            receiver_report = {
                "status": "fail",
                "route": receiver_route,
                "message": f"Receiver provider evaluation failed: {exc}",
                "details": {},
            }
    provider_status = _receiver_gate_status_from_provider(receiver_report)
    provider_ok = str(receiver_report.get("status", "") or "").lower() == "ok"
    route_ready = bool(route_report and route_report.get("ok") and route_report.get("ready"))
    route_validated = route_report is not None
    doctor_overall = str((doctor_report or {}).get("overall", "") or "").lower()
    doctor_failed = doctor_overall == "fail"
    doctor_fail_names = [
        str(item.get("name", "") or "")
        for item in (doctor_report or {}).get("checks", []) or []
        if isinstance(item, dict) and str(item.get("status", "") or "").lower() == "fail"
    ]
    uxplay_status, uxplay_message, _uxplay_details = _probe_check_line(doctor_report, "binary:uxplay")
    screenshot_status, screenshot_text = _acceptance_check_line(acceptance_report, "screenshot_quality")
    manual_status, manual_text = _acceptance_check_line(acceptance_report, "manual_observation")
    binding_status, binding_detail = _receiver_capture_binding_gate(route_decision)
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))
    summary = evidence_summary or {}
    status_counts = summary.get("by_status", {}) if isinstance(summary.get("by_status"), dict) else {}
    total_events = int(summary.get("total", 0) or 0)
    fail_events = int(status_counts.get("fail", 0) or 0)

    rows: list[dict[str, str]] = []
    for topic in RECEIVER_CANDIDATE_ROUTES:
        route = str(topic["route"])
        selected = receiver_route == route
        strengths: list[str] = []
        gaps: list[str] = []
        score_parts: list[str] = []
        score = 0
        source_status = "pass" if (root / str(topic["source"])).exists() else "fail"
        if source_status == "pass":
            score += _receiver_score_add(
                score_parts,
                strengths,
                gaps,
                "source",
                5,
                5,
                f"source exists: {topic['source']}",
            )
        else:
            _receiver_score_add(
                score_parts,
                strengths,
                gaps,
                "source",
                0,
                5,
                f"source missing: {topic['source']}",
                good=False,
            )

        if not route_decision:
            score += _receiver_score_add(
                score_parts,
                strengths,
                gaps,
                "route",
                0,
                10,
                f"route decision missing at {route_path_text}",
                good=False,
            )
        elif selected:
            route_points = 10 if route_ready else 5 if route_validated else 3
            score += _receiver_score_add(
                score_parts,
                strengths,
                gaps,
                "route",
                route_points,
                10,
                f"selected route={route}; route_ready={route_ready}",
                good=route_points >= 8,
            )
        elif selected_route_unknown:
            score += _receiver_score_add(
                score_parts,
                strengths,
                gaps,
                "route",
                0,
                10,
                f"receiver.route is missing or placeholder: {receiver_route or '-'}",
                good=False,
            )
        else:
            score += _receiver_score_add(
                score_parts,
                strengths,
                gaps,
                "route",
                2,
                10,
                f"backup candidate while selected route={receiver_route}",
                good=False,
            )

        if route == "uxplay":
            if uxplay_status == "pass":
                install_points = 18
            elif uxplay_status == "warn":
                install_points = 9
            else:
                install_points = 0
            score += _receiver_score_add(
                score_parts,
                strengths,
                gaps,
                "install",
                install_points,
                18,
                f"binary:uxplay={uxplay_status}; {uxplay_message}",
                good=install_points >= 12,
            )
        elif selected:
            if provider_status == "pass":
                install_points = 18
            elif provider_status == "warn":
                install_points = 8
            else:
                install_points = 0
            score += _receiver_score_add(
                score_parts,
                strengths,
                gaps,
                "install",
                install_points,
                18,
                f"provider={provider_status}; {receiver_report.get('message', '')}",
                good=install_points >= 12,
            )
        else:
            backup_points = 8 if route in {"windows_receiver", "wired", "capture_card"} else 4
            score += _receiver_score_add(
                score_parts,
                strengths,
                gaps,
                "install",
                backup_points,
                18,
                "not selected; needs provider metadata before field use",
                good=False,
            )

        if selected:
            if binding_status == "pass":
                binding_points = 18
            elif binding_status == "warn":
                binding_points = 8
            else:
                binding_points = 0
            score += _receiver_score_add(
                score_parts,
                strengths,
                gaps,
                "binding",
                binding_points,
                18,
                f"{binding_status}: {binding_detail}",
                good=binding_points >= 12,
            )
        else:
            score += _receiver_score_add(
                score_parts,
                strengths,
                gaps,
                "binding",
                int(topic["backup_capture_score"]),
                18,
                f"candidate capture profile: {topic['integration_points']}",
                good=False,
            )

        if selected:
            if screenshot_status == "pass":
                screenshot_points = 14
            elif screenshot_status == "fail":
                screenshot_points = 0
            else:
                screenshot_points = 4 if evidence_exists else 0
            score += _receiver_score_add(
                score_parts,
                strengths,
                gaps,
                "screenshot",
                screenshot_points,
                14,
                f"screenshot={screenshot_status}; {screenshot_text}",
                good=screenshot_points >= 10,
            )
        else:
            _receiver_score_add(
                score_parts,
                strengths,
                gaps,
                "screenshot",
                0,
                14,
                "no screenshot proof for this candidate in the current run",
                good=False,
            )

        if real_ios_verified:
            log_points = 8
            log_text = "Readiness says real_ios_control_verified=true"
            log_good = True
        elif total_events > 0 and fail_events == 0:
            log_points = 5
            log_text = f"events={total_events}; fail_events=0"
            log_good = True
        elif fail_events:
            log_points = 0
            log_text = f"events={total_events}; fail_events={fail_events}"
            log_good = False
        else:
            log_points = 0
            log_text = "no field events or receiver reconnect logs yet"
            log_good = False
        score += _receiver_score_add(
            score_parts,
            strengths,
            gaps,
            "logs",
            log_points,
            8,
            log_text,
            good=log_good,
        )

        score += _receiver_score_add(
            score_parts,
            strengths,
            gaps,
            "python",
            int(topic["python_score"]),
            12,
            str(topic["integration_points"]),
        )

        if route == "windows_receiver":
            license_text = license_status or "license/status missing"
            if _receiver_setup_missing_or_placeholder(license_status):
                license_points = 2
                license_good = False
            elif "trial" in license_status.lower():
                license_points = 4
                license_good = False
            else:
                license_points = int(topic["license_score"])
                license_good = True
        else:
            license_text = str(topic["risk_profile"])
            license_points = int(topic["license_score"])
            license_good = True
        score += _receiver_score_add(
            score_parts,
            strengths,
            gaps,
            "license",
            license_points,
            10,
            license_text,
            good=license_good,
        )

        score += _receiver_score_add(
            score_parts,
            strengths,
            gaps,
            "xp",
            int(topic["xp_score"]),
            10,
            str(topic["best_for"]),
        )

        hard_block = False
        if source_status == "fail":
            hard_block = True
        if not route_decision:
            hard_block = route == "uxplay" and uxplay_status == "fail"
        elif selected:
            if route_validated and not route_ready:
                hard_block = True
            if provider_status == "fail":
                hard_block = True
            if binding_status == "fail":
                hard_block = True
            if screenshot_status == "fail":
                hard_block = True
            if route == "uxplay" and uxplay_status == "fail":
                hard_block = True
            if route != "uxplay" and doctor_failed and "binary:uxplay" in doctor_fail_names:
                hard_block = True
        elif route == "uxplay" and uxplay_status == "fail" and not selected_route_valid:
            hard_block = True

        if hard_block:
            status = "fail"
        elif selected and real_ios_verified:
            status = "pass"
        elif (
            selected
            and route_ready
            and provider_ok
            and binding_status == "pass"
            and screenshot_status == "pass"
            and fail_events == 0
        ):
            status = "ready"
        elif selected:
            if not route_validated or not doctor_report:
                status = "pending"
            elif doctor_overall == "warn" or provider_status == "warn" or binding_status == "warn":
                status = "warn"
            else:
                status = "pending"
        elif selected_route_valid:
            status = "warn"
        else:
            status = "pending"

        if selected:
            method = "show_receiver_setup_wizard_from_gui" if status != "fail" else "edit_route_decision_from_gui"
        elif status == "fail":
            method = "run_preflight_doctor" if route == "uxplay" else "edit_route_decision_from_gui"
        elif not route_decision:
            method = "edit_route_decision_from_gui"
        else:
            method = str(topic["method"])

        current = (
            f"stage={normalized_stage.upper()}; selected={selected}; route={receiver_route or '-'}; "
            f"name={receiver_name or '-'}; version={receiver_version or '-'}; path={receiver_path or '-'}; "
            f"start={receiver_start or '-'}; airplay={airplay_name or '-'}; capture={capture_method or '-'}; "
            f"window={window_title or '-'}; process={window_process or '-'}; doctor={doctor_overall or '-'}; "
            f"binary:uxplay={uxplay_status}; screenshot={screenshot_status}; manual={manual_status}; "
            f"events={total_events}; fail_events={fail_events}"
        )
        if status == "fail":
            next_action = "Fix the first hard blocker before collecting screenshots or HID observations."
            stop_rule = "Stop receiver switching or control claims until the hard blocker is recorded as fixed under a clean run_id."
        elif selected and status in {"ready", "pass"}:
            next_action = "Keep this receiver route and continue through P1 Trial, Acceptance, and Readiness."
            stop_rule = "Do not claim perfect iOS control or XP parity until manual JSONL evidence and Readiness pass."
        elif selected:
            next_action = "Complete route validation, Doctor, capture binding, and screenshot bench for the selected receiver."
            stop_rule = "Stop if setup success is not backed by a current nonblank screenshot."
        elif not route_decision:
            next_action = "Create or edit Route Decision before choosing a receiver candidate."
            stop_rule = "Stop if the run has no route file; scorecard selection alone is not evidence."
        else:
            next_action = "Keep as backup; switch only with a fresh route decision/run_id after a recorded failure."
            stop_rule = "Do not mix candidate routes in one field evidence run."

        rows.append({
            "candidate": str(topic["candidate"]),
            "route": route,
            "status": status,
            "selected": "yes" if selected else "no",
            "recommendation": "candidate",
            "score": str(min(score, 100)),
            "score_parts": "; ".join(score_parts),
            "current": current,
            "strengths": "; ".join(strengths[:4]) or "-",
            "gaps": "; ".join(gaps[:5]) or "-",
            "next_action": next_action,
            "evidence": (
                "Route Decision, Doctor with route decision, screenshot artifacts, receiver logs, "
                "P1 Trial JSONL, Acceptance, and Readiness for the same run_id."
            ),
            "stop_rule": stop_rule,
            "source": str(topic["source"]),
            "risk": str(topic["risk_profile"]),
            "gui_action": _receiver_candidate_scorecard_gui_action(method),
            "method": method,
        })

    selected_rows = [
        row for row in rows
        if row.get("selected") == "yes" and row.get("status") in {"pass", "ready", "warn", "pending"}
    ]
    ready_rows = [
        row for row in rows
        if row.get("status") in {"pass", "ready"} and row.get("selected") != "yes"
    ]
    eligible = selected_rows or ready_rows
    best_row = max(eligible, key=lambda row: int(row.get("score", "0") or 0), default=None)
    for row in rows:
        if row is best_row:
            row["recommendation"] = "recommended"
        elif row.get("status") == "fail":
            row["recommendation"] = "blocked"
        elif not route_decision:
            row["recommendation"] = "route-needed"
        elif row.get("selected") == "yes":
            row["recommendation"] = "selected-needs-proof"
        else:
            row["recommendation"] = "backup"
    return rows


def receiver_candidate_scorecard_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts: dict[str, int] = {}
    recommended = "none"
    first_gap = "none"
    best_score = "0"
    for row in rows:
        status = str(row.get("status", "pending") or "pending").lower()
        counts[status] = counts.get(status, 0) + 1
        if row.get("recommendation") == "recommended":
            recommended = str(row.get("candidate", "") or "unknown")
            best_score = str(row.get("score", "0") or "0")
        if first_gap == "none" and status in {"fail", "pending"}:
            first_gap = str(row.get("candidate", "") or "unknown")
    return (
        f"Receiver candidate scorecard {stage.upper()}: rows={len(rows)}, "
        f"pass={counts.get('pass', 0)}, ready={counts.get('ready', 0)}, "
        f"warn={counts.get('warn', 0)}, pending={counts.get('pending', 0)}, "
        f"fail={counts.get('fail', 0)}; recommended={recommended}; "
        f"score={best_score}; first_gap={first_gap}"
    )


def write_receiver_candidate_scorecard_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    stage: str = "p1",
    evidence_path: str | Path = "",
    route_decision_path: str | Path = "",
    readiness_report: dict | None = None,
) -> Path:
    out_path = Path(path)
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))
    lines = [
        f"# Receiver Candidate Scorecard {stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        f"- Route Decision: `{route_decision_path}`",
        f"- Real iOS control verified: `{real_ios_verified}`",
        "- This scorecard ranks receiver candidates only. It does not write JSONL evidence, start a receiver, prove real iPhone response, prove iOS perfect control, or prove XP parity.",
        "",
        "## Candidate Rows",
        "",
        "| Candidate | Route | Status | Recommendation | Selected | Score | Current signal | Strengths | Gaps | Next action | Evidence | Stop rule | Source | GUI action |",
        "|---|---|---|---|---|---|---|---|---|---|---|---|---|---|",
    ]
    for row in rows:
        lines.append(
            f"| {_md_cell(row.get('candidate', ''))} | {_md_cell(row.get('route', ''))} | "
            f"`{_md_cell(row.get('status', ''))}` | {_md_cell(row.get('recommendation', ''))} | "
            f"{_md_cell(row.get('selected', ''))} | {_md_cell(row.get('score', ''))} | "
            f"{_md_cell(row.get('current', ''))} | {_md_cell(row.get('strengths', ''))} | "
            f"{_md_cell(row.get('gaps', ''))} | {_md_cell(row.get('next_action', ''))} | "
            f"{_md_cell(row.get('evidence', ''))} | {_md_cell(row.get('stop_rule', ''))} | "
            f"{_md_cell(row.get('source', ''))} | {_md_cell(row.get('gui_action', ''))} |"
        )
    if not rows:
        lines.append("| None | - | `pending` | route-needed | no | 0 | no rows built | - | Refresh Scorecard | Refresh | - | Do not promote | - | - |")
    lines.extend([
        "",
        "## Score Parts",
        "",
    ])
    for row in rows:
        lines.append(f"- {row.get('candidate', '')}: {row.get('score_parts', '')}")
    if not rows:
        lines.append("- No score parts available.")
    lines.extend([
        "",
        "## Review Rule",
        "",
        "Use the recommended row only to choose the next receiver route to validate. A receiver recommendation still needs route validation, Doctor, visible screenshot quality, Manual/P1 Trial JSONL, Acceptance PASS, and Readiness PASS before any iOS control claim.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


def gui_knowledge_center_rows(
    *,
    stage: str = "p1",
    docs_root: str | Path = ".",
    route_report: dict | None = None,
    doctor_report: dict | None = None,
    acceptance_report: dict | None = None,
    readiness_report: dict | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
    xp_gap_audit: dict | None = None,
) -> list[dict[str, str]]:
    """Build the industry/SOP knowledge dashboard rows without writing evidence."""
    root = Path(docs_root)
    normalized_stage = stage.lower().strip() or "p1"
    summary = evidence_summary or {}
    status_counts = summary.get("by_status", {}) if isinstance(summary.get("by_status"), dict) else {}
    total_events = int(summary.get("total", 0) or 0)
    fail_events = int(status_counts.get("fail", 0) or 0)
    route_ready = bool(route_report and route_report.get("ok") and route_report.get("ready"))
    doctor_clean = bool(doctor_report and str(doctor_report.get("overall", "") or "").lower() == "ok")
    acceptance_ok = bool(acceptance_report and acceptance_report.get("ok"))
    readiness_ok = bool(readiness_report and readiness_report.get("ok"))
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))
    xp_domains = xp_gap_audit.get("rows", []) if isinstance(xp_gap_audit, dict) else []
    blocked_domains = [
        str(row.get("domain", row.get("name", "")) or "")
        for row in xp_domains
        if isinstance(row, dict) and str(row.get("status", "")).lower() in {"blocked", "not_started", "partial"}
    ]

    rows: list[dict[str, str]] = []
    for topic in GUI_KNOWLEDGE_TOPICS:
        source = str(topic["source"])
        source_path = root / source
        doc_status = "pass" if source_path.exists() else "fail"
        status = doc_status
        signal = str(topic["public_signal"])

        key = str(topic["key"])
        if key == "p1_route_decision":
            if route_report is None:
                status = _worst_status(doc_status, "pending")
                signal = f"{signal}; route=not loaded"
            else:
                status = _worst_status(doc_status, "pass" if route_ready else "fail")
                signal = f"{signal}; {route_decision_brief(route_report)}"
        elif key == "field_sop":
            if not evidence_exists or total_events == 0:
                status = _worst_status(doc_status, "pending")
                signal = f"{signal}; evidence=missing"
            elif fail_events:
                status = _worst_status(doc_status, "fail")
                signal = f"{signal}; events={total_events}, fail={fail_events}"
            else:
                status = _worst_status(doc_status, "ready")
                signal = f"{signal}; events={total_events}, fail=0"
        elif key == "hardware_bench":
            if route_report is None and doctor_report is None:
                status = _worst_status(doc_status, "pending")
                signal = f"{signal}; route/doctor pending"
            elif not route_ready or not doctor_clean:
                status = _worst_status(doc_status, "fail")
                signal = f"{signal}; route_ready={route_ready}, doctor_clean={doctor_clean}"
            else:
                status = _worst_status(doc_status, "ready")
                signal = f"{signal}; route_ready=True, doctor_clean=True"
        elif key == "xp_api_helper":
            if not xp_gap_audit:
                status = _worst_status(doc_status, "warn")
                signal = f"{signal}; XP Gap audit not exported in this session"
            elif blocked_domains:
                status = _worst_status(doc_status, "warn")
                signal = f"{signal}; gap_blockers={', '.join(blocked_domains[:3])}"
            else:
                status = _worst_status(doc_status, "ready")
                signal = f"{signal}; gap audit has no blocked/partial domains"
        elif key == "iteration_pitfalls":
            if fail_events:
                status = _worst_status(doc_status, "fail")
                signal = f"{signal}; failed evidence events={fail_events}"
            else:
                status = _worst_status(doc_status, "pass")
        elif key == "claim_boundary":
            if acceptance_ok and readiness_ok and real_ios_verified and fail_events == 0:
                status = doc_status
            elif acceptance_report is None and readiness_report is None:
                status = _worst_status(doc_status, "pending")
            elif acceptance_ok and readiness_ok and not real_ios_verified:
                status = _worst_status(doc_status, "warn")
            else:
                status = _worst_status(doc_status, "fail")
            signal = (
                f"{signal}; stage={normalized_stage.upper()}, acceptance_ok={acceptance_ok}, "
                f"readiness_ok={readiness_ok}, real_ios_verified={real_ios_verified}, fail_events={fail_events}"
            )
        elif key == "xp_public_model":
            if not xp_gap_audit:
                status = _worst_status(doc_status, "warn")
                signal = f"{signal}; public model mapped, current XP parity still needs field audit"
        elif key == "industry_route":
            if normalized_stage in {"p1", "p2", "p3", "p4"} and not route_ready:
                status = _worst_status(doc_status, "warn")
                signal = f"{signal}; route not ready for {normalized_stage.upper()}"

        rows.append({
            "key": key,
            "topic": str(topic["topic"]),
            "status": status,
            "source": source,
            "public_signal": signal,
            "sop_action": str(topic["sop_action"]),
            "gui_action": _knowledge_gui_action(str(topic["method"])),
            "method": str(topic["method"]),
        })
    return rows


def gui_knowledge_center_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts: dict[str, int] = {}
    first_blocker = "none"
    for row in rows:
        status = str(row.get("status", "pending") or "pending")
        counts[status] = counts.get(status, 0) + 1
        if first_blocker == "none" and status in {"fail", "pending"}:
            first_blocker = str(row.get("topic", "") or "unknown")
    return (
        f"GUI knowledge center {stage.upper()}: "
        f"pass={counts.get('pass', 0)}, ready={counts.get('ready', 0)}, "
        f"warn={counts.get('warn', 0)}, fail={counts.get('fail', 0)}, "
        f"pending={counts.get('pending', 0)}; first_blocker={first_blocker}"
    )


def write_gui_knowledge_center_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    stage: str = "p1",
    evidence_path: str | Path = "",
    readiness_report: dict | None = None,
) -> Path:
    out_path = Path(path)
    real_ios_verified = bool(
        (readiness_report or {}).get("claims", {}).get("real_ios_control_verified")
    )
    lines = [
        f"# GUI Knowledge Center {stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        f"- Real iOS control verified: `{real_ios_verified}`",
        "- This knowledge center turns public XP/industry/SOP notes into operator actions. It does not write evidence or prove real iPhone response.",
        "",
        "## Knowledge Rows",
        "",
        "| Topic | Status | Source | Public/industry signal | SOP action | GUI action |",
        "|---|---|---|---|---|---|",
    ]
    for row in rows:
        lines.append(
            f"| {_md_cell(row.get('topic', ''))} | `{_md_cell(row.get('status', ''))}` | "
            f"`{_md_cell(row.get('source', ''))}` | {_md_cell(row.get('public_signal', ''))} | "
            f"{_md_cell(row.get('sop_action', ''))} | {_md_cell(row.get('gui_action', ''))} |"
        )
    if not rows:
        lines.append("| None | `pending` | - | no rows built | Refresh Knowledge | - |")
    lines.extend([
        "",
        "## Claim Boundary",
        "",
        "Use this dashboard to keep research, SOP, and GUI behavior aligned. It is not a substitute for receiver/HID/iPhone field evidence, Acceptance, Readiness, and operator observations.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


def _industry_current_snapshot_gui_action(method: str) -> str:
    return {
        "show_xp_source_refresh_from_gui": "Open Src Refresh",
        "show_mainstream_route_matrix_from_gui": "Open Routes",
        "show_receiver_route_gate_from_gui": "Open Receiver",
        "show_control_response_bench_from_gui": "Open Control Bench",
        "show_ios_field_sop_from_gui": "Open iOS SOP",
        "show_xp_event_error_contract_from_gui": "Open Events",
        "show_scenario_library_from_gui": "Open Library",
        "show_stage_dashboard_from_gui": "Open Dashboard",
        "show_gui_goal_gate_from_gui": "Open Goals",
    }.get(method, method)


def industry_current_snapshot_rows(
    *,
    stage: str = "p1",
    docs_root: str | Path = ".",
    route_report: dict | None = None,
    doctor_report: dict | None = None,
    acceptance_report: dict | None = None,
    readiness_report: dict | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
) -> list[dict[str, str]]:
    """Build a current industry/SOP snapshot without writing field evidence."""
    root = Path(docs_root)
    normalized_stage = stage.lower().strip() or "p1"
    summary = evidence_summary or {}
    status_counts = summary.get("by_status", {}) if isinstance(summary.get("by_status"), dict) else {}
    total_events = int(summary.get("total", 0) or 0)
    fail_events = int(status_counts.get("fail", 0) or 0)
    metric_events = int(summary.get("metrics", {}).get("count", 0) or 0) if isinstance(summary.get("metrics"), dict) else 0
    route_ready = bool(route_report and route_report.get("ok") and route_report.get("ready"))
    route_seen = route_report is not None
    doctor_overall = str((doctor_report or {}).get("overall", "") or "").lower()
    doctor_clean = doctor_overall == "ok"
    doctor_failed = doctor_overall == "fail"
    acceptance_ok = bool(acceptance_report and acceptance_report.get("ok"))
    readiness_ok = bool(readiness_report and readiness_report.get("ok"))
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))
    screenshot_status, screenshot_text = _acceptance_check_line(acceptance_report, "screenshot_quality")
    manual_status, manual_text = _acceptance_check_line(acceptance_report, "manual_observation")

    rows: list[dict[str, str]] = []
    for topic in INDUSTRY_CURRENT_SNAPSHOT_TOPICS:
        key = str(topic["key"])
        source = str(topic["source"])
        doc_status = "pass" if (root / source).exists() else "fail"
        status = "pending"
        current = (
            f"stage={normalized_stage.upper()}; route_ready={route_ready}; doctor={doctor_overall or '-'}; "
            f"events={total_events if evidence_exists else 0}; fail_events={fail_events}; "
            f"screenshot={screenshot_text}; manual={manual_text}; real_ios_verified={real_ios_verified}"
        )

        if key == "public_source_snapshot":
            status = "ready"
            current = f"snapshot_doc={doc_status}; source review is available but not field proof"
        elif key == "mainstream_route_choice":
            if not route_seen:
                status = "pending"
                current = "Route Decision not evaluated; choose receiver/HID before P1."
            elif route_ready:
                status = "ready"
                current = f"route_ready=True; Doctor={doctor_overall or '-'}; still needs receiver/HID evidence"
            else:
                status = "fail"
                current = route_decision_brief(route_report)
        elif key == "receiver_capture_barrier":
            if doctor_failed or screenshot_status == "fail":
                status = "fail"
            elif screenshot_status == "pass" and doctor_clean:
                status = "ready"
            elif route_ready or doctor_clean:
                status = "pending"
            else:
                status = "pending"
            current = f"doctor={doctor_overall or '-'}; screenshot={screenshot_text}; route_ready={route_ready}"
        elif key == "hid_hardware_barrier":
            if doctor_failed or manual_status == "fail":
                status = "fail"
            elif manual_status == "pass" and real_ios_verified:
                status = "ready"
            elif manual_status == "pass":
                status = "warn"
            elif route_ready and doctor_clean:
                status = "pending"
            else:
                status = "pending"
            current = f"manual={manual_text}; real_ios_verified={real_ios_verified}; XP hardware parity=unverified"
        elif key == "ios_settings_gate":
            if route_seen and not route_ready:
                status = "fail"
            elif route_ready:
                status = "ready" if evidence_exists else "pending"
            else:
                status = "pending"
            current = f"route_ready={route_ready}; evidence_exists={evidence_exists}; settings still need operator transcript"
        elif key == "kernel_console_productization":
            status = "ready"
            current = "local API/GUI/event docs are reviewable; hardware-backed events remain field work"
        elif key == "vision_asset_replay":
            if screenshot_status == "fail" or fail_events:
                status = "fail" if screenshot_status == "fail" else "warn"
            elif screenshot_status == "pass" and evidence_exists:
                status = "ready"
            elif evidence_exists:
                status = "warn"
            else:
                status = "pending"
            current = f"screenshot={screenshot_text}; events={total_events}; fail_events={fail_events}"
        elif key == "group_failure_isolation":
            if normalized_stage in {"p3", "p4"}:
                if not evidence_exists or total_events == 0:
                    status = "pending"
                elif fail_events or metric_events == 0:
                    status = "warn"
                elif readiness_ok and real_ios_verified:
                    status = "ready"
                else:
                    status = "warn"
            else:
                status = "pending"
            current = f"stage={normalized_stage.upper()}; events={total_events}; metrics={metric_events}; fail_events={fail_events}"
        elif key == "claim_boundary":
            if acceptance_ok and readiness_ok and real_ios_verified and fail_events == 0:
                status = "pass"
            elif acceptance_report is None and readiness_report is None:
                status = "pending"
            elif acceptance_ok and readiness_ok and not real_ios_verified:
                status = "warn"
            else:
                status = "fail"
            current = (
                f"acceptance_ok={acceptance_ok}; readiness_ok={readiness_ok}; "
                f"real_ios_verified={real_ios_verified}; fail_events={fail_events}"
            )

        rows.append({
            "key": key,
            "area": str(topic["area"]),
            "status": _worst_status(doc_status, status),
            "current": current,
            "current_signal": str(topic["current_signal"]),
            "sop_gate": str(topic["sop_gate"]),
            "main_risk": str(topic["main_risk"]),
            "evidence_required": str(topic["evidence_required"]),
            "stop_rule": str(topic["stop_rule"]),
            "source": source,
            "gui_action": _industry_current_snapshot_gui_action(str(topic["method"])),
            "method": str(topic["method"]),
        })
    return rows


def industry_current_snapshot_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts = _row_status_counts(rows)
    first_focus = _first_attention_value(rows, "area")
    return (
        f"Industry current snapshot {stage.upper()}: "
        f"pass={counts.get('pass', 0)}, ready={counts.get('ready', 0)}, "
        f"warn={counts.get('warn', 0)}, fail={counts.get('fail', 0)}, "
        f"pending={counts.get('pending', 0)}; first_focus={first_focus}"
    )


def write_industry_current_snapshot_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    stage: str = "p1",
    evidence_path: str | Path = "",
    refreshed_at: str = "2026-06-09",
    readiness_report: dict | None = None,
) -> Path:
    out_path = Path(path)
    real_ios_verified = bool(
        (readiness_report or {}).get("claims", {}).get("real_ios_control_verified")
    )
    lines = [
        f"# GUI Industry Current Snapshot {stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        f"- Snapshot refresh: `{refreshed_at}`",
        f"- Real iOS control verified: `{real_ios_verified}`",
        "- This snapshot turns current industry/source/SOP knowledge into GUI actions. It does not write JSONL evidence, does not prove real iPhone response, and does not prove XP parity.",
        "",
        "## Snapshot Rows",
        "",
        "| Area | Status | Current local gate | Current public/source signal | SOP gate | Main risk | Evidence required | Stop rule | Source | GUI action |",
        "|---|---|---|---|---|---|---|---|---|---|",
    ]
    for row in rows:
        lines.append(
            f"| {_md_cell(row.get('area', ''))} | `{_md_cell(row.get('status', ''))}` | "
            f"{_md_cell(row.get('current', ''))} | {_md_cell(row.get('current_signal', ''))} | "
            f"{_md_cell(row.get('sop_gate', ''))} | {_md_cell(row.get('main_risk', ''))} | "
            f"{_md_cell(row.get('evidence_required', ''))} | {_md_cell(row.get('stop_rule', ''))} | "
            f"`{_md_cell(row.get('source', ''))}` | {_md_cell(row.get('gui_action', ''))} |"
        )
    if not rows:
        lines.append("| None | `pending` | no rows built | - | Refresh Snapshot | - | - | Do not promote | - | - |")
    lines.extend([
        "",
        "## Use Rule",
        "",
        "Use Snapshot before Routes, Kit Gate, iOS SOP, Start Pack, and any procurement or demo wording. A snapshot row can identify the next action, but only same-run field evidence, Acceptance, Readiness, logs, and exact device/iOS scope can support a claim.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


