def industry_sop_radar_rows(
    *,
    stage: str = "p1",
    docs_root: str | Path = ".",
    route_report: dict | None = None,
    doctor_report: dict | None = None,
    acceptance_report: dict | None = None,
    readiness_report: dict | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
    xp_gap_audit: dict | None = None,
    route_matrix_rows: list[dict[str, str]] | None = None,
    core_rows: list[dict[str, str]] | None = None,
) -> list[dict[str, str]]:
    """Build an industry/current-state SOP radar without writing field evidence."""
    root = Path(docs_root)
    normalized_stage = stage.lower().strip() or "p1"
    summary = evidence_summary or {}
    status_counts = summary.get("by_status", {}) if isinstance(summary.get("by_status"), dict) else {}
    total_events = int(summary.get("total", 0) or 0)
    fail_events = int(status_counts.get("fail", 0) or 0)
    metric_events = int(summary.get("metrics", {}).get("count", 0) or 0) if isinstance(summary.get("metrics"), dict) else 0
    route_ready = bool(route_report and route_report.get("ok") and route_report.get("ready"))
    doctor_overall = str((doctor_report or {}).get("overall", "") or "").lower()
    doctor_clean = doctor_overall == "ok"
    doctor_failed = doctor_overall == "fail"
    acceptance_ok = bool(acceptance_report and acceptance_report.get("ok"))
    readiness_ok = bool(readiness_report and readiness_report.get("ok"))
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))
    screenshot_status, screenshot_text = _acceptance_check_line(acceptance_report, "screenshot_quality")
    manual_status, manual_text = _acceptance_check_line(acceptance_report, "manual_observation")
    component_status, component_text = _acceptance_check_line(acceptance_report, "component_traceability")
    metrics_status, metrics_text = _acceptance_check_line(acceptance_report, "metrics")
    route_matrix_status = _rows_worst_status(route_matrix_rows or [])
    core_status = _rows_worst_status(core_rows or [])
    xp_domains = xp_gap_audit.get("rows", []) if isinstance(xp_gap_audit, dict) else []
    xp_gap_by_domain = {
        str(row.get("domain", row.get("name", "")) or "").lower(): str(row.get("status", "") or "").lower()
        for row in xp_domains
        if isinstance(row, dict)
    }

    def gap_status(*fragments: str) -> str:
        matches = [
            status
            for domain, status in xp_gap_by_domain.items()
            if any(fragment.lower() in domain for fragment in fragments)
        ]
        if not matches:
            return "pending"
        return _worst_status(*(
            "pass" if item == "pass" else "warn" if item == "partial" else "pending" if item == "not_started" else "fail"
            for item in matches
        ))

    rows: list[dict[str, str]] = []
    for topic in INDUSTRY_SOP_RADAR_TOPICS:
        key = str(topic["key"])
        source = str(topic["source"])
        doc_status = "pass" if (root / source).exists() else "fail"
        status = doc_status
        current = (
            f"stage={normalized_stage.upper()}; route_ready={route_ready}; doctor={doctor_overall or '-'}; "
            f"events={total_events}, fail={fail_events}; real_ios_verified={real_ios_verified}"
        )

        if key == "mainstream_route_boundary":
            if route_matrix_rows:
                status = _worst_status(doc_status, route_matrix_status)
                if status == "pass":
                    status = "ready"
                current = f"routes={route_matrix_status}; route_ready={route_ready}; selected route must still be proven by field evidence"
            elif route_ready:
                status = _worst_status(doc_status, "ready")
                current = "Route Decision is ready but route matrix has not been exported"
            else:
                status = _worst_status(doc_status, "pending" if route_report is None else "fail")
                current = "Route Decision and route matrix are not ready"
        elif key == "xp_product_boundary":
            if core_rows:
                status = _worst_status(doc_status, "warn" if core_status in {"pass", "ready"} else core_status)
                current = f"core={core_status}; XP hardware/wired/hard-decode parity remains separate from local API readiness"
            elif xp_gap_audit:
                status = _worst_status(doc_status, gap_status("receiver", "usb", "hid", "kernel", "api"))
                current = "XP Gap audit exists; side-by-side XP hardware and Windows/wired receiver proof still required"
            else:
                status = _worst_status(doc_status, "pending")
                current = "XP Gap/Core not exported for this run"
        elif key == "iphone_field_settings":
            if component_status == "pass" and manual_status == "pass" and real_ios_verified:
                status = _worst_status(doc_status, "pass")
            elif component_status == "pass" and manual_status == "pass":
                status = _worst_status(doc_status, "warn")
            elif doctor_failed or manual_status == "fail":
                status = _worst_status(doc_status, "fail")
            elif route_ready:
                status = _worst_status(doc_status, "pending")
            else:
                status = _worst_status(doc_status, "pending")
            current = f"component={component_text}; manual={manual_text}; real_ios_verified={real_ios_verified}"
        elif key == "receiver_capture_lane":
            if doctor_failed or screenshot_status == "fail":
                status = _worst_status(doc_status, "fail")
            elif screenshot_status == "pass" and doctor_clean:
                status = _worst_status(doc_status, "ready")
            elif route_ready and doctor_clean:
                status = _worst_status(doc_status, "pending")
            else:
                status = _worst_status(doc_status, "fail" if route_report or doctor_report else "pending")
            current = f"doctor={doctor_overall or '-'}; screenshot={screenshot_text}; route_ready={route_ready}"
        elif key == "hid_hardware_lane":
            if doctor_failed or manual_status == "fail":
                status = _worst_status(doc_status, "fail")
            elif manual_status == "pass" and real_ios_verified:
                status = _worst_status(doc_status, "ready")
            elif manual_status == "pass":
                status = _worst_status(doc_status, "warn")
            elif route_ready and doctor_clean:
                status = _worst_status(doc_status, "pending")
            else:
                status = _worst_status(doc_status, "fail" if route_report or doctor_report else "pending")
            current = (
                f"manual={manual_text}; doctor={doctor_overall or '-'}; "
                f"real_ios_verified={real_ios_verified}; XP hardware parity=unverified"
            )
        elif key == "api_sdk_lane":
            api_status = gap_status("kernel", "api", "python sdk")
            if api_status == "pass":
                status = _worst_status(doc_status, "ready")
            elif api_status in {"fail", "warn"}:
                status = _worst_status(doc_status, api_status)
            else:
                status = _worst_status(doc_status, "pending")
            current = f"xp_gap_api={api_status}; protocol compatibility does not prove real iPhone response"
        elif key == "vision_ocr_lane":
            if screenshot_status == "fail":
                status = _worst_status(doc_status, "fail")
            elif not evidence_exists or total_events == 0:
                status = _worst_status(doc_status, "pending")
            elif fail_events:
                status = _worst_status(doc_status, "warn")
            elif screenshot_status == "pass":
                status = _worst_status(doc_status, "ready")
            else:
                status = _worst_status(doc_status, "pending")
            current = f"screenshot={screenshot_text}; events={total_events}, fail={fail_events}"
        elif key == "observability_recovery":
            if fail_events:
                status = _worst_status(doc_status, "warn")
                current = f"failed events={fail_events}; attach logs and classify before rerun"
            elif evidence_exists and total_events:
                status = _worst_status(doc_status, "ready")
                current = f"events={total_events}, metrics={metric_events}; {metrics_text}"
            else:
                status = _worst_status(doc_status, "pending")
                current = "no field evidence ledger yet"
        elif key == "scale_ops_lane":
            if normalized_stage in {"p3", "p4"}:
                if real_ios_verified and evidence_exists and fail_events == 0 and (metric_events or metrics_status == "pass"):
                    status = _worst_status(doc_status, "ready")
                elif evidence_exists:
                    status = _worst_status(doc_status, "warn" if metric_events else "fail")
                else:
                    status = _worst_status(doc_status, "pending")
                current = f"stage={normalized_stage.upper()}; metrics={metric_events}; {metrics_text}; fail={fail_events}"
            else:
                status = _worst_status(doc_status, "pending")
                current = f"{normalized_stage.upper()} is not a scale gate; finish P1/P2 before group expansion"
        elif key == "claim_boundary":
            if acceptance_ok and readiness_ok and real_ios_verified and fail_events == 0:
                status = _worst_status(doc_status, "pass")
            elif acceptance_report is None and readiness_report is None:
                status = _worst_status(doc_status, "pending")
            elif acceptance_ok and readiness_ok and not real_ios_verified:
                status = _worst_status(doc_status, "warn")
            else:
                status = _worst_status(doc_status, "fail")
            current = (
                f"acceptance_ok={acceptance_ok}; readiness_ok={readiness_ok}; "
                f"real_ios_verified={real_ios_verified}; fail_events={fail_events}"
            )

        rows.append({
            "key": key,
            "topic": str(topic["topic"]),
            "layer": str(topic["layer"]),
            "status": status,
            "current": current,
            "public_signal": str(topic["public_signal"]),
            "sop_decision": str(topic["sop_decision"]),
            "evidence_gate": str(topic["evidence_gate"]),
            "stop_rule": str(topic["stop_rule"]),
            "source": source,
            "gui_action": _industry_sop_radar_gui_action(str(topic["method"])),
            "method": str(topic["method"]),
        })
    return rows


def industry_sop_radar_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts = _row_status_counts(rows)
    first_focus = _first_attention_value(rows, "topic")
    return (
        f"Industry SOP radar {stage.upper()}: "
        f"pass={counts.get('pass', 0)}, ready={counts.get('ready', 0)}, "
        f"warn={counts.get('warn', 0)}, fail={counts.get('fail', 0)}, "
        f"pending={counts.get('pending', 0)}; first_focus={first_focus}"
    )


