def industry_route_procurement_rows(
    *,
    stage: str = "p1",
    docs_root: str | Path = ".",
    device_ids: list[str] | None = None,
    route_decision: dict | None = None,
    route_report: dict | None = None,
    doctor_report: dict | None = None,
    acceptance_report: dict | None = None,
    readiness_report: dict | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
    route_matrix_rows: list[dict[str, str]] | None = None,
    xp_lab_rows: list[dict[str, str]] | None = None,
) -> list[dict[str, str]]:
    """Build the procurement-focused industry route SOP without writing evidence."""
    root = Path(docs_root)
    normalized_stage = stage.lower().strip() or "p1"
    selected_devices = [str(item).strip() for item in (device_ids or []) if str(item).strip()]
    required_devices = STAGE_DEVICE_REQUIREMENTS.get(normalized_stage, 1)
    route_values = route_decision_form_values(route_decision or {}) if route_decision else {}
    receiver_route = str(route_values.get("receiver.route", nested_get(route_decision or {}, "receiver.route", "")) or "").strip()
    receiver_name = str(route_values.get("receiver.name", nested_get(route_decision or {}, "receiver.name", "")) or "").strip()
    receiver_version = str(route_values.get("receiver.version", nested_get(route_decision or {}, "receiver.version", "")) or "").strip()
    capture_method = str(route_values.get("receiver.capture_method", nested_get(route_decision or {}, "receiver.capture_method", "")) or "").strip()
    hid_route = str(route_values.get("hid.route", nested_get(route_decision or {}, "hid.route", "")) or "").strip()
    hid_provider = str(route_values.get("hid.provider", nested_get(route_decision or {}, "hid.provider", "")) or "").strip()
    hid_firmware = str(route_values.get("hid.firmware", nested_get(route_decision or {}, "hid.firmware", "")) or "").strip()
    iphone_model = str(route_values.get("iphone.model", nested_get(route_decision or {}, "iphone.model", "")) or "").strip()
    ios_version = str(route_values.get("iphone.ios_version", nested_get(route_decision or {}, "iphone.ios_version", "")) or "").strip()
    route_ready = bool(route_report and route_report.get("ok") and route_report.get("ready"))
    route_seen = route_report is not None
    doctor_overall = str((doctor_report or {}).get("overall", "") or "").lower()
    doctor_clean = doctor_overall == "ok"
    doctor_failed = doctor_overall == "fail"
    readiness_ok = bool(readiness_report and readiness_report.get("ok"))
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))
    acceptance_ok = bool(acceptance_report and acceptance_report.get("ok"))
    screenshot_status, screenshot_text = _acceptance_check_line(acceptance_report, "screenshot_quality")
    manual_status, manual_text = _acceptance_check_line(acceptance_report, "manual_observation")
    component_status, component_text = _acceptance_check_line(acceptance_report, "component_traceability")
    metrics_status, metrics_text = _acceptance_check_line(acceptance_report, "metrics")
    summary = evidence_summary or {}
    status_counts = summary.get("by_status", {}) if isinstance(summary.get("by_status"), dict) else {}
    total_events = int(summary.get("total", 0) or 0)
    fail_events = int(status_counts.get("fail", 0) or 0)
    metric_events = int(summary.get("metrics", {}).get("count", 0) or 0) if isinstance(summary.get("metrics"), dict) else 0
    route_matrix_status = _rows_worst_status(route_matrix_rows or [])
    xp_lab_status = _rows_worst_status(xp_lab_rows or [])

    receiver_fields = (
        "receiver.route",
        "receiver.name",
        "receiver.version",
        "receiver.path",
        "receiver.start_command",
        "receiver.airplay_name",
        "receiver.capture_method",
    )
    hid_fields = ("hid.route", "hid.provider", "hid.id", "hid.firmware", "hid.serial_port", "hid.baudrate")
    iphone_fields = ("iphone.id", "iphone.model", "iphone.ios_version", "iphone.orientation", "iphone.assistive_touch", "iphone.pointer_speed")
    bench_fields = ("bench.device_id", "bench.hub_id", "bench.hub_port", "bench.cable_id", "bench.network", "bench.operator")
    receiver_gate = _route_nested_fields_gate(route_decision, receiver_fields)
    hid_gate = _route_nested_fields_gate(route_decision, hid_fields)
    iphone_gate = _route_nested_fields_gate(route_decision, iphone_fields)
    bench_gate = _route_nested_fields_gate(route_decision, bench_fields)

    rows: list[dict[str, str]] = []
    for topic in INDUSTRY_ROUTE_PROCUREMENT_TOPICS:
        key = str(topic["key"])
        source_doc = str(topic["source_doc"])
        doc_status = "pass" if (root / source_doc).exists() else "fail"
        status = "pending"
        current = (
            f"stage={normalized_stage.upper()}; devices={len(selected_devices)}/{required_devices}; "
            f"route={receiver_route or '-'}:{receiver_name or '-'}:{receiver_version or '-'}; "
            f"capture={capture_method or '-'}; hid={hid_route or '-'}:{hid_provider or '-'}:{hid_firmware or '-'}; "
            f"iphone={iphone_model or '-'}:{ios_version or '-'}; doctor={doctor_overall or '-'}; "
            f"events={total_events if evidence_exists else 0}; fail_events={fail_events}; real_ios_verified={real_ios_verified}"
        )

        if key == "route_lock":
            if not route_seen and not route_decision:
                status = "pending"
                current = "Route Decision not loaded; route matrix and physical bench lane must be chosen before buying."
            elif route_seen and not route_ready:
                status = "fail"
                current = route_decision_brief(route_report)
            elif route_ready and route_matrix_rows:
                status = "ready" if route_matrix_status in {"ready", "pass", "warn"} else route_matrix_status
                current = f"route_ready=True; routes={route_matrix_status}; receiver={receiver_route or '-'}; hid={hid_route or '-'}"
            elif route_ready:
                status = "warn"
                current = "Route Decision is ready but Route Matrix export has not been reviewed."
            else:
                status = "pending"
                current = f"receiver={receiver_route or '-'}; hid={hid_route or '-'}; route_ready={route_ready}"
        elif key == "receiver_procurement":
            status = receiver_gate[0]
            current = f"{current}; {receiver_gate[1]}; screenshot={screenshot_text}"
            if doctor_failed or screenshot_status == "fail":
                status = _worst_status(status, "fail")
            elif receiver_gate[0] == "pass" and doctor_clean and screenshot_status == "pass":
                status = "ready"
            elif receiver_gate[0] == "pass":
                status = "warn"
        elif key == "hid_procurement":
            status = hid_gate[0]
            current = f"{current}; {hid_gate[1]}; manual={manual_text}"
            if doctor_failed or manual_status == "fail":
                status = _worst_status(status, "fail")
            elif hid_gate[0] == "pass" and manual_status == "pass" and real_ios_verified:
                status = "ready"
            elif hid_gate[0] == "pass":
                status = "warn"
        elif key == "xp_parity_purchase":
            if hid_route == "xp_hardware":
                if xp_lab_rows and xp_lab_status in {"ready", "pass", "warn"}:
                    status = "warn"
                    current = f"{current}; xp_lab={xp_lab_status}; side-by-side legal XP parity evidence still required"
                elif hid_gate[0] == "pass":
                    status = "warn"
                    current = f"{current}; XP hardware route selected but XP Lab side-by-side rows are missing"
                else:
                    status = hid_gate[0]
                    current = f"{current}; XP hardware route selected but procurement fields are incomplete"
            elif hid_route:
                status = "warn"
                current = f"{current}; generic HID route can support generic P1, but XP hardware parity purchase remains separate"
            else:
                status = "pending"
                current = f"{current}; HID route not selected, so XP parity purchase is premature"
        elif key == "iphone_fixture_matrix":
            status = iphone_gate[0]
            current = f"{current}; {iphone_gate[1]}; component={component_text}"
            if len(selected_devices) < required_devices:
                status = _worst_status(status, "fail")
                current = f"{current}; selected device scope is short"
            elif component_status == "pass" and iphone_gate[0] == "pass":
                status = "ready"
            elif iphone_gate[0] == "pass":
                status = "warn"
        elif key == "bench_materials":
            status = bench_gate[0]
            current = f"{current}; {bench_gate[1]}; component={component_text}"
            if component_status == "fail":
                status = _worst_status(status, "fail")
            elif bench_gate[0] == "pass" and component_status == "pass":
                status = "ready"
            elif bench_gate[0] == "pass":
                status = "warn"
        elif key == "source_refresh_contract":
            status = "ready" if doc_status == "pass" else "fail"
            current = f"source_doc={doc_status}; refresh before package install, receiver purchase, route switch, or demo wording"
        elif key == "claim_and_scale_stop":
            if normalized_stage in {"p3", "p4"}:
                if (
                    len(selected_devices) >= required_devices
                    and readiness_ok
                    and real_ios_verified
                    and fail_events == 0
                    and (metric_events or metrics_status == "pass")
                ):
                    status = "ready"
                elif evidence_exists:
                    status = "warn"
                else:
                    status = "pending"
                current = f"{current}; metrics={metric_events}; {metrics_text}; readiness_ok={readiness_ok}"
            elif acceptance_ok and readiness_ok and real_ios_verified and fail_events == 0:
                status = "pass"
                current = f"{current}; P1/P2 claim gate is evidence-backed for exact scope only"
            elif acceptance_ok and readiness_ok and not real_ios_verified:
                status = "warn"
                current = f"{current}; gates look clean but real_ios_verified=False"
            elif acceptance_report is not None or readiness_report is not None:
                status = "fail"
                current = f"{current}; acceptance_ok={acceptance_ok}; readiness_ok={readiness_ok}"
            else:
                status = "pending"
                current = f"{current}; Acceptance and Readiness not evaluated"

        method = str(topic["method"])
        rows.append({
            "key": key,
            "lane": str(topic["lane"]),
            "layer": str(topic["layer"]),
            "status": _worst_status(doc_status, status),
            "current": current,
            "industry_signal": str(topic["industry_signal"]),
            "vendor_questions": str(topic["vendor_questions"]),
            "local_sop": str(topic["local_sop"]),
            "evidence_required": str(topic["evidence_required"]),
            "stop_rule": str(topic["stop_rule"]),
            "source": str(topic["source"]),
            "source_doc": source_doc,
            "gui_action": _industry_route_procurement_gui_action(method),
            "method": method,
        })
    return rows


def industry_route_procurement_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts = _row_status_counts(rows)
    first_focus = _first_attention_value(rows, "lane", statuses={"fail", "pending", "warn"})
    return (
        f"Route procurement SOP {stage.upper()}: "
        f"pass={counts.get('pass', 0)}, ready={counts.get('ready', 0)}, "
        f"warn={counts.get('warn', 0)}, fail={counts.get('fail', 0)}, "
        f"pending={counts.get('pending', 0)}; first_focus={first_focus}"
    )


def write_industry_route_procurement_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    stage: str = "p1",
    evidence_path: str | Path = "",
    refreshed_at: str = "2026-06-09",
    readiness_report: dict | None = None,
) -> Path:
    out_path = Path(path)
    real_ios_verified = bool(
        (readiness_report or {}).get("claims", {}).get("real_ios_control_verified")
    )
    lines = [
        f"# GUI Route Procurement SOP {stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        f"- Public-source refresh: `{refreshed_at}`",
        f"- Real iOS control verified: `{real_ios_verified}`",
        "- This board turns industry route knowledge into procurement questions, lab SOP, and stop lines. It does not write JSONL evidence, does not prove real iPhone response, and does not prove XP parity.",
        "",
        "## Procurement Rows",
        "",
        "| Lane | Layer | Status | Current local gate | Industry signal | Vendor questions | Local SOP | Evidence required | Stop rule | Source | GUI action |",
        "|---|---|---|---|---|---|---|---|---|---|---|",
    ]
    for row in rows:
        lines.append(
            f"| {_md_cell(row.get('lane', ''))} | {_md_cell(row.get('layer', ''))} | "
            f"`{_md_cell(row.get('status', ''))}` | {_md_cell(row.get('current', ''))} | "
            f"{_md_cell(row.get('industry_signal', ''))} | {_md_cell(row.get('vendor_questions', ''))} | "
            f"{_md_cell(row.get('local_sop', ''))} | {_md_cell(row.get('evidence_required', ''))} | "
            f"{_md_cell(row.get('stop_rule', ''))} | `{_md_cell(row.get('source', ''))}` | "
            f"{_md_cell(row.get('gui_action', ''))} |"
        )
    if not rows:
        lines.append("| None | - | `pending` | no rows built | - | Refresh Procure | - | - | Do not buy or claim | - | - |")
    lines.extend([
        "",
        "## Spend Rule",
        "",
        "Use Route Procurement SOP before receiver/HID/iPhone/Hub/cable buying, vendor calls, route switching, or demo wording. A ready procurement row means the lane is reviewable; only same-run field evidence, Acceptance, Readiness, logs, and exact device/iOS scope can close control or parity claims.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


def _mainstream_route_gui_action(method: str) -> str:
    return {
        "show_field_evidence_wizard_from_gui": "Open Wizard",
        "run_preflight_doctor": "Run Doctor",
        "edit_route_decision_from_gui": "Edit Route",
        "show_hardware_bench_from_gui": "Open Bench",
        "run_capture_quality_bench_from_gui": "Run Shot Bench",
        "show_control_response_bench_from_gui": "Open Control Bench",
        "show_gui_knowledge_center_from_gui": "Open Knowledge",
        "show_field_kit_gate_from_gui": "Open Kit Gate",
    }.get(method, method)


def mainstream_route_matrix_rows(
    *,
    stage: str = "p1",
    docs_root: str | Path = ".",
    route_decision: dict | None = None,
    route_report: dict | None = None,
    doctor_report: dict | None = None,
    acceptance_report: dict | None = None,
    readiness_report: dict | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
) -> list[dict[str, str]]:
    """Build the industry route matrix for receiver/HID/product route selection."""
    root = Path(docs_root)
    normalized_stage = stage.lower().strip() or "p1"
    route_values = route_decision_form_values(route_decision or {}) if route_decision else {}
    receiver_route = str(route_values.get("receiver.route", nested_get(route_decision or {}, "receiver.route", "")) or "").strip()
    hid_route = str(route_values.get("hid.route", nested_get(route_decision or {}, "hid.route", "")) or "").strip()
    receiver_name = str(route_values.get("receiver.name", "") or "").strip()
    capture_method = str(route_values.get("receiver.capture_method", "") or "").strip()
    hid_serial = str(route_values.get("hid.serial_or_device", "") or "").strip()
    route_ready = bool(route_report and route_report.get("ok") and route_report.get("ready"))
    doctor_overall = str((doctor_report or {}).get("overall", "") or "").lower()
    doctor_clean = doctor_overall == "ok"
    doctor_failed = doctor_overall == "fail"
    acceptance_ok = bool(acceptance_report and acceptance_report.get("ok"))
    readiness_ok = bool(readiness_report and readiness_report.get("ok"))
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))
    screenshot_status, screenshot_text = _acceptance_check_line(acceptance_report, "screenshot_quality")
    manual_status, manual_text = _acceptance_check_line(acceptance_report, "manual_observation")
    summary = evidence_summary or {}
    status_counts = summary.get("by_status", {}) if isinstance(summary.get("by_status"), dict) else {}
    total_events = int(summary.get("total", 0) or 0)
    fail_events = int(status_counts.get("fail", 0) or 0)

    def receiver_current(name: str) -> str:
        selected = receiver_route == name
        return (
            f"selected={selected}; receiver.route={receiver_route or '-'}; "
            f"name={receiver_name or '-'}; capture={capture_method or '-'}; "
            f"route_ready={route_ready}; doctor={doctor_overall or '-'}; screenshot={screenshot_text}"
        )

    def hid_current(name: str) -> str:
        selected = hid_route == name
        return (
            f"selected={selected}; hid.route={hid_route or '-'}; "
            f"serial={hid_serial or '-'}; route_ready={route_ready}; manual={manual_text}"
        )

    rows: list[dict[str, str]] = []
    for topic in MAINSTREAM_ROUTE_TOPICS:
        key = str(topic["key"])
        source = str(topic["source"])
        doc_status = "pass" if (root / source).exists() else "fail"
        status = doc_status
        selected = "no"
        current = f"stage={normalized_stage.upper()}; route_ready={route_ready}; events={total_events}, fail={fail_events}"

        if key == "mainline_decision":
            selected = "yes" if receiver_route and hid_route else "no"
            if not route_report:
                status = _worst_status(doc_status, "pending")
                current = "Route Decision not loaded; choose receiver and HID before P1."
            elif not route_ready or doctor_failed:
                status = _worst_status(doc_status, "fail")
                current = f"route_ready={route_ready}; doctor={doctor_overall or '-'}; receiver={receiver_route or '-'}; hid={hid_route or '-'}"
            elif screenshot_status == "fail" or manual_status == "fail" or fail_events:
                status = _worst_status(doc_status, "fail")
                current = f"screenshot={screenshot_text}; manual={manual_text}; fail_events={fail_events}"
            elif acceptance_ok and readiness_ok and real_ios_verified and screenshot_status == "pass" and manual_status == "pass":
                status = _worst_status(doc_status, "pass")
                current = "receiver/HID/screenshot/manual/acceptance/readiness all support current selected device."
            elif screenshot_status == "pass" and manual_status == "pass":
                status = _worst_status(doc_status, "ready")
                current = f"field proof ready, but real_ios_verified={real_ios_verified}; run Readiness/claim gate."
            else:
                status = _worst_status(doc_status, "pending")
                current = f"receiver={receiver_route or '-'}; hid={hid_route or '-'}; screenshot={screenshot_text}; manual={manual_text}"
        elif key == "uxplay_receiver":
            selected = "yes" if receiver_route == "uxplay" else "no"
            current = receiver_current("uxplay")
            if not receiver_route:
                status = _worst_status(doc_status, "pending")
            elif receiver_route != "uxplay":
                status = _worst_status(doc_status, "warn")
            elif not route_ready or doctor_failed:
                status = _worst_status(doc_status, "fail")
            elif screenshot_status == "pass":
                status = _worst_status(doc_status, "pass")
            else:
                status = _worst_status(doc_status, "ready" if doctor_clean else "warn")
        elif key == "windows_receiver":
            selected = "yes" if receiver_route == "windows_receiver" else "no"
            current = receiver_current("windows_receiver")
            if receiver_route == "windows_receiver":
                if not route_ready:
                    status = _worst_status(doc_status, "fail")
                elif screenshot_status == "pass":
                    status = _worst_status(doc_status, "pass")
                else:
                    status = _worst_status(doc_status, "ready")
            else:
                status = _worst_status(doc_status, "warn" if receiver_route else "pending")
        elif key == "wired_projection":
            selected = "yes" if receiver_route == "wired" else "no"
            current = receiver_current("wired")
            if receiver_route == "wired":
                if not route_ready:
                    status = _worst_status(doc_status, "fail")
                elif screenshot_status == "pass":
                    status = _worst_status(doc_status, "pass")
                else:
                    status = _worst_status(doc_status, "ready")
            else:
                status = _worst_status(doc_status, "warn" if receiver_route else "pending")
        elif key == "capture_card":
            selected = "yes" if receiver_route == "capture_card" else "no"
            current = receiver_current("capture_card")
            if receiver_route == "capture_card":
                if not route_ready:
                    status = _worst_status(doc_status, "fail")
                elif screenshot_status == "pass":
                    status = _worst_status(doc_status, "ready")
                else:
                    status = _worst_status(doc_status, "pending")
            else:
                status = _worst_status(doc_status, "warn" if receiver_route else "pending")
        elif key == "ch9329_hid":
            selected = "yes" if hid_route == "ch9329" else "no"
            current = hid_current("ch9329")
            if not hid_route:
                status = _worst_status(doc_status, "pending")
            elif hid_route != "ch9329":
                status = _worst_status(doc_status, "warn")
            elif not route_ready:
                status = _worst_status(doc_status, "fail")
            elif manual_status == "pass":
                status = _worst_status(doc_status, "pass")
            elif manual_status == "fail":
                status = _worst_status(doc_status, "fail")
            else:
                status = _worst_status(doc_status, "ready")
        elif key == "xp_hardware":
            selected = "yes" if hid_route == "xp_hardware" else "no"
            current = hid_current("xp_hardware")
            if hid_route == "xp_hardware":
                if not route_ready:
                    status = _worst_status(doc_status, "fail")
                else:
                    status = _worst_status(doc_status, "ready")
                    current = f"{current}; side_by_side_xp_parity_evidence=missing"
            else:
                status = _worst_status(doc_status, "warn" if hid_route else "pending")
                current = f"{current}; XP dedicated hardware/4.4/auto-binding claims remain blocked"
        elif key == "wda_appium":
            selected = "no"
            status = _worst_status(doc_status, "warn")
            current = "non-mainline for XP-style cross-app black-box control; keep only as own-app QA reference"
        elif key == "mdm_shortcuts":
            selected = "no"
            status = _worst_status(doc_status, "warn")
            current = "auxiliary setup lane; useful for device prep, not click/swipe/type proof"

        rows.append({
            "key": key,
            "lane": str(topic["lane"]),
            "role": str(topic["role"]),
            "status": status,
            "selected": selected,
            "route_type": str(topic["route_type"]),
            "current": current,
            "fit": str(topic["fit"]),
            "p1_gate": str(topic["p1_gate"]),
            "evidence": str(topic["evidence"]),
            "stop_rule": str(topic["stop_rule"]),
            "source": source,
            "gui_action": _mainstream_route_gui_action(str(topic["method"])),
            "method": str(topic["method"]),
        })
    return rows


def mainstream_route_matrix_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts: dict[str, int] = {}
    selected = []
    first_focus = "none"
    for row in rows:
        status = str(row.get("status", "pending") or "pending")
        counts[status] = counts.get(status, 0) + 1
        if row.get("selected") == "yes":
            selected.append(str(row.get("lane", "") or "unknown"))
        if first_focus == "none" and status in {"fail", "pending"}:
            first_focus = str(row.get("lane", "") or "unknown")
    selected_text = ", ".join(selected[:3]) or "none"
    return (
        f"Mainstream routes {stage.upper()}: "
        f"pass={counts.get('pass', 0)}, ready={counts.get('ready', 0)}, "
        f"warn={counts.get('warn', 0)}, fail={counts.get('fail', 0)}, "
        f"pending={counts.get('pending', 0)}; selected={selected_text}; first_focus={first_focus}"
    )


def write_mainstream_route_matrix_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    stage: str = "p1",
    evidence_path: str | Path = "",
    readiness_report: dict | None = None,
) -> Path:
    out_path = Path(path)
    real_ios_verified = bool(
        (readiness_report or {}).get("claims", {}).get("real_ios_control_verified")
    )
    lines = [
        f"# GUI Mainstream Route Matrix {stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        f"- Real iOS control verified: `{real_ios_verified}`",
        "- This matrix turns industry route choices into SOP gates. It does not write evidence or prove real iPhone response.",
        "",
        "## Route Rows",
        "",
        "| Lane | Role | Status | Selected | Route type | Current signal | Fit | P1 gate | Evidence | Stop rule | Source | GUI action |",
        "|---|---|---|---|---|---|---|---|---|---|---|---|",
    ]
    for row in rows:
        lines.append(
            f"| {_md_cell(row.get('lane', ''))} | {_md_cell(row.get('role', ''))} | "
            f"`{_md_cell(row.get('status', ''))}` | {_md_cell(row.get('selected', ''))} | "
            f"{_md_cell(row.get('route_type', ''))} | {_md_cell(row.get('current', ''))} | "
            f"{_md_cell(row.get('fit', ''))} | {_md_cell(row.get('p1_gate', ''))} | "
            f"{_md_cell(row.get('evidence', ''))} | {_md_cell(row.get('stop_rule', ''))} | "
            f"`{_md_cell(row.get('source', ''))}` | {_md_cell(row.get('gui_action', ''))} |"
        )
    if not rows:
        lines.append("| none | - | `pending` | no | - | no rows built | Refresh Routes | - | - | Do not promote | - | - |")
    lines.extend([
        "",
        "## Decision Rule",
        "",
        "Use Routes before editing Route Decision and before any real run. Pick one receiver lane and one HID lane for the current run_id, keep WDA/Appium and MDM/Shortcuts out of the XP-style control claim, then prove the chosen path with artifacts, manual observation, Acceptance, and Readiness.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


