def xp_architecture_map_rows(
    *,
    stage: str = "p1",
    docs_root: str | Path = ".",
    route_report: dict | None = None,
    doctor_report: dict | None = None,
    acceptance_report: dict | None = None,
    readiness_report: dict | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
    xp_gap_audit: dict | None = None,
) -> list[dict[str, str]]:
    """Build an XP architecture map from public signals to local proof gates."""
    root = Path(docs_root)
    normalized_stage = stage.lower().strip() or "p1"
    summary = evidence_summary or {}
    status_counts = summary.get("by_status", {}) if isinstance(summary.get("by_status"), dict) else {}
    total_events = int(summary.get("total", 0) or 0)
    fail_events = int(status_counts.get("fail", 0) or 0)
    metric_events = int(summary.get("metrics", {}).get("count", 0) or 0) if isinstance(summary.get("metrics"), dict) else 0
    route_ready = bool(route_report and route_report.get("ok") and route_report.get("ready"))
    doctor_overall = str((doctor_report or {}).get("overall", "") or "").lower()
    doctor_clean = doctor_overall == "ok"
    doctor_failed = doctor_overall == "fail"
    acceptance_ok = bool(acceptance_report and acceptance_report.get("ok"))
    readiness_ok = bool(readiness_report and readiness_report.get("ok"))
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))
    screenshot_status, screenshot_text = _acceptance_check_line(acceptance_report, "screenshot_quality")
    manual_status, manual_text = _acceptance_check_line(acceptance_report, "manual_observation")
    component_status, component_text = _acceptance_check_line(acceptance_report, "component_traceability")

    rows: list[dict[str, str]] = []
    for topic in XP_ARCHITECTURE_LAYERS:
        key = str(topic["key"])
        source_doc = str(topic["source_doc"])
        doc_status = "pass" if (root / source_doc).exists() else "fail"
        gap_status = _xp_gap_status_for_domains(
            xp_gap_audit,
            tuple(str(fragment) for fragment in topic.get("gap_fragments", ())),
        )
        status = doc_status
        current = (
            f"stage={normalized_stage.upper()}; route_ready={route_ready}; doctor={doctor_overall or '-'}; "
            f"events={total_events if evidence_exists else 0}; fail_events={fail_events}; "
            f"screenshot={screenshot_text}; manual={manual_text}; real_ios_verified={real_ios_verified}"
        )

        if key == "product_boundary":
            if not evidence_exists:
                status = _worst_status(doc_status, "pending")
                current = f"{current}; product route is architecture only until field evidence exists"
            elif acceptance_ok and readiness_ok and real_ios_verified and fail_events == 0:
                status = _worst_status(doc_status, "ready")
                current = f"{current}; current stage can be described narrowly, not as broad XP parity"
            else:
                status = _worst_status(doc_status, "warn" if total_events else "pending")
                current = f"{current}; source/model claims remain outside local proof"
        elif key == "hardware_usb_hid":
            if not real_ios_verified:
                status = _worst_status(doc_status, "fail")
                current = f"{current}; HID/iPhone response not proven; XP hardware/4.4/auto-binding unverified"
            elif gap_status == "pass":
                status = _worst_status(doc_status, "warn")
                current = f"{current}; generic HID can be current-stage ready, XP hardware parity still needs side-by-side evidence"
            else:
                status = _worst_status(doc_status, "warn")
                current = f"{current}; real response exists but XP Gap HID={gap_status or 'unknown'}"
        elif key == "projection_receiver":
            if doctor_failed or (route_report is not None and not route_ready):
                status = _worst_status(doc_status, "fail")
                current = f"{current}; receiver route or Doctor blocks projection"
            elif route_ready and doctor_clean and screenshot_status == "pass" and not fail_events:
                status = _worst_status(doc_status, "ready")
                current = f"{current}; receiver/capture usable for current run, but Windows/wired/hard-decode parity separate"
            elif route_ready or doctor_clean:
                status = _worst_status(doc_status, "warn")
                current = f"{current}; receiver path partially ready but screenshot proof is incomplete"
            else:
                status = _worst_status(doc_status, "pending")
                current = f"{current}; receiver route not locked"
        elif key == "capture_vision":
            if not evidence_exists or total_events == 0:
                status = _worst_status(doc_status, "pending")
                current = f"{current}; no real screenshot/vision artifacts"
            elif screenshot_status == "fail" or fail_events:
                status = _worst_status(doc_status, "fail")
                current = f"{current}; visual lane has failed evidence that must be replayed"
            elif screenshot_status == "pass":
                status = _worst_status(doc_status, "ready" if gap_status != "fail" else "warn")
                current = f"{current}; screenshot proof exists, vision/OCR assets still need replay discipline"
            else:
                status = _worst_status(doc_status, "warn")
                current = f"{current}; evidence exists but screenshot_quality is not pass"
        elif key == "kernel_api":
            if not xp_gap_audit:
                status = _worst_status(doc_status, "warn")
                current = f"{current}; XP Gap/API audit not supplied"
            elif gap_status == "pass":
                status = _worst_status(doc_status, "ready")
                current = f"{current}; protocol layer covered by local tests, hardware truth still downstream"
            else:
                status = _worst_status(doc_status, gap_status or "warn")
                current = f"{current}; XP Gap API status={gap_status or 'unknown'}"
        elif key == "python_sdk":
            if not xp_gap_audit:
                status = _worst_status(doc_status, "pending")
                current = f"{current}; SDK/API drift not compared with XP Gap"
            elif gap_status == "pass":
                status = _worst_status(doc_status, "ready")
                current = f"{current}; helper compatibility is local, not hardware proof"
            else:
                status = _worst_status(doc_status, "warn" if gap_status == "warn" else "fail")
                current = f"{current}; SDK/script runtime gap={gap_status or 'unknown'}"
        elif key == "console_gui":
            status = _worst_status(doc_status, "ready")
            current = f"{current}; GUI can guide operators but exports are not evidence"
        elif key == "evidence_readiness":
            if acceptance_ok and readiness_ok and real_ios_verified and fail_events == 0:
                status = _worst_status(doc_status, "pass")
                current = f"{current}; evidence gates support current stage only"
            elif evidence_exists and total_events:
                status = _worst_status(doc_status, "fail" if fail_events else "warn")
                current = f"{current}; component={component_text}; acceptance_ok={acceptance_ok}; readiness_ok={readiness_ok}"
            else:
                status = _worst_status(doc_status, "fail")
                current = f"{current}; no JSONL evidence for real iPhone control"
        elif key == "group_ops":
            if normalized_stage in {"p3", "p4"}:
                if not evidence_exists or total_events == 0 or metric_events == 0:
                    status = _worst_status(doc_status, "fail")
                    current = f"{current}; {normalized_stage.upper()} needs per-device evidence and metrics"
                elif fail_events:
                    status = _worst_status(doc_status, "fail")
                    current = f"{current}; scale blocked by failed per-device evidence"
                else:
                    status = _worst_status(doc_status, "ready" if readiness_ok else "warn")
                    current = f"{current}; group layer review applies to exact device count only"
            else:
                status = _worst_status(doc_status, "pending")
                current = f"{current}; group ops intentionally delayed until P1/P2 proof"

        method = str(topic["method"])
        rows.append({
            "key": key,
            "layer": str(topic["layer"]),
            "status": status,
            "xp_gap_status": gap_status or "-",
            "xp_signal": str(topic["xp_signal"]),
            "principle": str(topic["principle"]),
            "local_surface": str(topic["local_surface"]),
            "current": current,
            "proof_gate": str(topic["proof_gate"]),
            "stop_rule": str(topic["stop_rule"]),
            "source": str(topic["source"]),
            "source_doc": source_doc,
            "gui_action": _xp_architecture_gui_action(method),
            "method": method,
        })
    return rows


def xp_architecture_map_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts = _row_status_counts(rows)
    first_focus = _first_attention_value(rows, "layer", statuses={"fail", "pending", "warn"})
    return (
        f"XP architecture {stage.upper()}: "
        f"pass={counts.get('pass', 0)}, ready={counts.get('ready', 0)}, "
        f"warn={counts.get('warn', 0)}, fail={counts.get('fail', 0)}, "
        f"pending={counts.get('pending', 0)}; first_focus={first_focus}"
    )


def write_xp_architecture_map_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    stage: str = "p1",
    evidence_path: str | Path = "",
    readiness_report: dict | None = None,
) -> Path:
    out_path = Path(path)
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))
    lines = [
        f"# XP Architecture Map {stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        f"- Real iOS control verified: `{real_ios_verified}`",
        "- This map explains the inferred XP architecture and local proof gates. It does not write JSONL evidence, does not prove real iPhone response, and does not prove XP parity.",
        "",
        "## Architecture Layers",
        "",
        "| Layer | Status | XP Gap | Public signal | Inferred principle | Local surface | Current local state | Proof gate | Stop rule | Source | GUI action |",
        "|---|---|---|---|---|---|---|---|---|---|---|",
    ]
    for row in rows:
        lines.append(
            f"| {_md_cell(row.get('layer', ''))} | `{_md_cell(row.get('status', ''))}` | "
            f"`{_md_cell(row.get('xp_gap_status', ''))}` | {_md_cell(row.get('xp_signal', ''))} | "
            f"{_md_cell(row.get('principle', ''))} | {_md_cell(row.get('local_surface', ''))} | "
            f"{_md_cell(row.get('current', ''))} | {_md_cell(row.get('proof_gate', ''))} | "
            f"{_md_cell(row.get('stop_rule', ''))} | {_md_cell(row.get('source', ''))} | "
            f"{_md_cell(row.get('gui_action', ''))} |"
        )
    if not rows:
        lines.append("| none | `pending` | `-` | no rows built | Refresh XP Arch | - | - | - | Do not promote | - | - |")
    lines.extend([
        "",
        "## Review Rule",
        "",
        "Use XP Arch before Core, Roadmap, and XP Gap reviews. Architecture rows explain how the system should be built; only same-run field evidence, Acceptance, Readiness, logs, and exact device/iOS coverage can close a capability claim.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


def _xp_hardware_lab_gui_action(method: str) -> str:
    return {
        "edit_route_decision_from_gui": "Edit Route",
        "show_receiver_candidate_scorecard_from_gui": "Open Rx Score",
        "show_hardware_bench_from_gui": "Open Bench",
        "show_control_response_bench_from_gui": "Open Control Bench",
        "show_xp_architecture_map_from_gui": "Open XP Arch",
        "show_ios_field_sop_from_gui": "Open iOS SOP",
        "run_capture_quality_bench_from_gui": "Run Shot Bench",
        "attach_callback_log_from_gui": "Attach Log",
        "show_stage_dashboard_from_gui": "Open Dashboard",
    }.get(method, method)


def _lab_route_value(route_decision: dict | None, values: dict[str, str], path: str) -> str:
    value = values.get(path, "")
    if value in {"", None}:
        value = nested_get(route_decision or {}, path, "")
    if isinstance(value, list):
        return ", ".join(str(item).strip() for item in value if str(item).strip())
    return str(value or "").strip()


def _lab_required_fields_gate(
    route_decision: dict | None,
    values: dict[str, str],
    fields: tuple[str, ...],
) -> tuple[str, str]:
    if not route_decision:
        return "pending", "Route Decision is not loaded."
    missing: list[str] = []
    placeholders: list[str] = []
    for field in fields:
        value = _lab_route_value(route_decision, values, field)
        if not value:
            missing.append(field)
        elif _route_form_has_placeholder(value):
            placeholders.append(field)
    if missing or placeholders:
        parts: list[str] = []
        if missing:
            parts.append(f"missing={', '.join(missing[:4])}")
        if placeholders:
            parts.append(f"placeholder={', '.join(placeholders[:4])}")
        return "fail", "; ".join(parts)
    return "pass", f"fields locked: {', '.join(fields[:4])}"


def xp_hardware_lab_rows(
    *,
    stage: str = "p1",
    docs_root: str | Path = ".",
    device_ids: list[str] | None = None,
    route_decision: dict | None = None,
    route_report: dict | None = None,
    doctor_report: dict | None = None,
    acceptance_report: dict | None = None,
    readiness_report: dict | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
    xp_gap_audit: dict | None = None,
) -> list[dict[str, str]]:
    """Build the XP hardware lab board without writing evidence."""
    root = Path(docs_root)
    normalized_stage = stage.lower().strip() or "p1"
    selected_devices = [str(item).strip() for item in (device_ids or []) if str(item).strip()]
    required_devices = STAGE_DEVICE_REQUIREMENTS.get(normalized_stage, 1)
    values = route_decision_form_values(route_decision or {}) if route_decision else {}
    receiver_route = _lab_route_value(route_decision, values, "receiver.route")
    receiver_name = _lab_route_value(route_decision, values, "receiver.name")
    receiver_version = _lab_route_value(route_decision, values, "receiver.version")
    capture_method = _lab_route_value(route_decision, values, "receiver.capture_method")
    hid_route = _lab_route_value(route_decision, values, "hid.route")
    hid_provider = _lab_route_value(route_decision, values, "hid.provider")
    hid_id = _lab_route_value(route_decision, values, "hid.id")
    iphone_model = _lab_route_value(route_decision, values, "iphone.model")
    ios_version = _lab_route_value(route_decision, values, "iphone.ios_version")
    route_ready = bool(route_report and route_report.get("ok") and route_report.get("ready"))
    route_failed = bool(route_report and not route_ready)
    doctor_overall = str((doctor_report or {}).get("overall", "") or "").lower()
    doctor_clean = doctor_overall == "ok"
    doctor_failed = doctor_overall == "fail"
    readiness_ok = bool(readiness_report and readiness_report.get("ok"))
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))
    screenshot_status, screenshot_text = _acceptance_check_line(acceptance_report, "screenshot_quality")
    manual_status, manual_text = _acceptance_check_line(acceptance_report, "manual_observation")
    component_status, component_text = _acceptance_check_line(acceptance_report, "component_traceability")
    summary = evidence_summary or {}
    status_counts = summary.get("by_status", {}) if isinstance(summary.get("by_status"), dict) else {}
    total_events = int(summary.get("total", 0) or 0)
    fail_events = int(status_counts.get("fail", 0) or 0)
    metric_events = int(summary.get("metrics", {}).get("count", 0) or 0) if isinstance(summary.get("metrics"), dict) else 0

    ledger_gate = _lab_required_fields_gate(
        route_decision,
        values,
        (
            "receiver.route",
            "receiver.name",
            "receiver.version",
            "receiver.capture_method",
            "hid.route",
            "hid.provider",
            "hid.id",
            "hid.firmware",
            "iphone.model",
            "iphone.ios_version",
            "bench.device_id",
            "bench.hub_id",
            "bench.hub_port",
            "bench.cable_id",
            "bench.operator",
        ),
    )
    receiver_gate = _lab_required_fields_gate(
        route_decision,
        values,
        (
            "receiver.route",
            "receiver.name",
            "receiver.version",
            "receiver.path",
            "receiver.capture_method",
            "receiver.start_command",
            "receiver.airplay_name",
        ),
    )
    hid_gate = _lab_required_fields_gate(
        route_decision,
        values,
        ("hid.route", "hid.provider", "hid.id", "hid.firmware", "hid.serial_port"),
    )
    iphone_gate = _lab_required_fields_gate(
        route_decision,
        values,
        ("iphone.model", "iphone.ios_version", "iphone.assistive_touch", "iphone.pointer_speed"),
    )
    bench_gate = _lab_required_fields_gate(
        route_decision,
        values,
        ("bench.device_id", "bench.hub_id", "bench.hub_port", "bench.cable_id", "bench.operator"),
    )

    rows: list[dict[str, str]] = []
    for topic in XP_HARDWARE_LAB_TOPICS:
        key = str(topic["key"])
        source_doc = str(topic["source_doc"])
        doc_status = "pass" if (root / source_doc).exists() else "fail"
        gap_status = _xp_gap_status_for_domains(
            xp_gap_audit,
            tuple(str(fragment) for fragment in topic.get("gap_fragments", ())),
        )
        status = "pending"
        current = (
            f"stage={normalized_stage.upper()}; devices={len(selected_devices)}/{required_devices}; "
            f"receiver={receiver_route or '-'}:{receiver_name or '-'}:{receiver_version or '-'}; "
            f"capture={capture_method or '-'}; hid={hid_route or '-'}:{hid_provider or '-'}:{hid_id or '-'}; "
            f"iphone={iphone_model or '-'}:{ios_version or '-'}; doctor={doctor_overall or '-'}; "
            f"events={total_events if evidence_exists else 0}; fail_events={fail_events}; "
            f"screenshot={screenshot_text}; manual={manual_text}; real_ios_verified={real_ios_verified}"
        )

        if key == "route_procurement_ledger":
            status = ledger_gate[0]
            current = f"{current}; {ledger_gate[1]}"
            if route_report is not None:
                status = _worst_status(status, "pass" if route_ready else "fail")
                current = f"{current}; route_ready={route_ready}"
        elif key == "receiver_capture_rig":
            status = receiver_gate[0]
            current = f"{current}; {receiver_gate[1]}"
            if doctor_failed or route_failed or screenshot_status == "fail":
                status = _worst_status(status, "fail")
            elif route_ready and doctor_clean and screenshot_status == "pass" and fail_events == 0:
                status = _worst_status(status, "ready")
                current = f"{current}; receiver/capture can support the current run only"
            elif status == "pass":
                status = "warn"
                current = f"{current}; receiver selected but screenshot or Doctor proof is incomplete"
        elif key == "windows_wired_decode_lane":
            selected_product_route = receiver_route in {"windows_receiver", "wired", "capture_card"}
            if not selected_product_route:
                status = "pending"
                current = f"{current}; product receiver lane not selected for this run"
            elif doctor_failed or screenshot_status == "fail":
                status = "fail"
                current = f"{current}; selected product receiver is blocked by Doctor or screenshot quality"
            elif screenshot_status == "pass" and metric_events > 0 and fail_events == 0:
                status = "ready"
                current = f"{current}; product receiver has screenshot and metrics evidence for review"
            elif screenshot_status == "pass":
                status = "warn"
                current = f"{current}; screenshots exist, but decode/fps/reconnect metrics still need bench evidence"
            else:
                status = "warn" if receiver_gate[0] == "pass" else receiver_gate[0]
                current = f"{current}; product receiver procurement still needs measured artifacts"
        elif key == "hid_controller_rig":
            status = hid_gate[0]
            current = f"{current}; {hid_gate[1]}"
            if manual_status == "fail" or doctor_failed:
                status = _worst_status(status, "fail")
            elif manual_status == "pass" and real_ios_verified and fail_events == 0:
                status = _worst_status(status, "ready")
                current = f"{current}; HID controls current iPhone only, not XP hardware parity"
            elif status == "pass":
                status = "warn"
                current = f"{current}; HID is configured but visible iPhone response is not proven"
        elif key == "xp_dedicated_hardware_parity":
            if hid_route == "xp_hardware":
                if manual_status == "pass" and real_ios_verified:
                    status = "warn"
                    current = f"{current}; XP hardware selected and field response exists, but side-by-side parity is still open"
                elif hid_gate[0] == "pass":
                    status = "warn"
                    current = f"{current}; XP hardware selected, but real response and side-by-side evidence are missing"
                else:
                    status = hid_gate[0]
                    current = f"{current}; XP hardware route is selected but not fully described"
            else:
                status = "pending"
                current = f"{current}; current HID route is generic or unset, so XP hardware parity is unproven"
        elif key == "iphone_settings_fixture":
            status = iphone_gate[0]
            current = f"{current}; {iphone_gate[1]}; component={component_text}"
            if component_status == "fail":
                status = _worst_status(status, "fail")
            elif status == "pass" and component_status == "pass":
                status = "ready"
            elif status == "pass":
                status = "warn"
        elif key == "hub_cable_power_map":
            status = "ready" if bench_gate[0] == "pass" else bench_gate[0]
            current = f"{current}; {bench_gate[1]}"
        elif key == "capture_stability_metrics":
            if screenshot_status == "fail":
                status = "fail"
                current = f"{current}; screenshot quality blocks stability work"
            elif screenshot_status == "pass" and metric_events > 0 and fail_events == 0:
                status = "ready"
                current = f"{current}; screenshot and metrics evidence exists for this run"
            elif screenshot_status == "pass":
                status = "warn"
                current = f"{current}; first screenshot proof exists, but stability metrics are incomplete"
            elif evidence_exists and total_events:
                status = "warn"
                current = f"{current}; evidence exists but screenshot quality has not passed"
            else:
                status = "pending"
                current = f"{current}; no screenshot or metrics evidence"
        elif key == "logs_recovery_bridge":
            if fail_events:
                status = "warn"
                current = f"{current}; failed events require attached logs, callback rows, triage, and recovery"
            elif evidence_exists and total_events:
                status = "pending"
                current = f"{current}; attach logs before longer reruns even when current events have no fail"
            else:
                status = "pending"
                current = f"{current}; no field events or logs attached"
        elif key == "scale_procurement_boundary":
            if normalized_stage in {"p3", "p4"}:
                if len(selected_devices) < required_devices or metric_events == 0 or not readiness_ok or fail_events:
                    status = "fail"
                    current = f"{current}; scale gate needs devices, metrics, readiness, and no hidden failures"
                else:
                    status = "ready"
                    current = f"{current}; scale procurement can be reviewed for the exact device count"
            else:
                status = "pending"
                current = f"{current}; scale buying waits for P1/P2 proof"

        method = str(topic["method"])
        rows.append({
            "key": key,
            "lane": str(topic["lane"]),
            "status": _worst_status(doc_status, status),
            "xp_gap_status": gap_status or "-",
            "buy_decision": str(topic["buy_decision"]),
            "current": current,
            "lab_test": str(topic["lab_test"]),
            "evidence_required": str(topic["evidence_required"]),
            "stop_rule": str(topic["stop_rule"]),
            "source": str(topic["source"]),
            "source_doc": source_doc,
            "gui_action": _xp_hardware_lab_gui_action(method),
            "method": method,
        })
    return rows


def xp_hardware_lab_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts = _row_status_counts(rows)
    first_focus = _first_attention_value(rows, "lane", statuses={"fail", "pending", "warn"})
    return (
        f"XP hardware lab {stage.upper()}: "
        f"pass={counts.get('pass', 0)}, ready={counts.get('ready', 0)}, "
        f"warn={counts.get('warn', 0)}, fail={counts.get('fail', 0)}, "
        f"pending={counts.get('pending', 0)}; first_focus={first_focus}"
    )


def write_xp_hardware_lab_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    stage: str = "p1",
    evidence_path: str | Path = "",
    readiness_report: dict | None = None,
) -> Path:
    out_path = Path(path)
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))
    lines = [
        f"# XP Hardware Lab {stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        f"- Real iOS control verified: `{real_ios_verified}`",
        "- This lab board guides procurement and hardware validation. It does not write JSONL evidence, does not prove real iPhone response, and does not prove XP dedicated-hardware parity.",
        "",
        "## Lab Rows",
        "",
        "| Lane | Status | XP Gap | Procurement decision | Current local state | Lab test | Evidence required | Stop rule | Source | GUI action |",
        "|---|---|---|---|---|---|---|---|---|---|",
    ]
    for row in rows:
        lines.append(
            f"| {_md_cell(row.get('lane', ''))} | `{_md_cell(row.get('status', ''))}` | "
            f"`{_md_cell(row.get('xp_gap_status', ''))}` | {_md_cell(row.get('buy_decision', ''))} | "
            f"{_md_cell(row.get('current', ''))} | {_md_cell(row.get('lab_test', ''))} | "
            f"{_md_cell(row.get('evidence_required', ''))} | {_md_cell(row.get('stop_rule', ''))} | "
            f"`{_md_cell(row.get('source', ''))}` | {_md_cell(row.get('gui_action', ''))} |"
        )
    if not rows:
        lines.append("| none | `pending` | `-` | no rows built | Refresh XP Lab | - | - | Do not buy or claim | - | - |")
    lines.extend([
        "",
        "## Lab Rule",
        "",
        "Use XP Lab before buying receiver/HID hardware, before changing route decisions, and before any XP-parity wording. A ready lab row means the procurement or bench lane is reviewable; only same-run field evidence, Acceptance, Readiness, and side-by-side legal XP hardware artifacts can close control or parity claims.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


