def _xp_core_gate_status(xp_gap_audit: dict | None, fragments: tuple[str, ...]) -> str:
    status = _xp_gap_status_for_domains(xp_gap_audit, fragments)
    return status or "pending"


def xp_core_function_matrix_rows(
    *,
    stage: str = "p1",
    docs_root: str | Path = ".",
    route_decision: dict | None = None,
    route_report: dict | None = None,
    doctor_report: dict | None = None,
    acceptance_report: dict | None = None,
    readiness_report: dict | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
    xp_gap_audit: dict | None = None,
) -> list[dict[str, str]]:
    """Build a GUI-facing XP core function matrix without writing evidence."""
    root = Path(docs_root)
    normalized_stage = stage.lower().strip() or "p1"
    route_values = route_decision_form_values(route_decision or {}) if route_decision else {}
    receiver_route = str(route_values.get("receiver.route", nested_get(route_decision or {}, "receiver.route", "")) or "").strip()
    hid_route = str(route_values.get("hid.route", nested_get(route_decision or {}, "hid.route", "")) or "").strip()
    route_ready = bool(route_report and route_report.get("ok") and route_report.get("ready"))
    doctor_overall = str((doctor_report or {}).get("overall", "") or "").lower()
    doctor_clean = doctor_overall == "ok"
    doctor_failed = doctor_overall == "fail"
    acceptance_ok = bool(acceptance_report and acceptance_report.get("ok"))
    readiness_ok = bool(readiness_report and readiness_report.get("ok"))
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))
    screenshot_status, screenshot_text = _acceptance_check_line(acceptance_report, "screenshot_quality")
    manual_status, manual_text = _acceptance_check_line(acceptance_report, "manual_observation")
    metrics_status, metrics_text = _acceptance_check_line(acceptance_report, "metrics")
    component_status, component_text = _acceptance_check_line(acceptance_report, "component_traceability")
    summary = evidence_summary or {}
    status_counts = summary.get("by_status", {}) if isinstance(summary.get("by_status"), dict) else {}
    total_events = int(summary.get("total", 0) or 0)
    fail_events = int(status_counts.get("fail", 0) or 0)
    metric_events = int(summary.get("metrics", {}).get("count", 0) or 0) if isinstance(summary.get("metrics"), dict) else 0

    def field_control_status(gap_status: str) -> str:
        if doctor_failed or manual_status == "fail":
            return _worst_status(gap_status, "fail")
        if manual_status == "pass" and real_ios_verified and fail_events == 0:
            return _worst_status(gap_status, "pass")
        if manual_status == "pass":
            return _worst_status(gap_status, "warn")
        if route_ready and doctor_clean:
            return _worst_status(gap_status, "pending")
        return _worst_status(gap_status, "fail" if route_report or doctor_report else "pending")

    rows: list[dict[str, str]] = []
    for topic in XP_CORE_FUNCTION_TOPICS:
        key = str(topic["key"])
        source = str(topic["source"])
        fragments = tuple(str(fragment) for fragment in topic.get("gap_fragments", ()))
        doc_status = "pass" if (root / source).exists() else "fail"
        gap_status = _xp_core_gate_status(xp_gap_audit, fragments)
        status = _worst_status(doc_status, gap_status)
        current_gate = (
            f"stage={normalized_stage.upper()}; route_ready={route_ready}; "
            f"doctor={doctor_overall or '-'}; events={total_events}, fail={fail_events}"
        )

        if key == "product_route":
            if acceptance_ok and readiness_ok and real_ios_verified and fail_events == 0:
                status = _worst_status(doc_status, "ready")
                current_gate = "current route has field proof for the selected device only; broad XP parity still needs side-by-side evidence"
            elif acceptance_report is None and readiness_report is None:
                status = _worst_status(doc_status, "pending")
                current_gate = "Acceptance/Readiness not evaluated; no product-route claim"
            elif acceptance_ok and readiness_ok and not real_ios_verified:
                status = _worst_status(doc_status, "warn")
                current_gate = "gates look clean, but readiness says real_ios_verified=False"
            else:
                status = _worst_status(doc_status, "fail")
                current_gate = f"acceptance_ok={acceptance_ok}, readiness_ok={readiness_ok}, real_ios_verified={real_ios_verified}"
        elif key in {"kernel_api", "python_sdk"}:
            if gap_status == "pass":
                status = _worst_status(doc_status, "ready")
                current_gate = f"local compatibility assets pass; real hardware behavior still requires field evidence"
            elif gap_status in {"fail", "warn"}:
                status = _worst_status(doc_status, gap_status)
                current_gate = f"XP Gap status={gap_status}; keep service/client coverage before claiming parity"
            else:
                status = _worst_status(doc_status, "pending")
                current_gate = "XP Gap audit not built for this domain"
        elif key == "device_group":
            if normalized_stage in {"p3", "p4"} and (not evidence_exists or fail_events):
                status = _worst_status(doc_status, "fail")
                current_gate = f"{normalized_stage.upper()} group evidence missing or failing; events={total_events}, fail={fail_events}"
            elif component_status == "pass" and route_ready:
                status = _worst_status(doc_status, "ready" if gap_status != "fail" else "warn")
                current_gate = f"component={component_text}; local groups usable, cloud/account parity not proven"
            else:
                status = _worst_status(doc_status, "warn" if route_ready else "pending")
                current_gate = f"component={component_text}; receiver={receiver_route or '-'}; hid={hid_route or '-'}"
        elif key == "receiver_capture":
            if doctor_failed or screenshot_status == "fail":
                status = _worst_status(doc_status, "fail")
            elif screenshot_status == "pass" and doctor_clean:
                status = _worst_status(doc_status, "ready")
            elif route_ready and doctor_clean:
                status = _worst_status(doc_status, "pending")
            else:
                status = _worst_status(doc_status, "fail" if route_report or doctor_report else "pending")
            current_gate = f"receiver={receiver_route or '-'}; doctor={doctor_overall or '-'}; screenshot={screenshot_text}"
        elif key == "screenshot_capture":
            if screenshot_status == "pass" and fail_events == 0:
                status = _worst_status(doc_status, "pass")
            elif screenshot_status == "fail" or doctor_failed:
                status = _worst_status(doc_status, "fail")
            else:
                status = _worst_status(doc_status, "pending")
            current_gate = f"screenshot={screenshot_text}; events={total_events}, fail={fail_events}"
        elif key in {"hid_control", "calibration", "mouse_keyboard"}:
            status = field_control_status(gap_status)
            current_gate = (
                f"hid={hid_route or '-'}; manual={manual_text}; "
                f"real_ios_verified={real_ios_verified}; XP hardware parity=unverified"
            )
        elif key in {"vision_color", "ocr_text"}:
            if screenshot_status == "fail":
                status = _worst_status(doc_status, "fail")
                current_gate = f"screenshot={screenshot_text}; build no vision claim"
            elif not evidence_exists or total_events == 0:
                status = _worst_status(doc_status, "pending")
                current_gate = "no real screenshot artifacts yet"
            elif fail_events:
                status = _worst_status(doc_status, "warn")
                current_gate = f"events={total_events}, fail={fail_events}; replay assets required"
            elif screenshot_status == "pass":
                status = _worst_status(doc_status, "ready")
                current_gate = "screenshot evidence exists; build templates/OCR assets before scale"
            else:
                status = _worst_status(doc_status, "pending")
                current_gate = f"screenshot={screenshot_text}"
        elif key == "script_batch_runtime":
            if not evidence_exists or total_events == 0:
                status = _worst_status(doc_status, "pending")
                current_gate = "dry-run/real-run evidence missing"
            elif fail_events:
                status = _worst_status(doc_status, "warn")
                current_gate = f"failed evidence events={fail_events}; fix replay and isolation before scale"
            elif metric_events or metrics_status == "pass":
                status = _worst_status(doc_status, "ready")
                current_gate = f"events={total_events}, metrics={metric_events}; {metrics_text}"
            else:
                status = _worst_status(doc_status, "ready" if normalized_stage == "p1" else "warn")
                current_gate = f"events={total_events}; metrics={metric_events}; stage={normalized_stage.upper()}"
        elif key == "gui_console":
            if gap_status == "pass":
                status = _worst_status(doc_status, "ready")
            elif gap_status in {"warn", "fail"}:
                status = _worst_status(doc_status, gap_status)
            else:
                status = _worst_status(doc_status, "ready")
            current_gate = "GUI/SOP surface exists; realtime grid and replay UI still wait for receiver field route"
        elif key == "config_user_shortcut":
            status = _worst_status(doc_status, "warn")
            current_gate = "local config/user/shortcut scaffolding only; no XP cloud, permission, license, or shortcut execution proof"
        elif key == "observability":
            if fail_events:
                status = _worst_status(doc_status, "warn")
                current_gate = f"failed events={fail_events}; attach logs and classify before rerun"
            elif evidence_exists and total_events > 0:
                status = _worst_status(doc_status, "ready")
                current_gate = f"events={total_events}, metrics={metric_events}; callback/log coverage still needs field devices"
            else:
                status = _worst_status(doc_status, "pending")
                current_gate = "no evidence ledger yet"
        elif key == "commercial_ops":
            if normalized_stage in {"p3", "p4"} and evidence_exists and fail_events == 0:
                status = _worst_status(doc_status, "warn")
                current_gate = "post-P3 design candidate only; do not count as core control proof"
            else:
                status = _worst_status(doc_status, "pending")
                current_gate = "deferred until P3/P4 field control is proven"

        rows.append({
            "key": key,
            "domain": str(topic["domain"]),
            "layer": str(topic["layer"]),
            "priority": str(topic["priority"]),
            "status": status,
            "xp_gap_status": gap_status,
            "public_signal": str(topic["public_signal"]),
            "local_support": str(topic["local_support"]),
            "current_gate": current_gate,
            "evidence_required": str(topic["evidence_required"]),
            "gap": str(topic["gap"]),
            "source": source,
            "stage": normalized_stage,
            "gui_action": _xp_core_function_gui_action(str(topic["method"])),
            "method": str(topic["method"]),
        })
    return rows


def xp_core_function_matrix_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts = _row_status_counts(rows)
    first_focus = _first_attention_value(rows, "domain", statuses={"fail", "pending", "warn"})
    return (
        f"XP core functions {stage.upper()}: "
        f"pass={counts.get('pass', 0)}, ready={counts.get('ready', 0)}, "
        f"warn={counts.get('warn', 0)}, fail={counts.get('fail', 0)}, "
        f"pending={counts.get('pending', 0)}; first_focus={first_focus}"
    )


def write_xp_core_function_matrix_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    stage: str = "p1",
    evidence_path: str | Path = "",
    readiness_report: dict | None = None,
) -> Path:
    out_path = Path(path)
    real_ios_verified = bool(
        (readiness_report or {}).get("claims", {}).get("real_ios_control_verified")
    )
    lines = [
        f"# XP Core Function Matrix {stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        f"- Real iOS control verified: `{real_ios_verified}`",
        "- This matrix maps XP core functions to local implementation and evidence gates. It does not write evidence and does not prove XP parity.",
        "",
        "## Function Rows",
        "",
        "| Domain | Layer | Priority | Status | XP Gap | Public signal | Local support | Current gate | Evidence required | Gap | Source | GUI action |",
        "|---|---|---|---|---|---|---|---|---|---|---|---|",
    ]
    for row in rows:
        lines.append(
            f"| {_md_cell(row.get('domain', ''))} | {_md_cell(row.get('layer', ''))} | "
            f"{_md_cell(row.get('priority', ''))} | `{_md_cell(row.get('status', ''))}` | "
            f"`{_md_cell(row.get('xp_gap_status', ''))}` | {_md_cell(row.get('public_signal', ''))} | "
            f"{_md_cell(row.get('local_support', ''))} | {_md_cell(row.get('current_gate', ''))} | "
            f"{_md_cell(row.get('evidence_required', ''))} | {_md_cell(row.get('gap', ''))} | "
            f"`{_md_cell(row.get('source', ''))}` | {_md_cell(row.get('gui_action', ''))} |"
        )
    if not rows:
        lines.append("| none | - | - | `pending` | `pending` | no rows built | Refresh Core | - | - | - | - | - |")
    lines.extend([
        "",
        "## Review Rule",
        "",
        "Use Core with XP Gap, Sources, Routes and Goals. API/SDK readiness is not the same as real iPhone control; HID, receiver, screenshot, calibration and input domains need JSONL evidence, saved artifacts, Acceptance, Readiness and manual observation before promotion.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


