def _source_refresh_doc_stamp(path: Path) -> str:
    try:
        if not path.exists():
            return "missing"
        return datetime.fromtimestamp(path.stat().st_mtime).strftime("%Y-%m-%d")
    except OSError:
        return "unreadable"


def xp_source_refresh_rows(
    *,
    stage: str = "p1",
    docs_root: str | Path = ".",
    route_report: dict | None = None,
    doctor_report: dict | None = None,
    acceptance_report: dict | None = None,
    readiness_report: dict | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
    xp_gap_audit: dict | None = None,
) -> list[dict[str, str]]:
    """Build the public-source refresh board without fetching or trusting sources."""
    root = Path(docs_root)
    normalized_stage = stage.lower().strip() or "p1"
    summary = evidence_summary or {}
    status_counts = summary.get("by_status", {}) if isinstance(summary.get("by_status"), dict) else {}
    total_events = int(summary.get("total", 0) or 0)
    fail_events = int(status_counts.get("fail", 0) or 0)
    route_ready = bool(route_report and route_report.get("ok") and route_report.get("ready"))
    doctor_overall = str((doctor_report or {}).get("overall", "") or "").lower()
    doctor_clean = doctor_overall == "ok"
    acceptance_ok = bool(acceptance_report and acceptance_report.get("ok"))
    readiness_ok = bool(readiness_report and readiness_report.get("ok"))
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))
    xp_rows = (xp_gap_audit or {}).get("rows", []) if isinstance(xp_gap_audit, dict) else []
    xp_blocked = any(
        str(row.get("status", "") or "").lower() in {"blocked", "fail"}
        for row in xp_rows
        if isinstance(row, dict)
    )

    rows: list[dict[str, str]] = []
    for topic in XP_SOURCE_REFRESH_TOPICS:
        local_doc = str(topic["local_doc"])
        doc_path = root / local_doc
        doc_status = "pass" if doc_path.exists() else "fail"
        doc_stamp = _source_refresh_doc_stamp(doc_path)
        key = str(topic["key"])
        current = (
            f"stage={normalized_stage.upper()}; doc={doc_stamp}; route_ready={route_ready}; "
            f"doctor={doctor_overall or '-'}; evidence_exists={evidence_exists}; "
            f"events={total_events}; fail_events={fail_events}; real_ios_verified={real_ios_verified}"
        )

        if key == "official_homepage_refresh":
            status = "fail" if doc_status == "fail" else "ready" if real_ios_verified else "warn"
            current = f"{current}; homepage claims must be rechecked before compatibility or XP-route wording"
        elif key == "official_api_refresh":
            if doc_status == "fail":
                status = "fail"
            elif doctor_clean and not xp_blocked:
                status = "ready"
            else:
                status = "warn" if doctor_report is not None else "pending"
            current = f"{current}; doctor_clean={doctor_clean}; xp_blocked={xp_blocked}"
        elif key == "official_help_iteration_refresh":
            status = "fail" if doc_status == "fail" else "warn" if xp_blocked else "ready"
            current = f"{current}; xp_gap_blocked={xp_blocked}"
        elif key == "package_registry_refresh":
            status = "fail" if doc_status == "fail" else "warn"
            current = f"{current}; package versions are drift/supply-chain signals until pinned and reviewed"
        elif key == "apple_ios_pointer_refresh":
            if doc_status == "fail":
                status = "fail"
            elif acceptance_ok and readiness_ok and real_ios_verified:
                status = "ready"
            else:
                status = "warn"
            current = f"{current}; acceptance_ok={acceptance_ok}; readiness_ok={readiness_ok}"
        elif key == "industry_route_refresh":
            if doc_status == "fail":
                status = "fail"
            elif route_ready and doctor_clean:
                status = "ready"
            elif route_report is None and doctor_report is None:
                status = "pending"
            else:
                status = "warn"
            current = f"{current}; route_ready={route_ready}; doctor_clean={doctor_clean}"
        elif key == "source_to_sop_commit":
            if doc_status == "fail":
                status = "fail"
            elif route_ready or total_events > 0:
                status = "ready"
            else:
                status = "pending"
            current = f"{current}; source refresh must land as GUI owner and SOP gate"
        elif key == "source_claim_boundary_refresh":
            if doc_status == "fail":
                status = "fail"
            elif acceptance_ok and readiness_ok and real_ios_verified and fail_events == 0:
                status = "pass"
            elif acceptance_report is None and readiness_report is None:
                status = "pending"
            else:
                status = "fail"
            current = (
                f"{current}; acceptance_ok={acceptance_ok}; readiness_ok={readiness_ok}; "
                f"source-only claims must be downgraded"
            )
        else:
            status = doc_status

        method = str(topic["method"])
        rows.append({
            "key": key,
            "status": status,
            "source": str(topic["source"]),
            "local_doc": local_doc,
            "doc_stamp": doc_stamp,
            "cadence": str(topic["cadence"]),
            "public_signal": str(topic["signal"]),
            "refresh_action": str(topic["refresh_action"]),
            "landing_action": str(topic["landing_action"]),
            "current": current,
            "stop_rule": (
                "Stop source-derived product claims until the refreshed source is mapped to local SOP gates, "
                "and field claims still require JSONL evidence, Acceptance, and Readiness."
            ),
            "gui_action": _source_refresh_gui_action(method),
            "method": method,
        })
    return rows


def xp_source_refresh_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts = _row_status_counts(rows)
    first_focus = _first_attention_value(rows, "key", statuses={"fail", "pending", "warn"})
    return (
        f"XP source refresh {stage.upper()}: "
        f"pass={counts.get('pass', 0)}, ready={counts.get('ready', 0)}, "
        f"warn={counts.get('warn', 0)}, fail={counts.get('fail', 0)}, "
        f"pending={counts.get('pending', 0)}; first_focus={first_focus}"
    )


def write_xp_source_refresh_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    stage: str = "p1",
    evidence_path: str | Path = "",
    readiness_report: dict | None = None,
) -> Path:
    out_path = Path(path)
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))
    lines = [
        f"# XP Source Refresh Board {stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        f"- Real iOS control verified: `{real_ios_verified}`",
        "- This board is a source-refresh SOP. It does not browse automatically, does not write JSONL evidence, does not prove real iPhone response, and does not prove XP parity.",
        "",
        "## Refresh Rows",
        "",
        "| Key | Status | Source | Local doc | Doc stamp | Cadence | Public signal | Refresh action | Landing action | Current | Stop rule | GUI action |",
        "|---|---|---|---|---|---|---|---|---|---|---|---|",
    ]
    for row in rows:
        lines.append(
            f"| {_md_cell(row.get('key', ''))} | `{_md_cell(row.get('status', ''))}` | "
            f"{_md_cell(row.get('source', ''))} | `{_md_cell(row.get('local_doc', ''))}` | "
            f"{_md_cell(row.get('doc_stamp', ''))} | {_md_cell(row.get('cadence', ''))} | "
            f"{_md_cell(row.get('public_signal', ''))} | {_md_cell(row.get('refresh_action', ''))} | "
            f"{_md_cell(row.get('landing_action', ''))} | {_md_cell(row.get('current', ''))} | "
            f"{_md_cell(row.get('stop_rule', ''))} | {_md_cell(row.get('gui_action', ''))} |"
        )
    if not rows:
        lines.append("| none | `pending` | - | - | - | - | no rows built | Refresh | - | - | Do not promote | - |")
    lines.extend([
        "",
        "## Use Rule",
        "",
        "Refresh public sources before roadmap changes, route changes, dependency adoption, iOS compatibility claims, or demos. Every source delta must become a local SOP gate, test, artifact, or explicit rejection. Source freshness never replaces real-device evidence.",
        "",
    ])
    package_row = next((row for row in rows if row.get("key") == "package_registry_refresh"), None)
    if package_row:
        lines.extend([
            "## Package Namespace Guard",
            "",
            "The GUI tracks `imouse-py`, `imouse-xp`, and `py-imouse-xp` as separate PyPI namespaces. Treat similar names as dependency-confusion and SDK-drift signals, not interchangeable install targets.",
            "",
            "- `imouse-py`: `https://pypi.org/project/imouse-py/`",
            "- `imouse-xp`: `https://pypi.org/project/imouse-xp/`",
            "- `py-imouse-xp`: `https://pypi.org/project/py-imouse-xp/`",
            "",
            f"- Current package row: `{_md_cell(package_row.get('status', ''))}`; {_md_cell(package_row.get('current', ''))}",
            "- Adoption rule: pin exact version and hashes, review maintainer/source/API surface/license, run local API regressions, then require hardware-backed receiver/HID/iPhone evidence for the exact claim scope.",
            "- Stop rule: do not install lookalike packages on field machines and do not use package import success as XP parity or real iOS control proof.",
            "",
        ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


PACKAGE_NAMESPACE_LABELS = {
    "pypi_imouse_py": "imouse-py",
    "pypi_imouse_xp": "imouse-xp",
    "pypi_py_imouse_xp": "py-imouse-xp",
}


def xp_package_namespace_guard_rows(report: dict[str, Any]) -> list[dict[str, str]]:
    """Turn PyPI audit rows into a GUI adoption guard."""
    package_rows = package_namespace_drift_rows(report)
    rows: list[dict[str, str]] = []
    for package_row in package_rows:
        key = str(package_row.get("key", "") or "")
        package_name = PACKAGE_NAMESPACE_LABELS.get(key, key or "unknown")
        source_status = str(package_row.get("status", "") or "pending").lower()
        if source_status == "fail":
            status = "fail"
        elif source_status == "pending":
            status = "pending"
        else:
            status = "warn"
        version = str(package_row.get("version", "") or "")
        identity = (
            "official Python XP install target"
            if key == "pypi_imouse_py"
            else "similar-name namespace; review as dependency-confusion risk"
        )
        rows.append({
            "key": key,
            "package": package_name,
            "status": status,
            "source_status": source_status or "pending",
            "url": str(package_row.get("url", "") or ""),
            "version": version or "-",
            "summary": str(package_row.get("summary", "") or ""),
            "project_urls": str(package_row.get("project_urls", "") or ""),
            "identity": identity,
            "current": (
                f"source_status={source_status or 'pending'}; version={version or '-'}; "
                "package metadata only; import_success_not_control_proof=True"
            ),
            "review_rule": str(package_row.get("review_rule", "") or ""),
            "stop_rule": (
                "Stop dependency adoption until package identity, maintainer/source, exact version, "
                "hashes, license, API behavior, local regressions, and field evidence are all recorded."
            ),
            "claim_boundary": (
                str(package_row.get("claim_boundary", "") or "")
                + " Package rows never write JSONL evidence and never prove XP parity or real iOS control."
            ),
            "gui_action": "Open Source Audit",
            "method": "show_xp_public_source_audit_from_gui",
        })
    if not rows:
        rows.append({
            "key": "package_namespace_sources",
            "package": "imouse-py / imouse-xp / py-imouse-xp",
            "status": "fail",
            "source_status": "missing",
            "url": "https://pypi.org/project/imouse-py/",
            "version": "-",
            "summary": "Package namespace rows were not present in the source audit report.",
            "project_urls": "",
            "identity": "audit coverage gap",
            "current": "Default PyPI source specs are missing from this report.",
            "review_rule": "Rebuild Source Audit with the default source set before dependency review.",
            "stop_rule": "Stop package adoption until all three namespaces are audited.",
            "claim_boundary": "Missing package rows are not evidence and do not prove real iOS control.",
            "gui_action": "Open Source Audit",
            "method": "show_xp_public_source_audit_from_gui",
        })
    return rows


def xp_package_namespace_guard_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts = _row_status_counts(rows)
    first_focus = _first_attention_value(rows, "package", statuses={"fail", "pending", "warn"})
    return (
        f"XP package guard {stage.upper()}: "
        f"warn={counts.get('warn', 0)}, fail={counts.get('fail', 0)}, "
        f"pending={counts.get('pending', 0)}, ready={counts.get('ready', 0)}, "
        f"pass={counts.get('pass', 0)}; first_focus={first_focus}"
    )


def write_xp_package_namespace_guard_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    stage: str = "p1",
    source_audit_overall: str = "",
) -> Path:
    out_path = Path(path)
    lines = [
        f"# XP Package Namespace Guard {stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Source audit overall: `{source_audit_overall}`",
        "- This board is supply-chain and SDK-drift SOP only. It does not install packages, does not write JSONL evidence, does not prove real iPhone response, and does not prove XP parity.",
        "",
        "## Package Rows",
        "",
        "| Package | Status | Source status | Version | URL | Identity | Current | Review rule | Stop rule | Claim boundary | GUI action |",
        "|---|---|---|---|---|---|---|---|---|---|---|",
    ]
    for row in rows:
        lines.append(
            f"| {_md_cell(row.get('package', ''))} | `{_md_cell(row.get('status', ''))}` | "
            f"`{_md_cell(row.get('source_status', ''))}` | {_md_cell(row.get('version', ''))} | "
            f"{_md_cell(row.get('url', ''))} | {_md_cell(row.get('identity', ''))} | "
            f"{_md_cell(row.get('current', ''))} | {_md_cell(row.get('review_rule', ''))} | "
            f"{_md_cell(row.get('stop_rule', ''))} | {_md_cell(row.get('claim_boundary', ''))} | "
            f"{_md_cell(row.get('gui_action', ''))} |"
        )
    lines.extend([
        "",
        "## Adoption SOP",
        "",
        "1. Re-run `Src Audit` live when network is available and keep the Markdown/JSON artifact.",
        "2. Compare `imouse-py`, `imouse-xp`, and `py-imouse-xp` as separate namespaces; never treat a similar name as the official install target.",
        "3. Pin exact version and hashes, review maintainer/source/license/API behavior, then run local API/client regressions in an isolated environment.",
        "4. Only after hardware-backed receiver/HID/iPhone evidence exists for the exact lane may package behavior inform XP parity wording.",
        "",
        "Package import success is never screenshot freshness, HID movement, XP hardware authorization, broad iOS compatibility, or real iPhone control proof.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


def xp_public_source_ledger_rows(
    *,
    stage: str = "p1",
    docs_root: str | Path = ".",
    route_report: dict | None = None,
    doctor_report: dict | None = None,
    acceptance_report: dict | None = None,
    readiness_report: dict | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
    xp_gap_audit: dict | None = None,
) -> list[dict[str, str]]:
    """Map public XP/current-industry signals to verification gates."""
    root = Path(docs_root)
    normalized_stage = stage.lower().strip() or "p1"
    summary = evidence_summary or {}
    status_counts = summary.get("by_status", {}) if isinstance(summary.get("by_status"), dict) else {}
    total_events = int(summary.get("total", 0) or 0)
    fail_events = int(status_counts.get("fail", 0) or 0)
    route_ready = bool(route_report and route_report.get("ok") and route_report.get("ready"))
    doctor_clean = bool(doctor_report and str(doctor_report.get("overall", "") or "").lower() == "ok")
    acceptance_ok = bool(acceptance_report and acceptance_report.get("ok"))
    readiness_ok = bool(readiness_report and readiness_report.get("ok"))
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))
    xp_rows = xp_gap_audit.get("rows", []) if isinstance(xp_gap_audit, dict) else []
    xp_blocked = [
        str(row.get("domain", row.get("name", "")) or "")
        for row in xp_rows
        if isinstance(row, dict)
        and str(row.get("status", "")).lower() in {"blocked", "not_started", "partial"}
    ]

    rows: list[dict[str, str]] = []
    for topic in XP_PUBLIC_SOURCE_TOPICS:
        source_doc = str(topic["source_doc"])
        doc_status = "pass" if (root / source_doc).exists() else "fail"
        key = str(topic["key"])
        status = doc_status
        verification = str(topic["verification"])

        if key == "official_product_model":
            if not evidence_exists or total_events == 0:
                status = _worst_status(doc_status, "pending")
                verification = f"{verification}; current evidence=missing"
            elif fail_events:
                status = _worst_status(doc_status, "fail")
                verification = f"{verification}; current fail_events={fail_events}"
            elif real_ios_verified:
                status = _worst_status(doc_status, "ready")
                verification = f"{verification}; current selected-device evidence exists"
            else:
                status = _worst_status(doc_status, "warn")
                verification = f"{verification}; real_ios_verified=False"
        elif key == "official_current_support_claim":
            status = _worst_status(doc_status, "warn")
            verification = (
                f"{verification}; do not generalize from stage={normalized_stage.upper()} "
                f"or selected-device evidence to all advertised models/iOS versions"
            )
        elif key == "python_xp_helper":
            if not xp_gap_audit:
                status = _worst_status(doc_status, "pending")
                verification = f"{verification}; XP Gap audit not exported"
            elif xp_blocked:
                status = _worst_status(doc_status, "fail")
                verification = f"{verification}; gap_blockers={', '.join(xp_blocked[:4])}"
            else:
                status = _worst_status(doc_status, "ready")
                verification = f"{verification}; no blocked/partial XP domains in current audit"
        elif key == "pypi_imouse_py_release":
            if not xp_gap_audit:
                status = _worst_status(doc_status, "pending")
                verification = f"{verification}; package/API drift has not been compared with XP Gap"
            elif xp_blocked:
                status = _worst_status(doc_status, "warn")
                verification = f"{verification}; package exists but local parity gaps remain={', '.join(xp_blocked[:4])}"
            else:
                status = _worst_status(doc_status, "ready")
                verification = f"{verification}; SDK surface can be treated as integration reference only"
        elif key == "xp_api_protocol":
            if xp_gap_audit:
                status = _worst_status(doc_status, "ready" if not xp_blocked else "warn")
                verification = f"{verification}; xp_gap_blockers={len(xp_blocked)}"
            else:
                status = _worst_status(doc_status, "warn")
                verification = f"{verification}; needs current XP Gap audit"
        elif key == "xp_api_domains":
            if not xp_gap_audit:
                status = _worst_status(doc_status, "pending")
                verification = f"{verification}; XP Gap audit not exported"
            elif xp_blocked:
                status = _worst_status(doc_status, "fail")
                verification = f"{verification}; blocked_domains={', '.join(xp_blocked[:4])}"
            else:
                status = _worst_status(doc_status, "ready")
                verification = f"{verification}; current audit has no blocked domains"
        elif key == "xp_new_version_iteration":
            if route_report is None and doctor_report is None:
                status = _worst_status(doc_status, "pending")
                verification = f"{verification}; route/doctor pending"
            elif route_ready and doctor_clean and real_ios_verified:
                status = _worst_status(doc_status, "warn")
                verification = f"{verification}; current single-device evidence still does not prove XP wired/hardware-decode/auto-binding claims"
            else:
                status = _worst_status(doc_status, "fail")
                verification = f"{verification}; route_ready={route_ready}, doctor_clean={doctor_clean}, real_ios_verified={real_ios_verified}"
        elif key == "official_first_config_mouse_params":
            if route_report is None and doctor_report is None:
                status = _worst_status(doc_status, "pending")
                verification = f"{verification}; route/doctor pending"
            elif route_ready and doctor_clean and real_ios_verified:
                status = _worst_status(doc_status, "ready")
                verification = f"{verification}; iOS settings can be reused only for the exact model/iOS/orientation/profile proved by evidence"
            elif route_ready or doctor_clean or evidence_exists:
                status = _worst_status(doc_status, "warn")
                verification = f"{verification}; settings may be ready, but real_ios_verified={real_ios_verified}"
            else:
                status = _worst_status(doc_status, "pending")
                verification = f"{verification}; settings fields not yet tied to a field run"
        elif key == "claim_boundary":
            if acceptance_ok and readiness_ok and real_ios_verified and fail_events == 0:
                status = _worst_status(doc_status, "pass")
            elif acceptance_report is None and readiness_report is None:
                status = _worst_status(doc_status, "pending")
            elif acceptance_ok and readiness_ok and not real_ios_verified:
                status = _worst_status(doc_status, "warn")
            else:
                status = _worst_status(doc_status, "fail")
            verification = (
                f"{verification}; acceptance_ok={acceptance_ok}, readiness_ok={readiness_ok}, "
                f"real_ios_verified={real_ios_verified}, fail_events={fail_events}"
            )

        rows.append({
            "key": key,
            "tier": str(topic["tier"]),
            "status": status,
            "source": str(topic["source"]),
            "source_doc": source_doc,
            "source_signal": str(topic["signal"]),
            "rd_impact": str(topic["rd_impact"]),
            "verification_gap": verification,
            "gui_action": _source_ledger_gui_action(str(topic["method"])),
            "method": str(topic["method"]),
        })
    return rows


def xp_public_source_ledger_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts: dict[str, int] = {}
    first_blocker = "none"
    for row in rows:
        status = str(row.get("status", "pending") or "pending")
        counts[status] = counts.get(status, 0) + 1
        if first_blocker == "none" and status in {"fail", "pending", "warn"}:
            first_blocker = str(row.get("key", "") or "unknown")
    return (
        f"XP public sources {stage.upper()}: "
        f"pass={counts.get('pass', 0)}, ready={counts.get('ready', 0)}, "
        f"warn={counts.get('warn', 0)}, fail={counts.get('fail', 0)}, "
        f"pending={counts.get('pending', 0)}; first_focus={first_blocker}"
    )


def write_xp_public_source_ledger_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    stage: str = "p1",
    evidence_path: str | Path = "",
    refreshed_at: str = "2026-06-09",
    readiness_report: dict | None = None,
) -> Path:
    out_path = Path(path)
    real_ios_verified = bool(
        (readiness_report or {}).get("claims", {}).get("real_ios_control_verified")
    )
    lines = [
        f"# XP Public Source Ledger {stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        f"- Source refresh date: `{refreshed_at}`",
        f"- Real iOS control verified: `{real_ios_verified}`",
        "- This ledger maps public iMouse XP/current-industry signals to R&D actions and verification gaps. It does not write evidence and does not prove XP parity.",
        "",
        "## Source Rows",
        "",
        "| Key | Tier | Status | Source | Local doc | Public signal | R&D impact | Verification gap | GUI action |",
        "|---|---|---|---|---|---|---|---|---|",
    ]
    for row in rows:
        lines.append(
            f"| {_md_cell(row.get('key', ''))} | {_md_cell(row.get('tier', ''))} | "
            f"`{_md_cell(row.get('status', ''))}` | {_md_cell(row.get('source', ''))} | "
            f"`{_md_cell(row.get('source_doc', ''))}` | {_md_cell(row.get('source_signal', ''))} | "
            f"{_md_cell(row.get('rd_impact', ''))} | {_md_cell(row.get('verification_gap', ''))} | "
            f"{_md_cell(row.get('gui_action', ''))} |"
        )
    if not rows:
        lines.append("| none | - | `pending` | - | - | no rows built | Refresh Sources | Refresh | - |")
    lines.extend([
        "",
        "## Review Rule",
        "",
        "Treat public source claims as backlog inputs until they are backed by local route, hardware, evidence, Acceptance, Readiness, logs, and operator observations. Broad compatibility claims require a device/iOS matrix, not a single clean run.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


