def xp_public_source_action_map_rows(
    *,
    stage: str = "p1",
    docs_root: str | Path = ".",
    route_report: dict | None = None,
    doctor_report: dict | None = None,
    acceptance_report: dict | None = None,
    readiness_report: dict | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
    xp_gap_audit: dict | None = None,
) -> list[dict[str, str]]:
    """Map public-source intelligence to concrete R&D/SOP GUI actions."""
    root = Path(docs_root)
    normalized_stage = stage.lower().strip() or "p1"
    doc_status = "pass" if (root / "docs/xp_public_source_action_map.md").exists() else "fail"
    summary = evidence_summary or {}
    status_counts = summary.get("by_status", {}) if isinstance(summary.get("by_status"), dict) else {}
    total_events = int(summary.get("total", 0) or 0)
    fail_events = int(status_counts.get("fail", 0) or 0)
    route_ready = bool(route_report and route_report.get("ok") and route_report.get("ready"))
    doctor_overall = str((doctor_report or {}).get("overall", "") or "").lower()
    doctor_clean = bool(doctor_overall == "ok")
    doctor_failed = bool(doctor_overall == "fail")
    acceptance_ok = bool(acceptance_report and acceptance_report.get("ok"))
    readiness_ok = bool(readiness_report and readiness_report.get("ok"))
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))
    xp_rows = xp_gap_audit.get("rows", []) if isinstance(xp_gap_audit, dict) else []
    xp_blocked = [
        str(row.get("domain", row.get("name", "")) or "")
        for row in xp_rows
        if isinstance(row, dict)
        and str(row.get("status", "")).lower() in {"blocked", "not_started", "partial"}
    ]

    rows: list[dict[str, str]] = []
    for item in XP_PUBLIC_SOURCE_ACTION_ITEMS:
        key = str(item["key"])
        status = doc_status
        current = (
            f"stage={normalized_stage.upper()}, route_ready={route_ready}, doctor={doctor_overall or 'missing'}, "
            f"evidence_events={total_events if evidence_exists else 0}, fail_events={fail_events}, "
            f"acceptance_ok={acceptance_ok}, readiness_ok={readiness_ok}, real_ios_verified={real_ios_verified}"
        )

        if key == "xp_product_model":
            if doctor_failed:
                status = _worst_status(doc_status, "fail")
            elif not evidence_exists or total_events == 0:
                status = _worst_status(doc_status, "pending")
            elif real_ios_verified:
                status = _worst_status(doc_status, "ready")
            else:
                status = _worst_status(doc_status, "warn")
        elif key == "broad_compatibility_claims":
            status = _worst_status(doc_status, "warn")
            current = f"{current}; compatibility must be exact model+iOS+orientation+profile evidence"
        elif key == "python_sdk_hardware_boundary":
            if not xp_gap_audit:
                status = _worst_status(doc_status, "pending")
            elif xp_blocked:
                status = _worst_status(doc_status, "fail")
            elif real_ios_verified:
                status = _worst_status(doc_status, "ready")
            else:
                status = _worst_status(doc_status, "warn")
            current = f"{current}; xp_gap_blockers={', '.join(xp_blocked[:4]) or 'none'}"
        elif key == "xp_api_contract":
            if not xp_gap_audit:
                status = _worst_status(doc_status, "pending")
            elif xp_blocked:
                status = _worst_status(doc_status, "warn")
            else:
                status = _worst_status(doc_status, "ready")
            current = f"{current}; api contract still needs field callbacks/logs for product claims"
        elif key == "ios_pointer_setup":
            if doctor_failed:
                status = _worst_status(doc_status, "fail")
            elif real_ios_verified:
                status = _worst_status(doc_status, "ready")
            elif route_ready or doctor_clean or evidence_exists:
                status = _worst_status(doc_status, "warn")
            else:
                status = _worst_status(doc_status, "pending")
        elif key == "receiver_capture_route":
            if doctor_failed:
                status = _worst_status(doc_status, "fail")
            elif route_ready and doctor_clean and evidence_exists and fail_events == 0:
                status = _worst_status(doc_status, "ready")
            elif route_ready or doctor_clean:
                status = _worst_status(doc_status, "warn")
            else:
                status = _worst_status(doc_status, "pending")
        elif key == "package_registry_boundary":
            status = _worst_status(doc_status, "warn")
            current = f"{current}; packages are drift/supply-chain inputs, not proof"
        elif key == "group_ops_productization":
            if normalized_stage in {"p3", "p4"} and (not evidence_exists or not readiness_ok):
                status = _worst_status(doc_status, "fail")
            elif normalized_stage in {"p3", "p4"}:
                status = _worst_status(doc_status, "warn")
            else:
                status = _worst_status(doc_status, "pending")
            current = f"{current}; group claims require P3/P4 per-device evidence"
        elif key == "source_to_evidence_boundary":
            if acceptance_ok and readiness_ok and real_ios_verified and fail_events == 0:
                status = _worst_status(doc_status, "pass")
            elif acceptance_report is None and readiness_report is None:
                status = _worst_status(doc_status, "pending")
            elif acceptance_ok and readiness_ok and not real_ios_verified:
                status = _worst_status(doc_status, "warn")
            else:
                status = _worst_status(doc_status, "fail")

        rows.append({
            "key": key,
            "status": status,
            "source": str(item["source"]),
            "public_signal": str(item["public_signal"]),
            "rd_decision": str(item["rd_decision"]),
            "sop_gate": str(item["sop_gate"]),
            "stop_rule": str(item["stop_rule"]),
            "current": current,
            "gui_owner": _source_action_map_gui_action(str(item["method"])),
            "method": str(item["method"]),
        })
    return rows


def xp_public_source_action_map_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts = _row_status_counts(rows)
    first_focus = _first_attention_value(rows, "key")
    return (
        f"XP source action map {stage.upper()}: "
        f"pass={counts.get('pass', 0)}, ready={counts.get('ready', 0)}, "
        f"warn={counts.get('warn', 0)}, fail={counts.get('fail', 0)}, "
        f"pending={counts.get('pending', 0)}; first_focus={first_focus}"
    )


def write_xp_public_source_action_map_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    stage: str = "p1",
    evidence_path: str | Path = "",
    refreshed_at: str = "2026-06-09",
    readiness_report: dict | None = None,
) -> Path:
    out_path = Path(path)
    real_ios_verified = bool(
        (readiness_report or {}).get("claims", {}).get("real_ios_control_verified")
    )
    lines = [
        f"# XP Public Source Action Map {stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        f"- Source refresh date: `{refreshed_at}`",
        f"- Real iOS control verified: `{real_ios_verified}`",
        "- This action map converts public XP and industry signals into R&D decisions, SOP gates, stop rules, and GUI owners. It does not write JSONL evidence and does not prove real iPhone control.",
        "",
        "## Actions",
        "",
        "| Key | Status | Public signal | R&D decision | SOP gate | Stop rule | Current local state | GUI owner | Source |",
        "|---|---|---|---|---|---|---|---|---|",
    ]
    for row in rows:
        lines.append(
            f"| {_md_cell(row.get('key', ''))} | `{_md_cell(row.get('status', ''))}` | "
            f"{_md_cell(row.get('public_signal', ''))} | {_md_cell(row.get('rd_decision', ''))} | "
            f"{_md_cell(row.get('sop_gate', ''))} | {_md_cell(row.get('stop_rule', ''))} | "
            f"{_md_cell(row.get('current', ''))} | {_md_cell(row.get('gui_owner', ''))} | "
            f"{_md_cell(row.get('source', ''))} |"
        )
    if not rows:
        lines.append("| none | `pending` | no rows built | Refresh Action Map | Refresh | Stop claims | no local state | Action Map | - |")
    lines.extend([
        "",
        "## Review Rule",
        "",
        "Start from the first fail, pending, or warn row. Use the GUI owner to open the next operational panel, then refresh this map after creating evidence or artifacts. Public-source claims stay outside Acceptance and Readiness until the same run has real-device JSONL evidence, saved artifacts, and manual observations.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


def _xp_gap_status_for_domains(xp_gap_audit: dict | None, fragments: tuple[str, ...]) -> str:
    if not isinstance(xp_gap_audit, dict):
        return ""
    rows = xp_gap_audit.get("rows", [])
    if not isinstance(rows, list):
        return ""
    matched = []
    lowered_fragments = tuple(fragment.lower() for fragment in fragments)
    for row in rows:
        if not isinstance(row, dict):
            continue
        domain = str(row.get("domain", row.get("name", "")) or "").lower()
        if any(fragment in domain for fragment in lowered_fragments):
            matched.append(str(row.get("status", "") or "").lower())
    if not matched:
        return ""
    if any(status in {"blocked", "not_started"} for status in matched):
        return "fail"
    if any(status == "partial" for status in matched):
        return "warn"
    if all(status == "pass" for status in matched):
        return "pass"
    return "warn"


