def first_run_packet_rows(
    *,
    run_id: str,
    stage: str = "p1",
    device_ids: list[str] | None = None,
    source_rows: list[dict[str, str]] | None = None,
    industry_rows: list[dict[str, str]] | None = None,
    procurement_rows: list[dict[str, str]] | None = None,
    roadmap_rows: list[dict[str, str]] | None = None,
    verification_rows: list[dict[str, str]] | None = None,
    local_rows: list[dict[str, str]] | None = None,
    core_rows: list[dict[str, str]] | None = None,
    api_coverage_rows: list[dict[str, str]] | None = None,
    script_coverage_rows: list[dict[str, str]] | None = None,
    proof_map_rows: list[dict[str, str]] | None = None,
    claim_scope_rows_data: list[dict[str, str]] | None = None,
    event_contract_rows: list[dict[str, str]] | None = None,
    route_matrix_rows: list[dict[str, str]] | None = None,
    compatibility_rows: list[dict[str, str]] | None = None,
    goal_rows: list[dict[str, str]] | None = None,
    pitfall_rows: list[dict[str, str]] | None = None,
    kit_gate_rows: list[dict[str, str]] | None = None,
    ios_sop_rows: list[dict[str, str]] | None = None,
    bench_rows: list[dict[str, str]] | None = None,
    wizard_rows: list[dict[str, str]] | None = None,
    artifact_rows: list[dict[str, str]] | None = None,
    route_report: dict | None = None,
    doctor_report: dict | None = None,
    scenario_summary: dict | None = None,
    acceptance_report: dict | None = None,
    readiness_report: dict | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
    command_queue_items: list[dict] | None = None,
) -> list[dict[str, str]]:
    """Build the first real-device run packet rows without writing evidence."""
    normalized_stage = stage.lower().strip() or "p1"
    selected_devices = [str(item).strip() for item in (device_ids or []) if str(item).strip()]
    required_devices = STAGE_DEVICE_REQUIREMENTS.get(normalized_stage, 1)
    summary = evidence_summary or {}
    status_counts = summary.get("by_status", {}) if isinstance(summary.get("by_status"), dict) else {}
    total_events = int(summary.get("total", 0) or 0)
    fail_events = int(status_counts.get("fail", 0) or 0)
    source_list = source_rows or []
    industry_list = industry_rows or []
    procurement_list = procurement_rows or []
    roadmap_list = roadmap_rows or []
    verification_list = verification_rows or []
    local_list = local_rows or []
    core_list = core_rows or []
    api_coverage_list = api_coverage_rows or []
    script_coverage_list = script_coverage_rows or []
    proof_map_list = proof_map_rows or []
    claim_scope_list = claim_scope_rows_data or []
    event_contract_list = event_contract_rows or []
    route_matrix_list = route_matrix_rows or []
    compat_list = compatibility_rows or []
    goal_list = goal_rows or []
    pitfall_list = pitfall_rows or []
    kit_list = kit_gate_rows or []
    ios_sop_list = ios_sop_rows or []
    bench_list = bench_rows or []
    wizard_list = wizard_rows or []
    artifacts = artifact_rows or []
    queue_count = len(command_queue_rows(command_queue_items or []))
    script_path = standard_probe_script(normalized_stage)
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))
    screenshot_status, screenshot_text = _acceptance_check_line(acceptance_report, "screenshot_quality")
    manual_status, manual_text = _acceptance_check_line(acceptance_report, "manual_observation")
    artifact_by_name = {
        str(row.get("name", "") or ""): row
        for row in artifacts
        if isinstance(row, dict)
    }

    def artifact_status(name: str) -> tuple[str, str]:
        row = artifact_by_name.get(name)
        if not row:
            return "pending", f"{name} not indexed"
        status = str(row.get("status", "") or "missing")
        path = str(row.get("path", "") or "")
        if status == "present":
            return "ready", f"present: {path}"
        return "pending", f"{status}: {path or name}"

    rows: list[dict[str, str]] = []

    def add(
        step: str,
        section: str,
        status: str,
        current: str,
        operator_action: str,
        artifact: str,
        stop_rule: str,
        method: str,
    ) -> None:
        rows.append({
            "step": step,
            "section": section,
            "status": status,
            "current": current,
            "operator_action": operator_action,
            "gui_action": _first_run_gui_action(method),
            "artifact": artifact,
            "stop_rule": stop_rule,
            "method": method,
        })

    scope_status = "pass" if run_id.strip() and len(selected_devices) >= required_devices else "fail"
    add(
        "1",
        "Run identity and device scope",
        scope_status,
        f"run_id={run_id or '-'}; selected={len(selected_devices)}, required={required_devices}",
        "Set one run_id, select the exact bench devices, click Prepare, and keep Record enabled.",
        "Route template path, selected device ids, and future evidence JSONL path.",
        "Stop if the operator cannot point to the physical iPhone, cable, Hub port, and run_id.",
        "prepare_live_probe_from_gui",
    )

    source_status = "ready" if source_list and industry_list and goal_list else "pending"
    source_counts = _row_status_counts(source_list)
    industry_counts = _row_status_counts(industry_list)
    goal_counts = _row_status_counts(goal_list)
    source_method = (
        "show_xp_public_source_ledger_from_gui"
        if not source_list
        else "show_industry_sop_radar_from_gui"
        if not industry_list
        else "show_gui_goal_gate_from_gui"
        if not goal_list
        else "show_xp_public_source_ledger_from_gui"
    )
    add(
        "2",
        "XP public sources, industry radar, and goal boundary",
        source_status,
        (
            f"sources={len(source_list)} rows "
            f"(warn={source_counts.get('warn', 0)}, fail={source_counts.get('fail', 0)}); "
            f"industry={len(industry_list)} rows "
            f"(warn={industry_counts.get('warn', 0)}, fail={industry_counts.get('fail', 0)}); "
            f"goals={len(goal_list)} rows "
            f"(warn={goal_counts.get('warn', 0)}, fail={goal_counts.get('fail', 0)})"
        ),
        "Review Sources, Industry, and Goals so public XP claims, mainstream-route decisions, device/iOS claims, and user goals become test work.",
        "Industry Current Snapshot, XP Public Source Ledger, GUI Industry SOP Radar, and GUI Goal Gate exports.",
        "Stop product claims if Sources/Industry/Goals still show XP parity, broad compatibility, mainstream-route, or perfect-control gaps.",
        source_method,
    )

    procurement_status = _rows_worst_status(procurement_list)
    add(
        "2B",
        "Route procurement SOP",
        procurement_status,
        industry_route_procurement_brief(procurement_list, stage=normalized_stage) if procurement_list else "route procurement SOP not built",
        "Review Procure before buying receiver, HID, iPhone, Hub, cable, SDK/package, or before calling a route product-ready.",
        "GUI Route Procurement SOP export plus Route Decision, Rx Score, XP Lab, Kit Gate, and source refresh inputs.",
        "Stop spend and route-switch decisions if vendor questions, physical bench metadata, source freshness, or evidence gates are missing.",
        "show_industry_route_procurement_from_gui",
    )

    roadmap_status = _rows_worst_status(roadmap_list)
    add(
        "3",
        "XP roadmap and R&D closure",
        roadmap_status,
        xp_roadmap_brief(roadmap_list, stage=normalized_stage) if roadmap_list else "XP roadmap not built",
        "Review Roadmap so XP public signals, industry SOP, local implementation, evidence gates, and R&D next actions become one closure plan.",
        "XP Roadmap export plus Sources, Industry, Core, Routes, Verify, Goals, and XP Gap inputs.",
        "Stop if a roadmap lane is being closed by docs, API readiness, or GUI exports without receiver/HID/iPhone evidence.",
        "show_xp_roadmap_from_gui",
    )

    add(
        "4",
        "Step-by-step verification method",
        _rows_worst_status(verification_list),
        verification_walkthrough_brief(verification_list, stage=normalized_stage) if verification_list else "verification walkthrough not built",
        "Review Verify so the operator follows P0/P1/P2/P3/P4 commands, expected results, evidence, and stop rules in order.",
        "GUI Verification Walkthrough export plus command transcript and generated reports.",
        "Stop if the team cannot reproduce the test method or if a later green row is being used to bypass an earlier fail.",
        "show_verification_walkthrough_from_gui",
    )

    add(
        "5",
        "Local command verification",
        _rows_worst_status(local_list),
        local_verification_brief(local_list, stage=normalized_stage) if local_list else "local verification not built",
        "Open Local and run unittest, compileall, dependency check, Doctor, route-aware Doctor, scenario dry-run, and Readiness in PowerShell.",
        "GUI Local Verification export plus terminal transcript for the same run_id.",
        "Stop before receiver/HID work if local commands fail or differ from GUI state; local success still does not prove iPhone control.",
        "show_local_verification_from_gui",
    )

    add(
        "6",
        "XP core function coverage",
        _rows_worst_status(core_list),
        xp_core_function_matrix_brief(core_list, stage=normalized_stage) if core_list else "XP core function matrix not built",
        "Review Core so API/helper, receiver, HID, screenshot, calibration, vision, script, GUI, observability, and ops scopes are separated.",
        "XP Core Function Matrix export plus XP Gap Audit.",
        "Stop XP core parity claims if receiver/HID/manual/Readiness gates are not field-proven, even when API/SDK rows look ready.",
        "show_xp_core_function_matrix_from_gui",
    )

    if api_coverage_list:
        api_coverage_status = _rows_worst_status(api_coverage_list)
        api_coverage_text = xp_api_coverage_board_brief(api_coverage_list, stage=normalized_stage)
    else:
        api_coverage_status, api_coverage_text = artifact_status("XP API Coverage Board")
    add(
        "6B",
        "XP API/SDK coverage boundary",
        api_coverage_status,
        api_coverage_text,
        "Open API Cov to inspect every XP fun/helper domain as local coverage, field gate, scaffolding, or backlog.",
        "XP API Coverage Board export plus XP API compatibility tests and Events/Core review.",
        "Stop API/SDK parity claims if local tests are being counted as receiver, HID, iPhone, cloud, or XP hardware evidence.",
        "show_xp_api_coverage_board_from_gui",
    )

    if script_coverage_list:
        script_coverage_status = _rows_worst_status(script_coverage_list)
        script_coverage_text = script_coverage_board_brief(script_coverage_list, stage=normalized_stage)
    else:
        script_coverage_status, script_coverage_text = artifact_status("GUI Script Coverage Board")
    add(
        "6C",
        "Scenario/script coverage guard",
        script_coverage_status,
        script_coverage_text,
        "Open Script Cov to verify stage scripts, dry-run, real-run guard, lane evidence, metrics, group scripts, and claim boundaries.",
        "GUI Script Coverage Board export plus Scenario Library, Real-run Guard, runner summary, and Evidence Pack.",
        "Stop script or group-control claims if dry-run, queue success, or API success is being counted as real iPhone evidence.",
        "show_script_coverage_board_from_gui",
    )

    if proof_map_list:
        proof_map_status = _rows_worst_status(proof_map_list)
        proof_map_text = acceptance_proof_map_brief(proof_map_list, stage=normalized_stage)
    else:
        proof_map_status, proof_map_text = artifact_status("Acceptance Proof Map")
    add(
        "6D",
        "Acceptance proof map",
        proof_map_status,
        proof_map_text,
        "Open Proof Map to connect route, Doctor, screenshot, lane Manual, metrics, Acceptance, Readiness, and claim boundary to exact evidence.",
        "Acceptance Proof Map export plus Acceptance, Gap, Readiness, Ctrl Ledger, Matrix, and Evidence Pack.",
        "Stop handoff if a gate is being closed by dry-run, API success, generic Manual, or present markdown instead of same-run field evidence.",
        "show_acceptance_proof_map_from_gui",
    )

    if claim_scope_list:
        claim_scope_status = _rows_worst_status(claim_scope_list)
        claim_scope_text = claim_scope_brief(claim_scope_list, stage=normalized_stage)
    else:
        claim_scope_status, claim_scope_text = artifact_status("Claim Scope Board")
    add(
        "6E",
        "Claim scope and handoff wording",
        claim_scope_status,
        claim_scope_text,
        "Open Claim Scope before demo or handoff so allowed and forbidden claims match the current evidence gates.",
        "Claim Scope Board export plus Proof Map, Goal Gate, Acceptance, Readiness, Evidence Pack, and exact blocker list.",
        "Stop any handoff if P0/GUI/API/source progress is being worded as real iPhone control, group control, XP hardware parity, or broad compatibility.",
        "show_claim_scope_from_gui",
    )

    event_contract_status = _rows_worst_status(event_contract_list)
    add(
        "7",
        "XP event/error contract",
        event_contract_status,
        xp_event_error_contract_brief(event_contract_list, stage=normalized_stage) if event_contract_list else "XP event/error contract not built",
        "Open Events so API envelope, WebSocket/msgid, callbacks, receiver/HID/capture errors, log ingestion, and claim boundary share one contract.",
        "XP Event/Error Contract export plus Callback Monitor, Attach Log, Problems, Timeline, and Triage.",
        "Stop reruns and SDK parity claims if callbacks, logs, API errors, or failure categories are not tied to evidence for the same run_id.",
        "show_xp_event_error_contract_from_gui",
    )

    route_matrix_status = _rows_worst_status(route_matrix_list)
    add(
        "8",
        "Mainstream route matrix",
        route_matrix_status,
        mainstream_route_matrix_brief(route_matrix_list, stage=normalized_stage) if route_matrix_list else "mainstream route matrix not built",
        "Review Routes so the current receiver/HID choice matches the XP-style black-box control strategy and rejects auxiliary-only lanes.",
        "GUI Mainstream Route Matrix export plus Route Decision JSON/report.",
        "Stop P1 if no receiver lane and no HID lane are selected, or if WDA/MDM-style helper routes are being counted as control proof.",
        "show_mainstream_route_matrix_from_gui",
    )

    rx_score_status, rx_score_text = artifact_status("Receiver Candidate Scorecard")
    add(
        "9",
        "Receiver lane scorecard",
        rx_score_status,
        rx_score_text,
        "Open Rx Score and choose one receiver lane: UxPlay, Windows receiver, wired projection, or capture card.",
        "Receiver Candidate Scorecard export and selected-lane rationale.",
        "Stop receiver work if the selected lane is fail, lacks a written reason, or mixes evidence from another route/run_id.",
        "show_receiver_candidate_scorecard_from_gui",
    )

    rx_bootstrap_status, rx_bootstrap_text = artifact_status("Receiver Route Bootstrap")
    add(
        "10",
        "Receiver route bootstrap draft",
        rx_bootstrap_status,
        rx_bootstrap_text,
        "Use Rx Bootstrap when the selected lane is Windows receiver, wired projection, or capture card; fill real path/version/display/window/capture fields.",
        "Receiver bootstrap markdown and receiver-focused Route Decision draft.",
        "Stop if bootstrap is treated as P1 readiness; it must keep allowed_to_run_p1=false until HID/iPhone/bench evidence is filled.",
        "show_receiver_bootstrap_from_gui",
    )

    rx_setup_status, rx_setup_text = artifact_status("Receiver Setup Wizard")
    add(
        "11",
        "Receiver setup and binding split",
        rx_setup_status,
        rx_setup_text,
        "Open Rx Setup, follow the selected receiver lane, copy commands, and bind AirPlay/display/capture/window before Doctor and Shot Bench.",
        "Receiver Setup Wizard export plus receiver logs/window binding notes.",
        "Stop HID tests if receiver setup cannot prove the correct live window/display for the selected iPhone.",
        "show_receiver_setup_wizard_from_gui",
    )

    pitfall_status = _rows_worst_status(pitfall_list)
    add(
        "12",
        "Pitfall risk library",
        pitfall_status,
        pitfall_library_brief(pitfall_list, stage=normalized_stage) if pitfall_list else "pitfall library not built",
        "Review Pitfalls so receiver, HID, calibration, vision, group, performance, business-state, and claim-boundary risks have a first probe.",
        "GUI Pitfall Library export plus Issue Triage rows when failures already exist.",
        "Stop reruns if a known pitfall has no artifact, category, first probe, or stop rule.",
        "show_pitfall_library_from_gui",
    )

    compat_status = _rows_worst_status(compat_list)
    compat_focus = _first_attention_value(compat_list, "coverage_key")
    add(
        "13",
        "Device/iOS coverage",
        compat_status,
        f"{device_ios_compatibility_brief(compat_list, stage=normalized_stage) if compat_list else 'compat matrix not built'}; first_focus={compat_focus}",
        "Confirm the current iPhone model and iOS version are covered locally; do not inherit website compatibility claims.",
        "Device/iOS Compatibility Matrix and component metadata evidence.",
        "Stop if model/iOS is unknown, not covered, or belongs to another device row.",
        "show_device_ios_compatibility_from_gui",
    )

    kit_status = _rows_worst_status(kit_list)
    add(
        "14",
        "Field kit gate",
        kit_status,
        f"{field_kit_gate_brief(kit_list, stage=normalized_stage) if kit_list else 'field kit gate not built'}; first_stop={_first_attention_value(kit_list, 'gate', statuses={'fail', 'pending'})}",
        "Open Kit Gate and confirm procurement/SOP docs, receiver, HID, iPhone settings, Hub/cable/network, evidence plan, Route, and Doctor are ready.",
        "Field Kit Gate export and Route/Doctor artifacts for this run_id.",
        "Stop before real HID actions unless Open P1 stop line is pass; XP hardware comparison warn still blocks XP parity claims.",
        "show_field_kit_gate_from_gui",
    )

    ios_sop_status = _rows_worst_status(ios_sop_list)
    add(
        "15",
        "iPhone settings SOP",
        ios_sop_status,
        ios_field_sop_brief(ios_sop_list, stage=normalized_stage) if ios_sop_list else "iOS field settings SOP not built",
        "Open iOS SOP and confirm device identity, AssistiveTouch, rotation lock, AssistiveTouch menu, keyboard/mouse access, mouse parameter profile, QR scan policy, lock/brightness, AirPlay/network, Hub/Cable, and baseline artifacts.",
        "iOS Field Settings SOP export plus Route Decision iPhone fields and operator worksheet notes.",
        "Stop before receiver/HID reruns if any physical setting is unknown, copied from another phone, or not reproducible by a second operator.",
        "show_ios_field_sop_from_gui",
    )

    if route_report is None:
        route_status = "pending"
        route_text = "route decision not loaded"
    else:
        route_status = "pass" if route_report.get("ok") and route_report.get("ready") else "fail"
        route_text = route_decision_brief(route_report)
    if doctor_report is None:
        doctor_status = "pending"
        doctor_text = "doctor not run"
    else:
        overall = str(doctor_report.get("overall", "") or "").lower()
        doctor_status = "pass" if overall == "ok" else "warn" if overall == "warn" else "fail"
        doctor_text = doctor_brief(doctor_report)
    bench_status = _worst_status(route_status, doctor_status, _rows_worst_status(bench_list))
    add(
        "16",
        "Route, doctor, and hardware bench",
        bench_status,
        f"{route_text}; {doctor_text}; bench_first={_first_attention_value(bench_list, 'check')}",
        "Fill real receiver/HID/iPhone/Hub/cable/operator values, validate route, run route-aware Doctor, open Receiver, and inspect Bench.",
        "Route JSON/report, Doctor report, Receiver Route Gate, Hardware Bench export, and component metadata.",
        "Stop before any real HID action if route is not ready, Doctor fails, or Bench has unexplained gaps.",
        "show_receiver_route_gate_from_gui",
    )

    wizard_status = _rows_worst_status(wizard_list)
    add(
        "17",
        "Ordered field evidence sequence",
        wizard_status,
        f"{field_evidence_wizard_brief(wizard_list, stage=normalized_stage) if wizard_list else 'wizard not built'}",
        "Follow Wizard from the first fail/pending/warn row; do not jump directly to scripts.",
        "Field Evidence Wizard export plus the artifacts named in each row.",
        "Stop when any Wizard row is fail, pending, or unexplained warn.",
        "show_field_evidence_wizard_from_gui",
    )

    runner_status, runner_text = artifact_status("Field Evidence Runner")
    add(
        "18",
        "Field evidence runner",
        runner_status,
        runner_text,
        "Open Runner to track route, Doctor, screenshot, click, swipe, text, Acceptance, Readiness, and handoff commands for the same run_id.",
        "Field Evidence Runner export plus copy-ready terminal commands.",
        "Stop if Runner marks any control lane, Acceptance, Readiness, or claim boundary as fail/pending/unexplained warn.",
        "show_field_evidence_runner_from_gui",
    )

    ledger_status, ledger_text = artifact_status("Control Evidence Ledger")
    add(
        "18B",
        "Lane-separated control ledger",
        ledger_status,
        ledger_text,
        "Open Ctrl Ledger before closing P1 control proof; click, swipe, and text must each have their own Manual pass row.",
        "Control Evidence Ledger export plus JSONL action-specific Manual rows and artifacts.",
        "Stop if a generic Manual pass is being used to close more than one real-control lane.",
        "show_control_evidence_ledger_from_gui",
    )

    control_status = _worst_status(
        "pass" if evidence_exists and total_events > 0 and fail_events == 0 else "fail",
        screenshot_status,
        manual_status,
    )
    if control_status == "pass" and not real_ios_verified:
        control_status = "warn"
    add(
        "19",
        "Real iPhone control proof",
        control_status,
        (
            f"events={total_events}, fail={fail_events}; "
            f"screenshot={screenshot_text}; manual={manual_text}; real_ios_verified={real_ios_verified}"
        ),
        "Use Shot Bench for repeated screenshots, then P1 Trial for click, swipe, and text while watching the real iPhone.",
        "JSONL screenshot_quality, capture artifacts, manual observations, screenshots/recordings, and failure categories.",
        "Stop if API success is not matched by visible real-iPhone behavior.",
        "show_p1_trial_from_gui" if normalized_stage == "p1" else "show_field_runbook_from_gui",
    )

    if scenario_summary:
        scenario_status = "pass" if scenario_summary.get("ok") else "fail"
        scenario_current = scenario_brief(scenario_summary)
        scenario_method = "run_acceptance_from_gui" if scenario_summary.get("ok") else "write_acceptance_gap_from_gui"
    elif queue_count:
        scenario_status = "ready"
        scenario_current = command_queue_brief(command_queue_items or [])
        scenario_method = "run_command_queue_from_gui"
    else:
        scenario_status = "pending"
        scenario_current = f"default={script_path}; no dry-run summary or GUI queue result"
        scenario_method = "load_probe_script_from_gui"
    add(
        "20",
        "Repeatable script path",
        scenario_status,
        scenario_current,
        "Load the stage probe script or save a GUI queue, dry-run first, then run real only after guard checks.",
        "Scenario summary, GUI queue JSON, real-run guard, and later real-run JSONL events.",
        "Stop if the path cannot be replayed with the same run_id, route, devices, and edited safe coordinates.",
        scenario_method,
    )

    required_missing = [
        row.get("name", "")
        for row in artifacts
        if row.get("requirement") == "required" and row.get("status") != "present"
    ]
    recommended_missing = [
        row.get("name", "")
        for row in artifacts
        if row.get("requirement") == "recommended" and row.get("status") != "present"
    ]
    artifact_status = (
        "pending"
        if not artifacts
        else "fail"
        if required_missing
        else "warn"
        if recommended_missing
        else "pass"
    )
    add(
        "21",
        "Evidence pack exports",
        artifact_status,
        (
        f"artifacts={len(artifacts)}, required_missing={len(required_missing)}, "
            f"recommended_missing={len(recommended_missing)}"
        ),
        "Export Pack, Start Pack, Runbook, Worksheet, Industry Current Snapshot, Procure, Sources, Source Refresh, Action Map, Iter Radar, XP Timeline, XP Drill, XP Arch, XP Lab, Industry, Roadmap, Verify, Local, Core, API Cov, Script Cov, Proof Map, Claim Scope, Events, Routes, Compat, Goals, Kit Gate, iOS SOP, Bench, Wizard, Rerun, Recovery, XP Gap, and Session.",
        "Evidence Pack index and all recommended SOP/GUI markdown artifacts.",
        "Stop review if required artifacts are missing; present markdown still does not prove control.",
        "write_evidence_pack_from_gui",
    )

    if acceptance_report is None:
        acceptance_status = "pending"
        acceptance_text = "acceptance not evaluated"
    else:
        acceptance_status = "pass" if acceptance_report.get("ok") else "fail"
        acceptance_text = acceptance_brief(acceptance_report)
    if readiness_report is None:
        readiness_status = "pending"
        readiness_text = "readiness not evaluated"
    else:
        readiness_status = "pass" if readiness_report.get("ok") else "fail"
        readiness_text = readiness_brief(readiness_report)
    gate_status = _worst_status(acceptance_status, readiness_status)
    if gate_status == "pass" and not real_ios_verified:
        gate_status = "warn"
    add(
        "22",
        "Acceptance, readiness, and handoff",
        gate_status,
        f"{acceptance_text}; {readiness_text}; real_ios_verified={real_ios_verified}",
        "Run Acceptance, Gap if needed, Readiness, Dashboard, Session, and hand off only evidence-backed claims.",
        "Acceptance report, Gap report, Readiness report, Stage Dashboard, GUI Session Snapshot.",
        "Stop any statement of iOS perfect control unless Acceptance, Readiness, JSONL, and manual evidence all agree.",
        "run_readiness_audit" if gate_status != "fail" else "write_acceptance_gap_from_gui",
    )

    add(
        "23",
        "Local command replay",
        "ready",
        f"script={script_path}; evidence=evidence/{ValidationRecorder(run_id).safe_run_id}.jsonl",
        "Use the Local board and shell commands in the exported packet when the GUI result needs a second-person reproduction.",
        "Command transcript, GUI Local Verification export, and generated markdown reports.",
        "Stop if command output differs from GUI state; attach both outputs before changing code.",
        "show_local_verification_from_gui",
    )
    return rows


def first_run_packet_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts = _row_status_counts(rows)
    first_focus = _first_attention_value(rows, "section")
    return (
        f"First run packet {stage.upper()}: "
        f"pass={counts.get('pass', 0)}, ready={counts.get('ready', 0)}, "
        f"warn={counts.get('warn', 0)}, fail={counts.get('fail', 0)}, "
        f"pending={counts.get('pending', 0)}; first_focus={first_focus}"
    )


def write_first_run_packet_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    stage: str = "p1",
    evidence_path: str | Path = "",
    route_decision_path: str | Path = "",
    readiness_report: dict | None = None,
) -> Path:
    out_path = Path(path)
    normalized_stage = stage.lower().strip() or "p1"
    recorder = ValidationRecorder(run_id)
    safe_run_id = recorder.safe_run_id
    script_path = standard_probe_script(normalized_stage)
    real_ios_verified = bool(
        (readiness_report or {}).get("claims", {}).get("real_ios_control_verified")
    )
    evidence_text = str(evidence_path or Path("evidence") / f"{safe_run_id}.jsonl")
    route_text = str(route_decision_path or Path("evidence") / f"{safe_run_id}_route_decision.json")
    lines = [
        f"# GUI First Run Packet {normalized_stage.upper()}",
        "",
        f"- Run ID: `{safe_run_id}`",
        f"- Evidence: `{evidence_text}`",
        f"- Route Decision: `{route_text}`",
        f"- Real iOS control verified: `{real_ios_verified}`",
        "- This start packet is an operator guide. It does not write evidence and does not prove real iPhone response.",
        "",
        "## GUI Steps",
        "",
        "| # | Section | Status | Current | Operator action | GUI action | Artifact | Stop rule |",
        "|---|---|---|---|---|---|---|---|",
    ]
    for row in rows:
        lines.append(
            f"| {_md_cell(row.get('step', ''))} | {_md_cell(row.get('section', ''))} | "
            f"`{_md_cell(row.get('status', ''))}` | {_md_cell(row.get('current', ''))} | "
            f"{_md_cell(row.get('operator_action', ''))} | {_md_cell(row.get('gui_action', ''))} | "
            f"{_md_cell(row.get('artifact', ''))} | {_md_cell(row.get('stop_rule', ''))} |"
        )
    if not rows:
        lines.append("| - | none | `pending` | no rows built | Refresh Start Pack | - | - | Do not promote |")

    lines.extend([
        "",
        "## Exact Local Commands",
        "",
        "```powershell",
        "cd D:\\codex-projects\\imouse-clone",
        ".\\.venv\\Scripts\\python -m imouse.gui",
        ".\\.venv\\Scripts\\python -m unittest discover -s tests -v",
        ".\\.venv\\Scripts\\python -m compileall -q imouse tests",
        ".\\.venv\\Scripts\\python -m imouse.main --check",
        "# Optional when using windows_receiver/wired/capture_card instead of UxPlay:",
        f".\\.venv\\Scripts\\python -m imouse.receiver_bootstrap --run-id {safe_run_id} --route windows_receiver --receiver-path \"C:\\Path\\ReceiverX\\receiverx.exe\" --receiver-name ReceiverX --airplay-name imouse-dev-01 --window-title imouse-dev-01 --window-process receiverx.exe --output {route_text} --markdown evidence\\{safe_run_id}_{normalized_stage}_receiver_bootstrap.md",
        f".\\.venv\\Scripts\\python -m imouse.doctor --json",
        f".\\.venv\\Scripts\\python -m imouse.doctor --route-decision {route_text} --json",
        f".\\.venv\\Scripts\\python -m imouse.script_runner {script_path} --dry-run --run-id {safe_run_id}",
        f".\\.venv\\Scripts\\python -m imouse.acceptance {evidence_text} --gate {normalized_stage} --markdown evidence\\{safe_run_id}_{normalized_stage}_acceptance.md",
        f".\\.venv\\Scripts\\python -m imouse.acceptance {evidence_text} --gate {normalized_stage} --gap-markdown evidence\\{safe_run_id}_{normalized_stage}_gap.md",
        f".\\.venv\\Scripts\\python -m imouse.readiness --target {normalized_stage} --evidence {evidence_text}",
        "```",
        "",
        "Real-run command is intentionally not first in the packet. Use it only after Route, Doctor, Bench, Wizard, and Real-run Guard are clean:",
        "",
        "```powershell",
        f".\\.venv\\Scripts\\python -m imouse.script_runner {script_path} --run-id {safe_run_id}",
        "```",
        "",
        "## Claim Boundary",
        "",
        "A PASS-looking GUI row is still not a product claim. Only JSONL evidence, screenshot quality, manual real-iPhone observations, Acceptance PASS, Readiness PASS, and clean failure triage can support a stage claim.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


