    def _apply_server_url(self) -> None:
        self.client = XpApiClient(self.server_url.get().strip())
        self._log(f"Using server {self.client.base_url}")

    def _run_api(
        self,
        label: str,
        func: Callable[[], Any],
        on_success: Callable[[Any], None] | None = None,
        *,
        record_success: bool = True,
        record_error: bool = True,
    ) -> None:
        def worker() -> None:
            try:
                result = func()
            except XpApiError as exc:
                self.ui_queue.put(("error", (label, f"{label} failed: {exc}", record_error)))
                return
            except Exception as exc:
                self.ui_queue.put(("error", (label, f"{label} failed: {type(exc).__name__}: {exc}", record_error)))
                return
            self.ui_queue.put(("success", (label, result, on_success, record_success)))

        threading.Thread(target=worker, daemon=True).start()

    def _drain_ui_queue(self) -> None:
        try:
            while True:
                kind, payload = self.ui_queue.get_nowait()
                if kind == "error":
                    if isinstance(payload, tuple):
                        if len(payload) == 3:
                            label, message, record_error = payload
                        else:
                            label, message = payload
                            record_error = True
                    else:
                        label, message = "Operation", str(payload)
                        record_error = True
                    self._log(message)
                    if record_error:
                        self._record_evidence(label, "fail", {"error": message})
                    messagebox.showerror("iMouse", message)
                elif kind == "success":
                    if len(payload) == 4:
                        label, result, callback, record_success = payload
                    else:
                        label, result, callback = payload
                        record_success = True
                    status = self._success_evidence_status(label, result)
                    status_text = "OK" if status == "pass" else status.upper()
                    self._log(f"{label} {status_text}: {self._shorten(result)}")
                    if record_success:
                        self._record_evidence(label, status, result)
                    if callback:
                        callback(result)
        except queue.Empty:
            pass
        self.after(100, self._drain_ui_queue)

    def _success_evidence_status(self, label: str, result: Any) -> str:
        if label == "Preflight doctor" and isinstance(result, dict):
            report = result.get("report")
            if isinstance(report, dict):
                overall = str(report.get("overall", "")).lower()
                if overall == "fail":
                    return "fail"
                if overall == "warn":
                    return "info"
        if label.startswith("Scenario") and isinstance(result, dict):
            summary = result.get("summary")
            if isinstance(summary, dict) and summary.get("ok") is False:
                return "fail"
        if label.startswith("Command queue") and isinstance(result, dict):
            summary = result.get("summary")
            if isinstance(summary, dict) and summary.get("ok") is False:
                return "fail"
        if label == "Screenshot" and isinstance(result, dict):
            quality = result.get("screenshot_quality")
            if isinstance(quality, dict) and quality.get("ok") is False:
                return "fail"
        if label == "Capture quality bench" and isinstance(result, dict):
            if result.get("ok") is False:
                return "fail"
        if label == "Readiness audit" and isinstance(result, dict):
            report = result.get("report")
            if isinstance(report, dict) and report.get("ok") is False:
                return "fail"
        return "pass"

    def _log(self, text: str) -> None:
        stamp = time.strftime("%H:%M:%S")
        self.log_text.configure(state="normal")
        self.log_text.insert("end", f"[{stamp}] {text}\n")
        self.log_text.see("end")
        self.log_text.configure(state="disabled")

    def _shorten(self, value: Any, limit: int = 500) -> str:
        text = repr(value)
        if len(text) > limit:
            return text[:limit] + "..."
        return text

    def _record_evidence(
        self,
        step: str,
        status: str,
        details: Any,
        *,
        artifacts: list[str] | None = None,
        device_ids: list[str] | None = None,
    ) -> None:
        if not self.evidence_enabled.get():
            return
        run_id = self.evidence_run_id.get().strip()
        if not run_id:
            run_id = make_run_id("gui")
            self.evidence_run_id.set(run_id)
        recorder = ValidationRecorder(run_id)
        try:
            event = recorder.append(
                step,
                status,
                device_ids=device_ids if device_ids is not None else self._evidence_device_ids(step, details),
                details=self._compact_evidence_details(details),
                artifacts=artifacts,
            )
        except Exception as exc:
            self._log(f"Evidence record failed: {exc}")
            return
        self._log(f"Evidence {event['status']}: {recorder.path}")

    def _compact_evidence_details(self, value: Any) -> Any:
        if isinstance(value, dict):
            out = {}
            for key, item in value.items():
                if key == "base64" and isinstance(item, str):
                    out[key] = f"<base64 {len(item)} chars>"
                else:
                    out[key] = self._compact_evidence_details(item)
            return out
        if isinstance(value, list):
            return [self._compact_evidence_details(item) for item in value]
        return value

    def _evidence_device_ids(self, step: str, details: Any) -> list[str]:
        ids = []
        for item in self.device_tree.selection():
            values = self.device_tree.item(item, "values")
            if values and values[0]:
                ids.append(str(values[0]))
        ids.extend(self._device_ids_from_details(details))
        project_steps = {"Refresh devices", "Refresh groups", "Scan hardware", "Readiness audit"}
        if not ids and step not in project_steps:
            selected = self.selected_device.get().strip() or self.device_id.get().strip()
            if selected:
                ids.append(selected)
        seen = set()
        unique = []
        for item in ids:
            cleaned = str(item).strip()
            if cleaned and cleaned not in seen:
                seen.add(cleaned)
                unique.append(cleaned)
        return unique

    def _device_ids_from_details(self, value: Any) -> list[str]:
        ids = []
        if isinstance(value, dict):
            for key in ("device_id", "id"):
                if value.get(key):
                    ids.append(str(value[key]))
            for key in ("device_ids", "ids"):
                items = value.get(key)
                if isinstance(items, list):
                    ids.extend(str(item) for item in items if item)
            for key in ("devices", "results"):
                items = value.get(key)
                if isinstance(items, list):
                    for item in items:
                        ids.extend(self._device_ids_from_details(item))
            group = value.get("group")
            if isinstance(group, dict):
                ids.extend(self._device_ids_from_details(group))
        elif isinstance(value, list):
            for item in value:
                ids.extend(self._device_ids_from_details(item))
        return ids

    def write_evidence_summary(self) -> None:
        run_id = self.evidence_run_id.get().strip()
        if not run_id:
            messagebox.showwarning("iMouse", "Evidence run id is required")
            return
        try:
            path = ValidationRecorder(run_id).write_summary_markdown()
        except Exception as exc:
            messagebox.showerror("iMouse", f"Evidence summary failed: {exc}")
            return
        self._log(f"Wrote evidence summary to {path}")
        messagebox.showinfo("iMouse", f"Wrote evidence summary:\n{path}")

    def write_evidence_review(self) -> None:
        run_id = self.evidence_run_id.get().strip()
        if not run_id:
            messagebox.showwarning("iMouse", "Evidence run id is required")
            return
        recorder = ValidationRecorder(run_id)
        if not recorder.path.exists():
            messagebox.showwarning("iMouse", f"Evidence file does not exist yet:\n{recorder.path}")
            return
        review_path = recorder.path.with_name(f"{recorder.safe_run_id}_review.md")
        try:
            path = recorder.write_summary_markdown(review_path)
            summary = recorder.summary()
        except Exception as exc:
            messagebox.showerror("iMouse", f"Evidence review failed: {exc}")
            return
        line = evidence_review_brief(summary)
        self._log(f"{line}; artifact={path}")
        messagebox.showinfo("iMouse", f"{line}\n{path}")

    def show_evidence_timeline_from_gui(self) -> None:
        run_id = self.evidence_run_id.get().strip()
        if not run_id:
            messagebox.showwarning("iMouse", "Evidence run id is required")
            return
        recorder = ValidationRecorder(run_id)
        if not recorder.path.exists():
            messagebox.showwarning("iMouse", f"Evidence file does not exist yet:\n{recorder.path}")
