    def run_preflight_doctor(self) -> None:
        self._apply_server_url()
        run_id = self.evidence_run_id.get().strip() or make_run_id("gui")
        self.evidence_run_id.set(run_id)
        route_text = self.route_decision_path.get().strip()
        route_path = Path(route_text) if route_text else None
        route_decision_path = route_path if route_path and route_path.exists() else None

        def worker() -> dict:
            report = run_doctor(server_url=self.client.base_url, route_decision_path=route_decision_path)
            path = write_doctor_markdown(report, Path("evidence") / f"{run_id}_doctor.md")
            return {"report": report, "artifact": str(path)}

        def on_success(result: dict) -> None:
            report = result.get("report", {})
            self._store_probe_report("doctor", report)
            line = doctor_brief(report)
            self._log(f"{line}; artifact={result.get('artifact')}")
            self.refresh_live_probe_status()
            if report.get("overall") == "fail":
                messagebox.showwarning("iMouse", f"{line}\n{result.get('artifact')}")
            else:
                messagebox.showinfo("iMouse", f"{line}\n{result.get('artifact')}")

        self._run_api("Preflight doctor", worker, on_success)

    def run_readiness_audit(self) -> None:
        run_id = self.evidence_run_id.get().strip() or make_run_id("gui")
        self.evidence_run_id.set(run_id)
        recorder = ValidationRecorder(run_id)
        evidence_path = recorder.path if recorder.path.exists() else None

        def worker() -> dict:
            report = evaluate_readiness(evidence_jsonl=evidence_path, target="p1")
            path = write_readiness_markdown(report, Path("evidence") / f"{recorder.safe_run_id}_readiness.md")
            return {"report": report, "artifact": str(path)}

        def on_success(result: dict) -> None:
            report = result.get("report", {})
            self._store_probe_report("readiness", report)
            self._store_probe_report("readiness_preview", report)
            line = readiness_brief(report)
            self._log(f"{line}; artifact={result.get('artifact')}")
            self.refresh_live_probe_status()
            if report.get("ok"):
                messagebox.showinfo("iMouse", f"{line}\n{result.get('artifact')}")
            else:
                messagebox.showwarning("iMouse", f"{line}\n{result.get('artifact')}")

        self._run_api("Readiness audit", worker, on_success)

    def _ensure_evidence_run_id(self) -> str:
        run_id = self.evidence_run_id.get().strip()
        if not run_id:
            run_id = make_run_id("gui")
            self.evidence_run_id.set(run_id)
        return run_id

    def _store_probe_report(self, key: str, report: dict) -> None:
        self.probe_reports[key] = {
            "run_id": self._ensure_evidence_run_id(),
            "report": report,
        }

    def _probe_report(self, key: str) -> dict | None:
        current_run_id = self._ensure_evidence_run_id()
        item = self.probe_reports.get(key, {})
        if item.get("run_id") != current_run_id:
            return None
        report = item.get("report")
        return report if isinstance(report, dict) else None

    def prepare_live_probe_from_gui(self) -> None:
        run_id = self._ensure_evidence_run_id()
        stage = self.field_stage.get().strip().lower() or "p1"
        self.acceptance_gate.set(stage)
        self.scenario_path.set(standard_probe_script(stage))
        self.scenario_dry_run.set(True)
        path = Path(self.route_decision_path.get().strip() or self.route_decision_file(run_id))
        try:
            if not path.exists():
                write_decision_template(path, run_id=run_id, devices=self._selected_device_ids())
            self.route_decision_path.set(str(path))
        except Exception as exc:
            messagebox.showerror("iMouse", f"Live probe prepare failed: {exc}")
            return
        self._log(
            "Live probe prepared: "
            f"stage={stage}, run_id={run_id}, route={path}, script={self.scenario_path.get()}"
        )
        self.refresh_live_probe_status()

    def load_probe_script_from_gui(self) -> None:
        stage = self.field_stage.get().strip().lower() or "p1"
        script = standard_probe_script(stage)
        self.acceptance_gate.set(stage)
        self.scenario_path.set(script)
        self.scenario_dry_run.set(True)
        self._log(f"Loaded {stage.upper()} probe script: {script}; dry_run=True")
        self.refresh_live_probe_status()

    def run_live_probe_dry_run(self) -> None:
        self.load_probe_script_from_gui()
        self.run_scenario_from_gui()

    def _live_probe_rows(self) -> list[dict[str, str]]:
        stage = self.field_stage.get().strip().lower() or "p1"
        run_id = self._ensure_evidence_run_id()
        recorder = ValidationRecorder(run_id)
        evidence_path = recorder.path
        evidence_exists = evidence_path.exists()
        evidence_summary = recorder.summary() if evidence_exists else None

        route_report = self._load_current_route_report()
        acceptance_report = None
        try:
            acceptance_report = evaluate_acceptance(evidence_path, gate=self.acceptance_gate.get().strip().lower() or stage)
        except Exception as exc:
            acceptance_report = {
                "gate": self.acceptance_gate.get().strip().lower() or stage,
                "ok": False,
                "checks": [{"name": "acceptance_error", "status": "fail", "message": str(exc)}],
            }
        readiness_report = evaluate_readiness(
            evidence_jsonl=evidence_path if evidence_exists else None,
            target=stage,
            run_doctor_check=False,
            doctor_report=self._probe_report("doctor"),
        )
        self._store_probe_report("acceptance", acceptance_report)
        self._store_probe_report("readiness_preview", readiness_report)

        return live_probe_rows(
            stage=stage,
            device_ids=self._selected_device_ids(),
            route_report=route_report,
            doctor_report=self._probe_report("doctor"),
            scenario_summary=self._probe_report("scenario"),
            acceptance_report=acceptance_report,
            readiness_report=readiness_report,
            evidence_exists=evidence_exists,
            evidence_summary=evidence_summary,
        )

    def _load_current_route_report(self) -> dict | None:
        run_id = self._ensure_evidence_run_id()
        path = Path(self.route_decision_path.get().strip() or self.route_decision_file(run_id))
        if not path.exists():
            return None
        try:
            data = load_decision(path)
            report = evaluate_decision(data, require_ready=True)
        except Exception as exc:
            return {
                "ok": False,
                "ready": False,
                "target_stage": self.field_stage.get().strip().lower() or "p1",
                "blockers": [{"name": "route_file", "message": str(exc)}],
                "checks": [],
            }
        decision_run_id = str(data.get("run_id", "") or "").strip()
        if decision_run_id and decision_run_id != run_id:
            return {
                "ok": False,
                "ready": False,
                "target_stage": self.field_stage.get().strip().lower() or "p1",
                "blockers": [{
                    "name": "route_run_id_mismatch",
                    "message": f"route run_id={decision_run_id}, current run_id={run_id}",
                }],
                "checks": [],
            }
        if decision_run_id == run_id:
            self._store_probe_report("route", report)
        return report

    def refresh_live_probe_status(self) -> None:
        if not hasattr(self, "live_probe_tree"):
            return
        try:
            rows = self._live_probe_rows()
        except Exception as exc:
            self.live_probe_status.set(f"Live probe refresh failed: {exc}")
            self._log(f"Live probe refresh failed: {exc}")
            return
        self.live_probe_tree.delete(*self.live_probe_tree.get_children())
        for row in rows:
            self.live_probe_tree.insert(
                "",
                "end",
                values=(
                    row.get("label", ""),
                    row.get("status", ""),
                    row.get("message", ""),
                    row.get("action", ""),
                ),
            )
        line = live_probe_brief(rows, stage=self.field_stage.get().strip().lower() or "p1")
        self.live_probe_status.set(line)
        self._log(line)

    def write_live_probe_report_from_gui(self) -> None:
        run_id = self._ensure_evidence_run_id()
        recorder = ValidationRecorder(run_id)
        stage = self.field_stage.get().strip().lower() or "p1"
