    def _local_verification_context(self) -> tuple[list[dict[str, str]], dict | None]:
        run_id = self._ensure_evidence_run_id()
        stage = self.field_stage.get().strip().lower() or "p1"
        recorder = ValidationRecorder(run_id)
        evidence_exists = recorder.path.exists()
        evidence_summary = recorder.summary() if evidence_exists else {}
        route_path = Path(self.route_decision_path.get().strip() or self.route_decision_file(run_id))
        route_report = self._probe_report("route") or self._load_current_route_report()
        readiness_report = self._probe_report("readiness_preview") or self._probe_report("readiness")
        if readiness_report is None:
            try:
                readiness_report = evaluate_readiness(
                    evidence_jsonl=recorder.path if evidence_exists else None,
                    target=stage,
                    run_doctor_check=False,
                    doctor_report=self._probe_report("doctor"),
                )
                self._store_probe_report("readiness_preview", readiness_report)
            except Exception:
                readiness_report = None
        rows = local_verification_rows(
            run_id=run_id,
            stage=stage,
            route_report=route_report,
            doctor_report=self._probe_report("doctor"),
            scenario_summary=self._probe_report("scenario"),
            readiness_report=readiness_report,
            evidence_exists=evidence_exists,
            evidence_summary=evidence_summary,
            route_decision_path=route_path,
        )
        return rows, readiness_report

    def show_local_verification_from_gui(self) -> None:
        stage = self.field_stage.get().strip().lower() or "p1"
        try:
            rows, _readiness_report = self._local_verification_context()
        except Exception as exc:
            messagebox.showerror("iMouse", f"Local verification failed: {exc}")
            return

        dialog = tk.Toplevel(self)
        dialog.title(f"Local Check {stage.upper()}")
        dialog.geometry("1560x560")
        dialog.minsize(1120, 420)
        dialog.columnconfigure(0, weight=1)
        dialog.rowconfigure(1, weight=1)

        status_var = tk.StringVar(value=local_verification_brief(rows, stage=stage))
        ttk.Label(dialog, textvariable=status_var, padding=(10, 8)).grid(row=0, column=0, sticky="ew")

        columns = ("step", "check", "status", "current", "command", "expected", "failure", "next", "boundary", "action")
        tree = ttk.Treeview(dialog, columns=columns, show="headings", height=10)
        for column, label, width in (
            ("step", "#", 42),
            ("check", "Check", 170),
            ("status", "Status", 80),
            ("current", "Current signal", 300),
            ("command", "PowerShell command", 380),
            ("expected", "Expected result", 310),
            ("failure", "Failure meaning", 300),
            ("next", "Next action", 280),
            ("boundary", "Boundary", 340),
            ("action", "GUI action", 150),
        ):
            tree.heading(column, text=label)
            tree.column(column, width=width, anchor="w")
        tree.grid(row=1, column=0, sticky="nsew", padx=10)
        scroll = ttk.Scrollbar(dialog, orient="vertical", command=tree.yview)
        scroll.grid(row=1, column=1, sticky="ns")
        tree.configure(yscrollcommand=scroll.set)

        footer = ttk.Frame(dialog, padding=(10, 8))
        footer.grid(row=2, column=0, columnspan=2, sticky="ew")
        row_by_item: dict[str, dict[str, str]] = {}

        def render(next_rows: list[dict[str, str]]) -> None:
            tree.delete(*tree.get_children())
            row_by_item.clear()
            for row in next_rows:
                item_id = tree.insert(
                    "",
                    "end",
                    values=(
                        row.get("step", ""),
                        row.get("check", ""),
                        row.get("status", ""),
                        row.get("current", ""),
                        row.get("command", ""),
                        row.get("expected", ""),
                        row.get("failure_meaning", ""),
                        row.get("next_action", ""),
                        row.get("boundary", ""),
                        row.get("gui_action", ""),
                    ),
                )
                row_by_item[item_id] = row
            status_var.set(local_verification_brief(next_rows, stage=stage))

        def refresh() -> None:
            try:
                refreshed, _readiness = self._local_verification_context()
            except Exception as exc:
                status_var.set(f"Local verification refresh failed: {exc}")
                self._log(f"Local verification refresh failed: {exc}")
                return
            render(refreshed)
            self._log(local_verification_brief(refreshed, stage=stage))

        def run_selected() -> None:
            selection = tree.selection()
            if not selection:
                messagebox.showwarning("iMouse", "Select one local check row first.")
                return
            row = row_by_item.get(selection[0], {})
            method_name = str(row.get("method", "") or "")
            method = getattr(self, method_name, None)
            if not callable(method):
                messagebox.showerror("iMouse", f"Local check action is not available: {method_name}")
                return
            self._log(f"Local check action {row.get('check', '')}: {row.get('gui_action', '')}")
            method()

        ttk.Button(footer, text="Run Selected", command=run_selected).pack(side="left")
        ttk.Button(footer, text="Refresh", command=refresh).pack(side="left", padx=4)
        ttk.Button(footer, text="Export", command=self.write_local_verification_from_gui).pack(side="left", padx=4)
        ttk.Button(footer, text="Verify", command=self.show_verification_walkthrough_from_gui).pack(side="left", padx=4)
        ttk.Button(footer, text="Doctor", command=self.run_preflight_doctor).pack(side="left", padx=4)
        ttk.Button(footer, text="Receiver", command=self.show_receiver_route_gate_from_gui).pack(side="left", padx=4)
        ttk.Button(footer, text="Readiness", command=self.run_readiness_audit).pack(side="left", padx=4)
        ttk.Label(
            footer,
            text="Local Check is a terminal guide; it does not run commands, write evidence, or prove real iPhone response.",
        ).pack(side="left", padx=(12, 0))
        render(rows)

