    def show_receiver_bootstrap_from_gui(self) -> None:
        run_id = self._ensure_evidence_run_id()
        recorder = ValidationRecorder(run_id)
        stage = self.field_stage.get().strip().lower() or "p1"
        default_route_path = Path(self.route_decision_path.get().strip() or self.route_decision_file(run_id))
        default_md_path = Path("evidence") / f"{recorder.safe_run_id}_{stage}_receiver_bootstrap.md"

        dialog = tk.Toplevel(self)
        dialog.title(f"Receiver Route Bootstrap {stage.upper()}")
        dialog.geometry("980x520")
        dialog.minsize(820, 440)
        dialog.columnconfigure(1, weight=1)

        fields: dict[str, tk.StringVar] = {
            "route": tk.StringVar(value="windows_receiver"),
            "receiver_path": tk.StringVar(value=""),
            "receiver_name": tk.StringVar(value=""),
            "version": tk.StringVar(value=""),
            "start_command": tk.StringVar(value=""),
            "airplay_name": tk.StringVar(value="imouse-dev-01"),
            "capture_method": tk.StringVar(value="window"),
            "window_title": tk.StringVar(value="imouse-dev-01"),
            "window_process": tk.StringVar(value=""),
            "device_id": tk.StringVar(value=(self._selected_device_ids() or ["dev_1"])[0]),
            "output": tk.StringVar(value=str(default_route_path)),
            "markdown": tk.StringVar(value=str(default_md_path)),
        }
        status_var = tk.StringVar(value="Fill a real receiver path, then write bootstrap. This does not allow P1 by itself.")

        ttk.Label(dialog, textvariable=status_var, padding=(10, 8)).grid(row=0, column=0, columnspan=3, sticky="ew")

        def add_row(row: int, label: str, key: str, *, values: tuple[str, ...] | None = None, browse: bool = False) -> None:
            ttk.Label(dialog, text=label).grid(row=row, column=0, sticky="w", padx=10, pady=4)
            if values:
                widget = ttk.Combobox(dialog, textvariable=fields[key], values=values, state="readonly")
            else:
                widget = ttk.Entry(dialog, textvariable=fields[key])
            widget.grid(row=row, column=1, sticky="ew", padx=4, pady=4)
            if browse:
                def pick() -> None:
                    selected = filedialog.askopenfilename(title=f"Select {label}")
                    if selected:
                        fields[key].set(selected)
                        if not fields["window_process"].get().strip():
                            fields["window_process"].set(Path(selected).name)
                ttk.Button(dialog, text="Browse", command=pick).grid(row=row, column=2, sticky="w", padx=4, pady=4)

        add_row(1, "Route", "route", values=("windows_receiver", "wired", "capture_card", "uxplay"))
        add_row(2, "Receiver path", "receiver_path", browse=True)
        add_row(3, "Receiver name", "receiver_name")
        add_row(4, "Version", "version")
        add_row(5, "Start command", "start_command")
        add_row(6, "AirPlay/display name", "airplay_name")
        add_row(7, "Capture method", "capture_method", values=("window", "display", "sdk", "capture_card", "wired", "other"))
        add_row(8, "Window title", "window_title")
        add_row(9, "Window process", "window_process")
        add_row(10, "Device id", "device_id")
        add_row(11, "Route decision JSON", "output")
        add_row(12, "Bootstrap Markdown", "markdown")

        footer = ttk.Frame(dialog, padding=(10, 8))
        footer.grid(row=13, column=0, columnspan=3, sticky="ew")

        def write_bootstrap() -> None:
            receiver_path = fields["receiver_path"].get().strip()
            if not receiver_path:
                messagebox.showerror("iMouse", "Receiver path is required.")
                return
            try:
                data = build_receiver_bootstrap_decision(
                    run_id=run_id,
                    route=fields["route"].get().strip(),
                    receiver_path=receiver_path,
                    receiver_name=fields["receiver_name"].get().strip(),
                    version=fields["version"].get().strip(),
                    start_command=fields["start_command"].get().strip(),
                    airplay_name=fields["airplay_name"].get().strip(),
                    capture_method=fields["capture_method"].get().strip(),
                    window_title=fields["window_title"].get().strip(),
                    window_process=fields["window_process"].get().strip(),
                    device_id=fields["device_id"].get().strip() or "dev_1",
                )
                decision_path = write_bootstrap_decision(data, fields["output"].get().strip())
                report = receiver_bootstrap_report(data)
                markdown_path = write_bootstrap_markdown(
                    report,
                    fields["markdown"].get().strip(),
                    route_decision_path=decision_path,
                )
                self.route_decision_path.set(str(decision_path))
                self._store_probe_report("route", report.get("route_decision", {}))
            except Exception as exc:
                messagebox.showerror("iMouse", f"Receiver bootstrap failed: {exc}")
                return
            line = (
                f"Receiver bootstrap: preflight={report.get('ok_for_receiver_preflight')}, "
                f"ready_for_p1={report.get('ready_for_p1')}; route={decision_path}; artifact={markdown_path}"
            )
            status_var.set(line)
            self._log(line)
            messagebox.showinfo(
                "iMouse",
                f"{line}\n\nThis bootstrap does not prove screenshot quality or real iPhone control.",
            )

        ttk.Button(footer, text="Write Bootstrap", command=write_bootstrap).pack(side="left")
        ttk.Button(footer, text="Rx Score", command=self.show_receiver_candidate_scorecard_from_gui).pack(side="left", padx=4)
        ttk.Button(footer, text="Edit Route", command=self.edit_route_decision_from_gui).pack(side="left", padx=4)
        ttk.Button(footer, text="Doctor", command=self.run_preflight_doctor).pack(side="left", padx=4)
        ttk.Button(footer, text="Receiver", command=self.show_receiver_route_gate_from_gui).pack(side="left", padx=4)
        ttk.Label(
            footer,
            text="Bootstrap only prepares receiver preflight; P1 still needs real screenshots and manual observations.",
        ).pack(side="left", padx=(12, 0))

    def _field_runbook_context(self) -> tuple[list[dict[str, str]], dict | None]:
        stage = self.field_stage.get().strip().lower() or "p1"
        run_id = self._ensure_evidence_run_id()
        recorder = ValidationRecorder(run_id)
        evidence_path = recorder.path
        evidence_exists = evidence_path.exists()
        evidence_summary = recorder.summary() if evidence_exists else None
        acceptance_report = self._probe_report("acceptance")
        if acceptance_report is None and evidence_exists:
            try:
                acceptance_report = evaluate_acceptance(evidence_path, gate=stage)
            except Exception as exc:
                acceptance_report = {
                    "gate": stage,
                    "ok": False,
                    "checks": [{
                        "name": "acceptance_error",
                        "status": "fail",
                        "message": str(exc),
                    }],
                }
        readiness_report = self._probe_report("readiness_preview") or self._probe_report("readiness")
        if readiness_report is None:
            try:
                readiness_report = evaluate_readiness(
                    evidence_jsonl=evidence_path if evidence_exists else None,
                    target=stage,
                    run_doctor_check=False,
                    doctor_report=self._probe_report("doctor"),
                )
                self._store_probe_report("readiness_preview", readiness_report)
            except Exception:
                readiness_report = None
        rows = field_runbook_rows(
            stage=stage,
            device_ids=self._selected_device_ids(),
            route_report=self._probe_report("route") or self._load_current_route_report(),
            doctor_report=self._probe_report("doctor"),
            scenario_summary=self._probe_report("scenario"),
            acceptance_report=acceptance_report,
            readiness_report=readiness_report,
            evidence_exists=evidence_exists,
            evidence_summary=evidence_summary,
            command_queue_items=self.command_queue_items,
            template_asset_rows_data=template_asset_rows("templates"),
        )
        return rows, readiness_report

