    def _p1_trial_context(self) -> tuple[list[dict[str, str]], dict | None]:
        run_id = self._ensure_evidence_run_id()
        recorder = ValidationRecorder(run_id)
        evidence_path = recorder.path
        evidence_exists = evidence_path.exists()
        evidence_summary = recorder.summary() if evidence_exists else None
        acceptance_report = self._probe_report("acceptance")
        if acceptance_report is None and evidence_exists:
            try:
                acceptance_report = evaluate_acceptance(evidence_path, gate="p1")
            except Exception as exc:
                acceptance_report = {
                    "gate": "p1",
                    "ok": False,
                    "checks": [{
                        "name": "acceptance_error",
                        "status": "fail",
                        "message": str(exc),
                    }],
                }
        readiness_report = self._probe_report("readiness_preview") or self._probe_report("readiness")
        if readiness_report is None:
            readiness_report = evaluate_readiness(
                evidence_jsonl=evidence_path if evidence_exists else None,
                target="p1",
                run_doctor_check=False,
                doctor_report=self._probe_report("doctor"),
            )
            self._store_probe_report("readiness_preview", readiness_report)
        try:
            callback_rows_data = self._callback_event_rows_from_api()
        except Exception:
            callback_rows_data = []
        rows = p1_trial_rows(
            device_ids=self._selected_device_ids(),
            route_report=self._probe_report("route") or self._load_current_route_report(),
            doctor_report=self._probe_report("doctor"),
            acceptance_report=acceptance_report,
            readiness_report=readiness_report,
            evidence_exists=evidence_exists,
            evidence_summary=evidence_summary,
            callback_rows_data=callback_rows_data,
        )
        return rows, readiness_report

    def show_p1_trial_from_gui(self) -> None:
        self.field_stage.set("p1")
        self.acceptance_gate.set("p1")
        try:
            rows, _readiness_report = self._p1_trial_context()
        except Exception as exc:
            messagebox.showerror("iMouse", f"P1 trial failed: {exc}")
            return

        dialog = tk.Toplevel(self)
        dialog.title("P1 Trial")
        dialog.geometry("1360x520")
        dialog.minsize(1040, 380)
        dialog.columnconfigure(0, weight=1)
        dialog.rowconfigure(1, weight=1)

        status_var = tk.StringVar(value=p1_trial_brief(rows))
        ttk.Label(dialog, textvariable=status_var, padding=(10, 8)).grid(row=0, column=0, sticky="ew")

        columns = ("step", "lane", "status", "operator_action", "gui_action", "evidence", "stop_rule")
        tree = ttk.Treeview(dialog, columns=columns, show="headings", height=12)
        for column, label, width in (
            ("step", "#", 42),
            ("lane", "Lane", 140),
            ("status", "Status", 80),
            ("operator_action", "Operator action", 300),
            ("gui_action", "GUI action", 260),
            ("evidence", "Evidence/status", 260),
            ("stop_rule", "Stop rule", 330),
        ):
            tree.heading(column, text=label)
            tree.column(column, width=width, anchor="w")
        tree.grid(row=1, column=0, sticky="nsew", padx=10)
        scroll = ttk.Scrollbar(dialog, orient="vertical", command=tree.yview)
        scroll.grid(row=1, column=1, sticky="ns")
        tree.configure(yscrollcommand=scroll.set)

        footer = ttk.Frame(dialog, padding=(10, 8))
        footer.grid(row=2, column=0, columnspan=2, sticky="ew")
        row_by_item: dict[str, dict[str, str]] = {}

        def render(next_rows: list[dict[str, str]]) -> None:
            tree.delete(*tree.get_children())
            row_by_item.clear()
            for row in next_rows:
                item_id = tree.insert(
                    "",
                    "end",
                    values=(
                        row.get("step", ""),
                        row.get("lane", ""),
                        row.get("status", ""),
                        row.get("operator_action", ""),
                        row.get("gui_action", ""),
                        row.get("evidence", ""),
                        row.get("stop_rule", ""),
                    ),
                )
                row_by_item[item_id] = row
            status_var.set(p1_trial_brief(next_rows))

        def selected_row() -> dict[str, str] | None:
            selection = tree.selection()
            if not selection:
                messagebox.showwarning("iMouse", "Select one P1 trial row first.")
                return None
            return row_by_item.get(selection[0], {})

        def refresh() -> None:
            try:
                refreshed, _readiness = self._p1_trial_context()
            except Exception as exc:
                status_var.set(f"P1 trial refresh failed: {exc}")
                self._log(f"P1 trial refresh failed: {exc}")
                return
            render(refreshed)
            self._log(p1_trial_brief(refreshed))

        def run_selected() -> None:
            row = selected_row()
            if not row:
                return
            method = getattr(self, row.get("method", ""), None)
            if not callable(method):
                messagebox.showerror("iMouse", f"P1 trial action is not available: {row.get('method')}")
                return
            self._log(f"P1 trial action {row.get('lane')}: {row.get('gui_action')}")
            method()

        def record_selected(status: str) -> None:
            row = selected_row()
            if not row:
                return
            lane = row.get("lane", "P1 trial")
            self.manual_step.set(f"P1 trial - {lane}")
            self.manual_status.set(status)
            if status == "fail":
                self.manual_category.set(_p1_trial_failure_category(lane))
            else:
                self.manual_category.set("")
            self.manual_note.set(
                f"{row.get('operator_action', '')}; evidence={row.get('evidence', '')}"
            )
            self.record_manual_observation()
            refresh()

        ttk.Button(footer, text="Run Selected", command=run_selected).pack(side="left")
        ttk.Button(footer, text="Record Pass", command=lambda: record_selected("pass")).pack(side="left", padx=4)
        ttk.Button(footer, text="Record Fail", command=lambda: record_selected("fail")).pack(side="left", padx=4)
        ttk.Button(footer, text="Refresh", command=refresh).pack(side="left", padx=4)
        ttk.Button(footer, text="Export", command=self.write_p1_trial_from_gui).pack(side="left", padx=4)
        ttk.Button(footer, text="Ctrl Ledger", command=self.show_control_evidence_ledger_from_gui).pack(side="left", padx=4)
        ttk.Button(footer, text="Callback", command=self.show_callback_monitor_from_gui).pack(side="left", padx=4)
        ttk.Button(footer, text="Gap", command=self.write_acceptance_gap_from_gui).pack(side="left", padx=4)
        ttk.Label(
            footer,
            text="P1 Trial guides field actions; promotion still requires JSONL evidence, Acceptance, Readiness, and real iPhone observation.",
        ).pack(side="left", padx=(12, 0))
        render(rows)

