            row = row_by_item.get(selection[0], {})
            method_name = str(row.get("method", "") or "")
            method = getattr(self, method_name, None)
            if not callable(method):
                messagebox.showerror("iMouse", f"Knowledge action is not available: {method_name}")
                return
            self._log(f"Knowledge action {row.get('topic', '')}: {row.get('gui_action', '')}")
            method()

