        ttk.Button(footer, text="XP Gap", command=self.write_xp_gap_audit_from_gui).pack(side="left", padx=4)
        ttk.Label(
            footer,
            text="Knowledge Center aligns industry/SOP guidance with GUI actions; field evidence still decides claims.",
        ).pack(side="left", padx=(12, 0))
        render(rows)

