    def _hardware_bench_context(self) -> tuple[list[dict[str, str]], dict | None]:
        run_id = self._ensure_evidence_run_id()
        stage = self.field_stage.get().strip().lower() or "p1"
        recorder = ValidationRecorder(run_id)
        evidence_exists = recorder.path.exists()
        evidence_summary = recorder.summary() if evidence_exists else {}
        route_path = Path(self.route_decision_path.get().strip() or self.route_decision_file(run_id))
        route_decision = None
        if route_path.exists():
            try:
                route_decision = load_decision(route_path)
            except Exception:
                route_decision = None

        route_report = self._probe_report("route") or self._load_current_route_report()
        acceptance_report = self._probe_report("acceptance")
        if acceptance_report is None and evidence_exists:
            try:
                acceptance_report = evaluate_acceptance(recorder.path, gate=stage)
                self._store_probe_report("acceptance", acceptance_report)
            except Exception as exc:
                acceptance_report = {
                    "gate": stage,
                    "ok": False,
                    "checks": [{
                        "name": "acceptance_error",
                        "status": "fail",
                        "message": str(exc),
                    }],
                }
        readiness_report = self._probe_report("readiness_preview") or self._probe_report("readiness")
        if readiness_report is None:
            try:
                readiness_report = evaluate_readiness(
                    evidence_jsonl=recorder.path if evidence_exists else None,
                    target=stage,
                    run_doctor_check=False,
                    doctor_report=self._probe_report("doctor"),
                )
                self._store_probe_report("readiness_preview", readiness_report)
            except Exception:
                readiness_report = None
        try:
            callback_rows = self._callback_event_rows_from_api()
        except Exception as exc:
            callback_rows = [{
                "seq": "",
                "ts": "",
                "event": "callback_unavailable",
                "device_id": "-",
                "source": "gui",
                "severity": "warn",
                "detail": str(exc),
            }]
        rows = hardware_bench_rows(
            stage=stage,
            device_ids=self._selected_device_ids(),
            route_decision=route_decision,
            route_report=route_report,
            doctor_report=self._probe_report("doctor"),
            acceptance_report=acceptance_report,
            readiness_report=readiness_report,
            evidence_exists=evidence_exists,
            evidence_summary=evidence_summary,
            callback_rows_data=callback_rows,
        )
        return rows, readiness_report

