    def _first_run_packet_context(self) -> tuple[list[dict[str, str]], dict | None]:
        run_id = self._ensure_evidence_run_id()
        stage = self.field_stage.get().strip().lower() or "p1"
        recorder = ValidationRecorder(run_id)
        evidence_exists = recorder.path.exists()
        evidence_summary = recorder.summary() if evidence_exists else {}
        route_path = Path(self.route_decision_path.get().strip() or self.route_decision_file(run_id))
        route_report = self._probe_report("route") or self._load_current_route_report()
        acceptance_report = self._probe_report("acceptance")
        if acceptance_report is None and evidence_exists:
            try:
                acceptance_report = evaluate_acceptance(recorder.path, gate=stage)
                self._store_probe_report("acceptance", acceptance_report)
            except Exception as exc:
                acceptance_report = {
                    "gate": stage,
                    "ok": False,
                    "checks": [{
                        "name": "acceptance_error",
                        "status": "fail",
                        "message": str(exc),
                    }],
                }
        readiness_report = self._probe_report("readiness_preview") or self._probe_report("readiness")
        if readiness_report is None:
            try:
                readiness_report = evaluate_readiness(
                    evidence_jsonl=recorder.path if evidence_exists else None,
                    target=stage,
                    run_doctor_check=False,
                    doctor_report=self._probe_report("doctor"),
                )
                self._store_probe_report("readiness_preview", readiness_report)
            except Exception:
                readiness_report = None
        artifact_rows = gui_evidence_pack_rows(
            run_id=run_id,
            stage=stage,
            base_dir="evidence",
            evidence_path=recorder.path,
            route_decision_path=route_path,
        )
        try:
            source_rows, _ = self._xp_public_source_ledger_context()
        except Exception:
            source_rows = []
        try:
            industry_rows, _industry_readiness = self._industry_sop_radar_context()
        except Exception:
            industry_rows = []
        try:
            procurement_rows, _procurement_readiness = self._industry_route_procurement_context()
        except Exception:
            procurement_rows = []
        try:
            roadmap_rows, _roadmap_readiness = self._xp_roadmap_context()
        except Exception:
            roadmap_rows = []
        try:
            verification_rows, _verification_readiness = self._verification_walkthrough_context()
        except Exception:
            verification_rows = []
        try:
            local_rows, _local_readiness = self._local_verification_context()
        except Exception:
            local_rows = []
        try:
            core_rows, _core_readiness = self._xp_core_function_matrix_context()
        except Exception:
            core_rows = []
        try:
            api_coverage_rows, _api_coverage_readiness = self._xp_api_coverage_board_context()
        except Exception:
            api_coverage_rows = []
        try:
            script_coverage_rows, _script_coverage_readiness = self._script_coverage_board_context()
        except Exception:
            script_coverage_rows = []
        try:
            proof_map_rows, _proof_map_readiness = self._acceptance_proof_map_context()
        except Exception:
            proof_map_rows = []
        try:
            claim_scope_rows_data, _claim_scope_readiness = self._claim_scope_context()
        except Exception:
            claim_scope_rows_data = []
        try:
            event_contract_rows, _event_readiness = self._xp_event_error_contract_context()
        except Exception:
            event_contract_rows = []
        try:
            route_matrix_rows, _route_matrix_readiness = self._mainstream_route_matrix_context()
        except Exception:
            route_matrix_rows = []
        try:
            goal_rows, _ = self._gui_goal_gate_context()
        except Exception:
            goal_rows = []
        try:
            pitfall_rows, _pitfall_readiness = self._pitfall_library_context()
        except Exception:
            pitfall_rows = []
        try:
            compatibility_rows, _compat_recorder = self._device_ios_compatibility_rows()
        except Exception:
            compatibility_rows = []
        try:
            kit_gate_rows, _kit_readiness = self._field_kit_gate_context()
        except Exception:
            kit_gate_rows = []
        try:
            ios_sop_rows, _ios_sop_readiness = self._ios_field_sop_context()
        except Exception:
            ios_sop_rows = []
        try:
            bench_rows, _bench_readiness = self._hardware_bench_context()
        except Exception:
            bench_rows = []
        try:
            wizard_rows, _wizard_readiness = self._field_evidence_wizard_context()
        except Exception:
            wizard_rows = []
        rows = first_run_packet_rows(
            run_id=run_id,
            stage=stage,
            device_ids=self._selected_device_ids(),
            source_rows=source_rows,
            industry_rows=industry_rows,
            procurement_rows=procurement_rows,
            roadmap_rows=roadmap_rows,
            verification_rows=verification_rows,
            local_rows=local_rows,
            core_rows=core_rows,
            api_coverage_rows=api_coverage_rows,
            script_coverage_rows=script_coverage_rows,
            proof_map_rows=proof_map_rows,
            claim_scope_rows_data=claim_scope_rows_data,
            event_contract_rows=event_contract_rows,
            route_matrix_rows=route_matrix_rows,
            compatibility_rows=compatibility_rows,
            goal_rows=goal_rows,
            pitfall_rows=pitfall_rows,
            kit_gate_rows=kit_gate_rows,
            ios_sop_rows=ios_sop_rows,
            bench_rows=bench_rows,
            wizard_rows=wizard_rows,
            artifact_rows=artifact_rows,
            route_report=route_report,
            doctor_report=self._probe_report("doctor"),
            scenario_summary=self._probe_report("scenario"),
            acceptance_report=acceptance_report,
            readiness_report=readiness_report,
            evidence_exists=evidence_exists,
            evidence_summary=evidence_summary,
            command_queue_items=self.command_queue_items,
        )
        return rows, readiness_report

    def show_first_run_packet_from_gui(self) -> None:
        stage = self.field_stage.get().strip().lower() or "p1"
        try:
            rows, _readiness_report = self._first_run_packet_context()
        except Exception as exc:
            messagebox.showerror("iMouse", f"First run packet failed: {exc}")
            return

        dialog = tk.Toplevel(self)
        dialog.title(f"First Run Packet {stage.upper()}")
        dialog.geometry("1480x560")
        dialog.minsize(1120, 420)
        dialog.columnconfigure(0, weight=1)
        dialog.rowconfigure(1, weight=1)

        status_var = tk.StringVar(value=first_run_packet_brief(rows, stage=stage))
        ttk.Label(dialog, textvariable=status_var, padding=(10, 8)).grid(row=0, column=0, sticky="ew")

        columns = ("step", "section", "status", "current", "operator", "gui", "artifact", "stop")
        tree = ttk.Treeview(dialog, columns=columns, show="headings", height=11)
        for column, label, width in (
            ("step", "#", 42),
            ("section", "Section", 210),
            ("status", "Status", 80),
            ("current", "Current", 300),
            ("operator", "Operator action", 360),
            ("gui", "GUI action", 150),
            ("artifact", "Artifact", 300),
            ("stop", "Stop rule", 360),
        ):
            tree.heading(column, text=label)
            tree.column(column, width=width, anchor="w")
        tree.grid(row=1, column=0, sticky="nsew", padx=10)
        scroll = ttk.Scrollbar(dialog, orient="vertical", command=tree.yview)
        scroll.grid(row=1, column=1, sticky="ns")
        tree.configure(yscrollcommand=scroll.set)

        footer = ttk.Frame(dialog, padding=(10, 8))
        footer.grid(row=2, column=0, columnspan=2, sticky="ew")
        row_by_item: dict[str, dict[str, str]] = {}

        def render(next_rows: list[dict[str, str]]) -> None:
            tree.delete(*tree.get_children())
            row_by_item.clear()
            for row in next_rows:
                item_id = tree.insert(
                    "",
                    "end",
                    values=(
                        row.get("step", ""),
                        row.get("section", ""),
                        row.get("status", ""),
                        row.get("current", ""),
                        row.get("operator_action", ""),
                        row.get("gui_action", ""),
                        row.get("artifact", ""),
                        row.get("stop_rule", ""),
                    ),
                )
                row_by_item[item_id] = row
            status_var.set(first_run_packet_brief(next_rows, stage=stage))

        def refresh() -> None:
            try:
                refreshed, _readiness = self._first_run_packet_context()
            except Exception as exc:
                status_var.set(f"First run packet refresh failed: {exc}")
                self._log(f"First run packet refresh failed: {exc}")
                return
            render(refreshed)
            self._log(first_run_packet_brief(refreshed, stage=stage))

        def run_selected() -> None:
            selection = tree.selection()
            if not selection:
                messagebox.showwarning("iMouse", "Select one first-run row first.")
                return
            row = row_by_item.get(selection[0], {})
            method_name = str(row.get("method", "") or "")
            method = getattr(self, method_name, None)
            if not callable(method):
                messagebox.showerror("iMouse", f"First-run action is not available: {method_name}")
                return
            self._log(f"First-run action {row.get('section', '')}: {row.get('gui_action', '')}")
            method()

        ttk.Button(footer, text="Run Selected", command=run_selected).pack(side="left")
        ttk.Button(footer, text="Refresh", command=refresh).pack(side="left", padx=4)
        ttk.Button(footer, text="Export", command=self.write_first_run_packet_from_gui).pack(side="left", padx=4)
        ttk.Button(footer, text="Sources", command=self.show_xp_public_source_ledger_from_gui).pack(side="left", padx=4)
        ttk.Button(footer, text="Industry", command=self.show_industry_sop_radar_from_gui).pack(side="left", padx=4)
        ttk.Button(footer, text="Procure", command=self.show_industry_route_procurement_from_gui).pack(side="left", padx=4)
        ttk.Button(footer, text="Roadmap", command=self.show_xp_roadmap_from_gui).pack(side="left", padx=4)
        ttk.Button(footer, text="iOS SOP", command=self.show_ios_field_sop_from_gui).pack(side="left", padx=4)
        ttk.Button(footer, text="Verify", command=self.show_verification_walkthrough_from_gui).pack(side="left", padx=4)
        ttk.Button(footer, text="Local", command=self.show_local_verification_from_gui).pack(side="left", padx=4)
        ttk.Button(footer, text="Core", command=self.show_xp_core_function_matrix_from_gui).pack(side="left", padx=4)
        ttk.Button(footer, text="Events", command=self.show_xp_event_error_contract_from_gui).pack(side="left", padx=4)
        ttk.Button(footer, text="Proof Map", command=self.show_acceptance_proof_map_from_gui).pack(side="left", padx=4)
        ttk.Button(footer, text="Claim Scope", command=self.show_claim_scope_from_gui).pack(side="left", padx=4)
        ttk.Button(footer, text="Routes", command=self.show_mainstream_route_matrix_from_gui).pack(side="left", padx=4)
        ttk.Button(footer, text="Compat", command=self.show_device_ios_compatibility_from_gui).pack(side="left", padx=4)
        ttk.Button(footer, text="Bench", command=self.show_hardware_bench_from_gui).pack(side="left", padx=4)
        ttk.Button(footer, text="Wizard", command=self.show_field_evidence_wizard_from_gui).pack(side="left", padx=4)
        ttk.Button(footer, text="Runner", command=self.show_field_evidence_runner_from_gui).pack(side="left", padx=4)
        ttk.Button(footer, text="Ctrl Ledger", command=self.show_control_evidence_ledger_from_gui).pack(side="left", padx=4)
        ttk.Label(
            footer,
            text="Start Pack is a step-by-step guide; JSONL evidence, Acceptance, Readiness, and manual observation decide claims.",
        ).pack(side="left", padx=(12, 0))
        render(rows)

