    def _write_capture_bench_artifact(self, encoded: Any, path: Path) -> tuple[str, str, int]:
        if not isinstance(encoded, str) or not encoded:
            return "", "missing_base64", 0
        try:
            raw = base64.b64decode(encoded)
        except Exception as exc:
            return "", f"invalid_base64: {exc}", 0
        try:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_bytes(raw)
        except Exception as exc:
            return "", str(exc), len(raw)
        return str(path), "", len(raw)

    def run_capture_quality_bench_from_gui(self) -> None:
        try:
            device_id = self._selected_device_id()
        except Exception as exc:
            messagebox.showwarning("iMouse", str(exc))
            return
        run_id = self._ensure_evidence_run_id()
        recorder = ValidationRecorder(run_id)
        stage = self.field_stage.get().strip().lower() or "p1"
        sample_goal = CAPTURE_BENCH_DEFAULT_SAMPLES
        wait_seconds = CAPTURE_BENCH_WAIT_SECONDS
        artifact_dir = recorder.path.parent / f"{recorder.safe_run_id}_artifacts"

        def worker() -> dict:
            samples: list[dict] = []
            for index in range(1, sample_goal + 1):
                started = time.perf_counter()
                sample: dict[str, Any] = {"sample": index, "device_id": device_id}
                try:
                    data = self.client.screenshot(device_id)
                    sample["elapsed_ms"] = round((time.perf_counter() - started) * 1000, 1)
                    if not isinstance(data, dict):
                        sample["error"] = f"unexpected screenshot result: {type(data).__name__}"
                        sample["screenshot_quality"] = {"ok": False, "reason": "invalid_response"}
                    else:
                        encoded = data.get("base64")
                        quality = analyze_screenshot_base64(encoded)
                        ext = str(data.get("format", "png") or "png").lower()
                        if ext not in {"png", "jpg", "jpeg"}:
                            ext = "png"
                        artifact_path = artifact_dir / (
                            f"capture_bench_{safe_token(device_id)}_{index:03d}.{ext}"
                        )
                        artifact, artifact_error, byte_count = self._write_capture_bench_artifact(
                            encoded,
                            artifact_path,
                        )
                        sample.update({
                            "screenshot_quality": quality,
                            "artifact": artifact,
                            "artifact_error": artifact_error,
                            "bytes": byte_count,
                        })
                except Exception as exc:
                    sample["elapsed_ms"] = round((time.perf_counter() - started) * 1000, 1)
                    sample["error"] = f"{type(exc).__name__}: {exc}"
                    sample["screenshot_quality"] = {"ok": False, "reason": "api_error", "error": str(exc)}
                samples.append(sample)
                if wait_seconds > 0 and index < sample_goal:
                    time.sleep(wait_seconds)
            rows = capture_quality_bench_rows(samples, device_id=device_id)
            bench_status = capture_quality_bench_status(rows, sample_goal=sample_goal)
            out_path = write_capture_quality_bench_markdown(
                rows,
                Path("evidence") / f"{recorder.safe_run_id}_{stage}_capture_bench.md",
                run_id=recorder.safe_run_id,
                stage=stage,
                device_id=device_id,
                sample_goal=sample_goal,
                evidence_path=recorder.path,
            )
            return {
                "ok": bench_status == "pass",
                "bench_status": bench_status,
                "device_id": device_id,
                "sample_goal": sample_goal,
                "wait_seconds": wait_seconds,
                "rows": rows,
                "artifact": str(out_path),
                "brief": capture_quality_bench_brief(rows, stage=stage, sample_goal=sample_goal),
                "real_ios_control_verified": False,
            }

        def on_success(result: dict) -> None:
            line = str(result.get("brief", "Capture bench finished"))
            artifact = str(result.get("artifact", ""))
            self._log(f"{line}; artifact={artifact}")
            self.refresh_live_probe_status()
            if result.get("ok"):
                messagebox.showinfo(
                    "iMouse",
                    f"{line}\n{artifact}\n\n"
                    "This proves repeated screenshot quality only, not click/swipe/text or full iOS control.",
                )
            else:
                messagebox.showwarning(
                    "iMouse",
                    f"{line}\n{artifact}\n\n"
                    "Fix receiver/capture quality before real HID actions or promotion claims.",
                )

        self._apply_server_url()
        self._run_api("Capture quality bench", worker, on_success)

