    def validate_route_decision_from_gui(self) -> None:
        run_id = self._ensure_evidence_run_id()
        path = Path(self.route_decision_path.get().strip() or self.route_decision_file(run_id))
        if not path.exists():
            messagebox.showwarning("iMouse", f"Route decision JSON does not exist:\n{path}")
            return
        try:
            data = load_decision(path)
            decision_run_id = str(data.get("run_id", "") or "").strip()
            if decision_run_id:
                self.evidence_run_id.set(decision_run_id)
                run_id = decision_run_id
            report = evaluate_decision(data, require_ready=True)
            markdown_path = write_decision_markdown(report, path.with_suffix(".md"))
            evidence_path = ValidationRecorder(run_id).path
            append_decision_evidence(data, report, evidence_path)
        except Exception as exc:
            messagebox.showerror("iMouse", f"Route decision validation failed: {exc}")
            return

        line = route_decision_brief(report)
        self._store_probe_report("route", report)
        self._log(f"{line}; artifact={markdown_path}; evidence={evidence_path}")
        self.refresh_live_probe_status()
        if report.get("ok"):
            messagebox.showinfo("iMouse", f"{line}\n{markdown_path}\n{evidence_path}")
        else:
            messagebox.showwarning(
                "iMouse",
                f"{line}\n{markdown_path}\n{evidence_path}\n\n"
                "A failed route decision was recorded; treat this run_id as blocked and use a fresh run_id after fixing blockers.",
            )

    def generate_field_packet_from_gui(self) -> None:
        run_id = self._ensure_evidence_run_id()
        stage = self.field_stage.get().strip().lower() or "p1"
        devices = self._selected_device_ids()
        recorder = ValidationRecorder(run_id)

        def worker() -> dict:
            packet = build_field_packet(
                stage=stage,
                run_id=run_id,
                devices=devices,
                evidence_jsonl=recorder.path,
            )
            path = write_field_packet_markdown(packet, Path("evidence") / f"{recorder.safe_run_id}_field_packet.md")
            return {"packet": packet, "artifact": str(path)}

        def on_success(result: dict) -> None:
            packet = result.get("packet", {})
            line = field_packet_brief(packet)
            self._log(f"{line}; artifact={result.get('artifact')}")
            readiness = packet.get("readiness", {}) if isinstance(packet, dict) else {}
            if isinstance(readiness, dict) and readiness.get("ok"):
                messagebox.showinfo("iMouse", f"{line}\n{result.get('artifact')}")
            else:
                messagebox.showwarning("iMouse", f"{line}\n{result.get('artifact')}")

        self._run_api(
            "Field packet",
            worker,
            on_success,
            record_success=False,
            record_error=False,
        )

