    def show_scenario_library_from_gui(self) -> None:
        rows = scenario_library_rows("scripts")
        dialog = tk.Toplevel(self)
        dialog.title("Scenario Library")
        dialog.geometry("1220x460")
        dialog.columnconfigure(0, weight=1)
        dialog.rowconfigure(1, weight=1)

        status_var = tk.StringVar(value=scenario_library_brief(rows))
        ttk.Label(dialog, textvariable=status_var, padding=(10, 8)).grid(row=0, column=0, sticky="ew")

        columns = ("stage", "name", "status", "steps", "actions", "devices", "groups", "dry_run", "path", "note")
        tree = ttk.Treeview(dialog, columns=columns, show="headings", height=12)
        for column, label, width in (
            ("stage", "Stage", 65),
            ("name", "Name", 220),
            ("status", "Status", 70),
            ("steps", "Steps", 65),
            ("actions", "Actions", 210),
            ("devices", "Devices", 120),
            ("groups", "Groups", 110),
            ("dry_run", "Dry-run", 105),
            ("path", "Path", 260),
            ("note", "Note", 260),
        ):
            tree.heading(column, text=label)
            tree.column(column, width=width, anchor="w")
        tree.grid(row=1, column=0, sticky="nsew", padx=10)
        scroll = ttk.Scrollbar(dialog, orient="vertical", command=tree.yview)
        scroll.grid(row=1, column=1, sticky="ns")
        tree.configure(yscrollcommand=scroll.set)

        footer = ttk.Frame(dialog, padding=(10, 8))
        footer.grid(row=2, column=0, columnspan=2, sticky="ew")
        row_by_item: dict[str, dict[str, str]] = {}

        def render(next_rows: list[dict[str, str]]) -> None:
            tree.delete(*tree.get_children())
            row_by_item.clear()
            for row in next_rows:
                item_id = tree.insert(
                    "",
                    "end",
                    values=(
                        row.get("stage", ""),
                        row.get("name", ""),
                        row.get("status", ""),
                        row.get("steps", ""),
                        row.get("actions", ""),
                        row.get("devices", ""),
                        row.get("groups", ""),
                        row.get("dry_run", ""),
                        row.get("path", ""),
                        row.get("note", ""),
                    ),
                )
                row_by_item[item_id] = row
            status_var.set(scenario_library_brief(next_rows))

        def selected_row() -> dict[str, str] | None:
            selection = tree.selection()
            if not selection:
                messagebox.showwarning("iMouse", "Select one scenario first.")
                return None
            row = row_by_item.get(selection[0], {})
            if row.get("status") != "ok":
                messagebox.showwarning("iMouse", f"Scenario is not loadable: {row.get('note', '')}")
                return None
            return row

        def use_selected() -> None:
            row = selected_row()
            if not row:
                return
            self.scenario_path.set(row.get("path", ""))
            stage = row.get("stage", "")
            if stage in {"p1", "p2", "p3", "p4"}:
                self.field_stage.set(stage)
                self.acceptance_gate.set(stage)
            self.scenario_dry_run.set(True)
            self._log(f"Loaded scenario from library: {row.get('path', '')}; dry_run=True")

        def dry_run_selected() -> None:
            row = selected_row()
            if not row:
                return
            use_selected()
            self.run_scenario_from_gui()

        def refresh() -> None:
            refreshed = scenario_library_rows("scripts")
            render(refreshed)
            self._log(scenario_library_brief(refreshed))

        ttk.Button(footer, text="Use Selected", command=use_selected).pack(side="left")
        ttk.Button(footer, text="Dry Run Selected", command=dry_run_selected).pack(side="left", padx=4)
        ttk.Button(footer, text="Refresh", command=refresh).pack(side="left", padx=4)
        ttk.Button(footer, text="Export", command=self.write_scenario_library_from_gui).pack(side="left", padx=4)
        ttk.Label(
            footer,
            text="Library always loads with Dry Run enabled; Real-run Guard controls real execution.",
        ).pack(side="left", padx=(12, 0))
        tree.bind("<Double-1>", lambda _event: use_selected())
        render(rows)

